-- ===== 226 new books =====
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Skysworn', 'Will Wight', '1959001256', 'https://assets.hardcover.app/external_data/25592191/9375c7fb9ed3a46065342f129e225463655b9f6a.jpeg', 'With his duel fast approaching, Lindon is locked away in prison.

As a Blackflame, he is too dangerous to remain free. The Skysworn, protectors of the Empire, have imprisoned him to keep him under control until the day of his promised fight arrives.

When it does, he will face Jai Long.

But a new danger approaches the Empire, closer every day. Only the Skysworn stand between the people of the land and total annihilation.

And Lindon may be forced to join them.', 292, 523, 2017, 446670, (select id from series where hardcover_id = 4968), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Marvellous Light', 'Freya Marske', '1529080894', 'https://assets.hardcover.app/external_data/3245376/fb8bf6117358b5372fd7d9ca02999ebb8b038697.jpeg', 'Red, White & Royal Blue meets Jonathan Strange & Mr Norrell in debut author Freya Marske’s A Marvellous Light, featuring an Edwardian England full of magic, contracts, and conspiracies.

Robin Blyth has more than enough bother in his life. He’s struggling to be a good older brother, a responsible employer, and the harried baronet of a seat gutted by his late parents’ excesses. When an administrative mistake sees him named the civil service liaison to a hidden magical society, he discovers what’s been operating beneath the unextraordinary reality he’s always known.

Now Robin must contend with the beauty and danger of magic, an excruciating deadly curse, and the alarming visions of the future that come with it―not to mention Edwin Courcey, his cold and prickly counterpart in the magical bureaucracy, who clearly wishes Robin were anyone and anywhere else.

Robin’s predecessor has disappeared, and the mystery of what happened to him reveals unsettling truths about the very oldest stories they’ve been told about the land they live on and what binds it. Thrown together and facing unexpected dangers, Robin and Edwin discover a plot that threatens every magician in the British Isles―and a secret that more than one person has already died to keep.', 384, 870, 2021, 449039, (select id from series where hardcover_id = 2175), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dragon Keeper', 'Robin Hobb', '0061561657', 'https://assets.hardcover.app/external_data/24742082/588283bbbe146e586023cdcea13ce82a40c1c784.jpeg', 'Guided by the great blue dragon Tintaglia, they came from the sea: a Tangle of serpents fighting their way up the Rain Wilds River, the first to make the perilous journey to the cocooning grounds in generations. Many have died along the way. With its acid waters and impenetrable forest, it is a hard place for any to survive.People are changed by the Rain Wilds, subtly or otherwise. One such is Thymara. Born with black claws and other aberrations, she should have been exposed at birth. But her father saved her and her mother has never forgiven him. Like everyone else, Thymara is fascinated by the return of dragons: it is as if they symbolise the return of hope to their war-torn world. Leftrin, captain of the liveship Tarman, also has an interest in the hatching; as does Bingtown newlywed, Alise Finbok, who has made it her life''s work to study all there is to know of dragons.But the creatures which emerge from the cocoons are a travesty of the powerful, shining dragons of old. Stunted and deformed, they cannot fly; some seem witless and bestial. Soon, they become a danger and a burden to the Rain Wilders: something must be done. The dragons claim an ancestral memory of a fabled Elderling city far upriver: perhaps there the dragons will find their true home. But Kelsingra appears on no maps and they cannot get there on their own: a band of dragon keepers, hunters and chroniclers must attend them.To be a dragon keeper is a dangerous job: their charges are vicious and unpredictable, and there are many unknown perils on the journey to a city which may not even exist...', 564, null, 2002, 384242, (select id from series where hardcover_id = 6193), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Book of Azrael', 'Amber V. Nicole', '1035414503', 'https://assets.hardcover.app/edition/31761706/066018aa6eafc83212570af0f0e8221599c5f829.jpeg', 'A thousand years ago, Dianna gave up her life in the deserts of Eoria to save her dying sister. She called upon anyone who would listen, not expecting a monster far worse than any nightmare to answer. Now she does what Kaden asks, even if that means securing an ancient relic from the very creatures that hunt her.

A King thought long dead and long forgotten. 

In the old world his name was Samkiel. In the new world it is Liam, but one title remains true throughout time. He is the World Ender, a myth to his enemies, a savior and King to those loyal to him. After the Gods War, he locked himself away, hiding from the world. He denied his crown and responsibilities, leaving the very ones who needed him most to deal with the fallout of the death of their homeworld. Now an attack on those he holds dear sends him back to the one realm he never wished to visit again and into the sights of an enemy he thought imprisoned eons ago. Now enemies older than time must put aside their differences and work together in hopes of saving both their world and every realm in between.', 752, 1275, 2022, 774035, (select id from series where hardcover_id = 205498), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Continent', 'Terry Pratchett', '180499023X', 'https://assets.hardcover.app/edition/31471075/dd7a38fc-4906-4aeb-bed5-1cfea154936b.jpg', '"If you are unfamiliar with Pratchett’s unique blend of philosophical badinage interspersed with slapstick, you are on the threshold of a mind-expanding opportunity.” —Financial Times Chaos ensues when Discworld’s deliciously hapless wizard Rincewind goes walking about in the Down Under in this wonderfully witty satire from legendary internationally bestselling author Sir Terry Pratchett. There’s big trouble at the Unseen University, Ankh-Morpork’s prestigious and only institute of higher learning. A professor is missing—and the one person who can find him is not only the most bumbling magician the school ever produced, he’s currently stranded in Fourecks, Discworld’s last (and unfinished) continent. The down-under is hot (so hot) and it’s dry (so dry)—though it’s rumored there was once this thing called The Wet, but no one believes that. Practically everything here that’s not poisonous is venomous. Discworld’s most inept wizard and his companion, Luggage, are eager to get home—but first Rincewind has to survive a pushy mystical kangaroo trickster named Scrappy and a mob of Fourecks hooligans determined to hang him. All his problems would be solved if he could just make it rain . . . for (maybe) the first time ever. And if the time-traveling professors from UU working on rescuing him can get to the right millennium . . . The Discworld books can be read in any order, but The Last Continent is the sixth book in the Wizards collection (and the 22nd Discworld book). The other books in the Wizards collection include: The Color of Magic The Light Fantastic Sourcery Eric Interesting Times Unseen Academicals', 420, 581, 1998, 446148, (select id from series where hardcover_id = 1018), 22) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ghostwater', 'Will Wight', '1959001027', 'https://assets.hardcover.app/external_data/41781621/11c17266abc9b41853ccc9e06715400c4fa99db7.jpeg', 'Long ago, the Monarch Northstrider created a world of his own.

This world, known as Ghostwater, housed some of his most valuable experiments. Now, it has been damaged by the attack of the Bleeding Phoenix, and a team of Skysworn have been sent to recover whatever they can from the dying world.

Now, Lindon must brave the depths of this new dimension, scavenging treasures and pushing his skills to new heights to compete with new enemies.

Because Ghostwater is not as empty as it seems.', 312, 556, 2018, 446392, (select id from series where hardcover_id = 4968), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Finale', 'Stephanie Garber', '9669488710', 'https://assets.hardcover.app/external_data/4225350/28ad04fbfe180fd99f34812632ac046730b5d013.jpeg', 'It’s been two months since the Fates were freed, since Legend claimed the throne for his own, and since Tella discovered the boy she fell in love with doesn’t really exist.

With lives, empires, and hearts hanging in the balance, Tella must decide if she’s going to trust Legend or a former enemy. After uncovering a secret that upends her life, Scarlett will need to do the impossible. And Legend has a choice to make that will forever change and define him.

Caraval is over, but perhaps the greatest game of all has begun. . . .', 496, 726, 2019, 461905, (select id from series where hardcover_id = 4886), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wolfsong', 'TJ Klune', '8804778067', 'https://assets.hardcover.app/edition/30707743/5dc6e609-098d-420c-8650-c2816cdb0841.jpg', 'Oxnard Matheson was twelve when his father taught him a lesson: Ox wasn’t worth anything and people would never understand him. Then his father left.

Ox was sixteen when the energetic Bennett family moved in next door, harboring a secret that would change him forever. The Bennetts are shapeshifters. They can transform into wolves at will. Drawn to their magic, loyalty, and enduring friendships, Ox feels a gulf between this extraordinary new world and the quiet life he’s known, but he finds an ally in Joe, the youngest Bennett boy.

Ox was twenty-three when murder came to town and tore a hole in his heart. Violence flared, tragedy split the pack, and Joe left town, leaving Ox behind. Three years later, the boy is back. Except now he’s a man – charming, handsome, but haunted – and Ox can no longer ignore the song that howls between them.', 528, 1121, 2016, 594241, (select id from series where hardcover_id = 6710), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Underlord', 'Will Wight', '1959001302', 'https://assets.hardcover.app/edition/30407676/9961d602-cded-41a6-a817-054605eab7a6.jpg', 'All around the world, great clans and sects prepare their disciples to fight against one another in a competition of young Underlords. Even the Blackflame Empire is drawn in, but their youth are not strong enough to compete. Yet.', 335, 572, 2019, 446593, (select id from series where hardcover_id = 4968), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Emperor''s Blades', 'Brian Staveley', '076533643X', 'https://assets.hardcover.app/edition/30405516/a99940d4bc99e203f537e022cd64ef9410a813ca.jpeg', 'The circle is closing. The stakes are high. And old truths will live again...

The Emperor has been murdered, leaving the Annurian Empire in turmoil. Now his progeny must bury their grief and prepare to unmask a conspiracy.

His son Valyn, training for the empire’s deadliest fighting force, hears the news an ocean away. He expected a challenge, but after several ‘accidents’ and a dying soldier’s warning, he realizes his life is also in danger. Yet before Valyn can take action, he must survive the mercenaries’ brutal final initiation.

Meanwhile, the Emperor’s daughter, Minister Adare, hunts her father’s murderer in the capital itself. Court politics can be fatal, but she needs justice. And Kaden, heir to an empire, studies in a remote monastery. Here, the Blank God’s disciples teach their harsh ways – which Kaden must master to unlock their ancient powers. When an imperial delegation arrives, he’s learnt enough to perceive evil intent. But will this keep him alive, as long-hidden powers make their move?', 493, 1160, 2014, 251967, (select id from series where hardcover_id = 4881), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Poison Study', 'Maria V. Snyder, Kristin Atherton', '1426824874', 'https://assets.hardcover.app/edition/15009139/221576-L.jpg', 'Yelena, about to be executed, is offered the job of food taster to the Commander of Ixia, but politics and magic keep threatening her life.', null, 835, 2005, 255623, (select id from series where hardcover_id = 5753), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Curse for True Love', 'Stephanie Garber', '8582357176', 'https://assets.hardcover.app/editions/31495337/9608193062253782.jpg', 'Evangeline Fox ventured to the Magnificent North in search of her happy ending, and it seems as if she has it. She’s married to a handsome prince and lives in a legendary castle. But Evangeline has no idea of the devastating price she’s paid for this fairytale. She doesn’t know what she has lost, and her husband is determined to make sure she never finds out. . . . but first he must kill Jacks, the Prince of Hearts.

Blood will be shed, hearts will be stolen, and true love will be put to the test in A CURSE FOR TRUE LOVE, the breathtaking conclusion to Stephanie Garber’s #1 NEW YORK TIMES bestselling Once Upon A Broken Heart trilogy
', 383, 539, 2023, 585422, (select id from series where hardcover_id = 1411), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Can''t Spell Treason Without Tea', 'Rebecca Thorne', '9798986692401', 'https://assets.hardcover.app/edition/31432239/696269df50d240db02731b843d455f8220b0f873.jpeg', 'Worn wooden floors, plants on every table, firelight drifting between the rafters… all complemented by love and good company. Thing is, Reyna works as one of the Queen’s private guards, and Kianthe is the most powerful mage in existence. Leaving their lives isn’t so easy.

But after an assassin takes Reyna hostage, she decides she’s thoroughly done risking her life for a self-centered queen. Meanwhile, Kianthe has been waiting for a chance to flee responsibility–all the better that her girlfriend is on board.

Together, they settle in Tawney, a town nestled in the icy tundra near dragon country, and open the shop of their dreams.

What follows is a cozy tale of mishaps, mysteries, and a murderous queen throwing the realm’s biggest temper tantrum. In a story brimming with hurt/comfort and quiet fireside conversations, these two women will discover just what they mean to each other… and the world.', 443, null, 2022, 552142, (select id from series where hardcover_id = 122351), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Galatea', 'Madeline Miller', '6075740058', 'https://assets.hardcover.app/external_data/59535574/d0864a2de332b94f7b5f63fc00615e473fdbffaa.jpeg', 'In ancient Greece, a skilled marble sculptor has been blessed by a goddess who has given his masterpiece—the most beautiful woman the town has ever seen—the gift of life. After marrying her, he expects Galatea to please him, to be obedience and humility personified. But she has desires of her own and yearns for independence.

In a desperate bid by her obsessive husband to keep her under control, Galatea is locked away under the constant supervision of doctors and nurses. But with a daughter to rescue, she is determined to break free, whatever the cost...', 20, null, 2013, 454383, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wintersteel', 'Will Wight', '1959001434', 'https://assets.hardcover.app/external_data/61305792/596447e16fd2dc44f20bd651c53b128ea920e336.jpeg', 'As the Uncrowned King tournament reaches its final rounds, tensions between the competing factions are higher than ever. The outcome may determine the power balance throughout the rest of the world. Each Monarch schemes to seize any advantage they can...while far away, a Dreadgod stirs. When the tournament ends, the Dreadgod will rise. Whether it will be driven back into the sea or allowed to rampage depends on the Monarchs. And on which of them is left standing.', 522, 879, 2020, 484978, (select id from series where hardcover_id = 4968), 8) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Serpent''s Shadow', 'Rick Riordan', '0141335696', 'https://assets.hardcover.app/edition/301085/324324b519e6e31156fd5ebe4efc8cd172eab72c.jpeg', 'When young magicians Carter and Sadie Kane learned how to follow the path of the ancient Egyptian gods, they knew they would have to play an important role in restoring Ma’at—order—to the world. What they didn’t know is how chaotic the world would become. The Chaos snake Apophis is loose and threatening to destroy the earth in three days’ time. The magicians are divided. The gods are disappearing, and those that remain are weak. Walt, one of Carter and Sadie’s most gifted initiates, is doomed and can already feel his life force ebbing. Zia is too busy babysitting the senile sun god, Ra, to be of much help. What are a couple of teenagers and a handful of young trainees to do?

There is, possibly, one way to stop Apophis, but it is so difficult that it might cost Carter and Sadie their lives, if it even works at all. It involves trusting the ghost of a psychotic magician not to betray them, or worse, kill them. They’d have to be crazy to try. Well, call them crazy.

With hilarious asides, memorable monsters, and an ever-changing crew of friends and foes, the excitement never lets up in The Serpent’s Shadow, a thoroughly entertaining and satisfying conclusion to the Kane Chronicles trilogy.', 448, null, 2012, 430988, (select id from series where hardcover_id = 5784), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Uncrowned', 'Will Wight', '1959001418', 'https://assets.hardcover.app/external_data/43089270/cd8bc1840d44eba4db0b800d19d309b647d8af6c.jpeg', 'Emriss Silentborn, Memory of the World.
Tiberian Arelius, the fallen Patriarch.
Akura Malice, Queen of Shadows.
Seshethkunaaz, King of Dragons.
Reigan Shen, Emperor of Lions.
Luminous Queen Sha Miara.
The Eight-Man Empire.
Northstrider.

The Monarchs, the most powerful sacred artists on Cradle, rule with unquestioned authority. They are mysterious and distant, and catching a glimpse of one is privilege enough for a lifetime.

Now, they have all gathered in one place, bringing their heirs and greatest students together for a competition to determine whose successor is the best in the world:

The Uncrowned King tournament.', 320, 572, 2019, 446607, (select id from series where hardcover_id = 4968), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Hollow', 'Krystal Sutherland', '0143796992', 'https://assets.hardcover.app/external_data/47672443/820fdcd7866f6583cfb6eb88e18d5f77ae56cfa0.jpeg', 'A New York Times Bestseller! An Instant Indie Bestseller! A dark, twisty modern fairytale where three sisters discover they are not exactly all that they seem and evil things really do go bump in the night. Iris Hollow and her two older sisters are unquestionably strange. Ever since they disappeared on a suburban street in Scotland as children only to return a month a later with no memory of what happened to them, odd, eerie occurrences seem to follow in their wake. And they''re changing. First, their dark hair turned white. Then, their blue eyes slowly turned black. They have insatiable appetites yet never gain weight. People find them disturbingly intoxicating, unbearably beautiful, and inexplicably dangerous. But now, ten years later, seventeen-year-old Iris Hollow is doing all she can to fit in and graduate high school on time--something her two famously glamourous globe-trotting older sisters, Grey and Vivi, never managed to do. But when Grey goes missing without a trace, leaving behind bizarre clues as to what might have happened, Iris and Vivi are left to trace her last few days. They aren''t the only ones looking for her though. As they brush against the supernatural they realize that the story they''ve been told about their past is unraveling and the world that returned them seemingly unharmed ten years ago, might just be calling them home.', 306, 550, 2021, 451340, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Thornhedge', 'T. Kingfisher', '6178287739', 'https://assets.hardcover.app/editions/30648254/760995913498377.jpg', 'There''s a princess trapped in a tower. This isn''t her story.

Meet Toadling. On the day of her birth, she was stolen from her family by the fairies, but she grew up safe and loved in the warm waters of faerieland. Once an adult though, the fae ask a favor of Toadling: return to the human world and offer a blessing of protection to a newborn child. Simple, right?

But nothing with fairies is ever simple.

Centuries later, a knight approaches a towering wall of brambles, where the thorns are as thick as your arm and as sharp as swords. He''s heard there''s a curse here that needs breaking, but it''s a curse Toadling will do anything to uphold…', 116, 223, 2023, 664175, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sword Catcher', 'Cassandra Clare', '1035090724', 'https://assets.hardcover.app/edition/30858000/e8b812cb7179d8c6fa782473d39dcb427032b09a.jpeg', 'Or, perhaps more accurately, the theft of a boy’s life and future. Young orphan Kellian could never have expected a grand life in the vibrant port city of Castellane if fate had not intervened, but fate did. At the tender age of 10, he is removed from his orphanage and offered a unique position: to become Sword Catcher to Conor Aurelian, Prince of Castellane and heir to its throne. Kel will be raised in luxury in the palace alongside Conor, trained and educated as befits a royal, and given every advantage in life–with one notable exception: His life will never be his own again. Bespelled to resemble Conor, Kel essentially becomes Conor for any occasions where the prince might be in danger, or at which he would rather not put in an appearance. He is Conor’s double, his shadow self, tied forever to a person he both loves and resents–and from whom he might never be free.

Eleven years on, tensions are growing–both personal and political. Conflicts with the neighboring countries are high, and Conor’s betrothal might be the only thing to calm the waters–an idea that Conor is furious about. And Kel is starting to chafe under the restrictions of his position, realizing as he grows how very many of the things he wants–like love and stability and a place to call his own–are simply not possible.  But it is not until Kel catches an assassin’s blade meant for Conor that things really begin to escalate, for it is then that he meets Lin–a young physician and a member of the only people in the world still to hold a trace of magic. An outcast from society like Kel, Lin has her own ambitions and desires, and this fateful meeting is about to set a chain of events into motion that could alter the very fabric of both of their worlds.', 624, 1404, 2023, 526083, (select id from series where hardcover_id = 65546), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Practical Magic', 'Alice Hoffman', '0606158227', 'https://assets.hardcover.app/edition/18205199/6da97a77-8ced-4198-b1e6-934491abefe9.jpg', 'For more than two hundred years, the Owens women had been blamed for everything that went wrong in their Massachusetts town. And Gillian and Sally endured that fate as well; as children, the sisters were outsiders. Their elderly aunts almost seemed to encourage the whispers of witchery, but all Gillian and Sally wanted was to escape. One would do so by marrying, the other by running away. But the bonds they shared brought them back-almost as if by magic...', 286, null, 1995, 78370, (select id from series where hardcover_id = 1495), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Moon Called', 'Patricia Briggs', '3453523733', 'https://assets.hardcover.app/edition/4875145/cd103f53ca86c35ea6197004d0f7f7b84d6d0187.jpeg', 'Mercedes Thompson, aka Mercy, is a talented Volkswagen mechanic living in the Tri-Cities area of Washington. She also happens to be a walker, a magical being with the power to shift into a coyote at will. Mercy''s next-door neighbor is a werewolf. Her former boss is a gremlin. And she''s fixing a bus for a vampire. This is the world of Mercy Thompson, one that looks a lot like ours but is populated by those things that go bump in the night. And Mercy''s connection to those things is about to get her into some serious hot water...', 473, 554, 2006, 300524, (select id from series where hardcover_id = 2360), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bloodline', 'Will Wight', '1959001078', 'https://assets.hardcover.app/external_data/686887/5d3b2f9794a52b029a3574427fdeaca6d01b8e1b.jpeg', 'It''s time to go back home.

In the years since Lindon left Sacred Valley he has attained power beyond anything his family thought possible. Now he''ll have to put those powers to the test because a Dreadgod is on its way.

Lindon and his allies set out to evacuate the valley before the arrival of the Wandering Titan but their sacred arts are weakened by an ancient curse. They''ll have to persuade the squabbling inhabitants of Sacred Valley to leave behind their home and set off into the outside world.

But it has been a long time since Lindon left and more has changed than he realized.

He has always sought power to save his family...but now he might be too late.', 418, 673, 2021, 446347, (select id from series where hardcover_id = 4968), 9) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Alchemyst', 'Michael Scott', '9022548619', 'https://assets.hardcover.app/edition/5118183/9fab4cef56331185c373b05fa2b03aff25a69db2.jpeg', 'He holds the secret that can end the world.The truth: Nicholas Flamel was born in Paris on September 28, 1330. Nearly 700 years later, he is acknowledged as the greatest Alchemyst of his day. It is said that he discovered the secret of eternal life.The records show that he died in 1418.But his tomb is empty.The legend: Nicholas Flamel lives. But only because he has been making the elixir of life for centuries. The secret of eternal life is hidden within the book he protects--the Book of Abraham the Mage. It''s the most powerful book that has ever existed. In the wrong hands, it will destroy the world. That''s exactly what Dr. John Dee plans to do when he steals it. Humankind won''t know what''s happening until it''s too late. And if the prophecy is right, Sophie and Josh Newman are the only ones with the power to save the world as we know it.Sometimes legends are true.And Sophie and Josh Newman are about to find themselves in the middle of the greatest legend of all time.From the Hardcover edition.', 400, null, 2007, 106379, (select id from series where hardcover_id = 2784), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Murtagh', 'Christopher Paolini', '9798217116904', 'https://assets.hardcover.app/edition/30713381/813b17477ab4eca3b3352ef3263e6472384a57c1.jpeg', 'The world is no longer safe for the Dragon Rider Murtagh and his dragon, Thorn. An evil king has been toppled, and they are left to face the consequences of the reluctant role they played in his reign of terror. Now they are hated and alone, exiled to the outskirts of society.

Throughout the land, hushed voices whisper of brittle ground and a faint scent of brimstone in the air—and Murtagh senses that something wicked lurks in the shadows of Alagaësia. So begins an epic journey into lands both familiar and untraveled, where Murtagh and Thorn must use every weapon in their arsenal, from brains to brawn, to find and outwit a mysterious witch. A witch who is much more than she seems.', 636, 1472, 2023, 720128, (select id from series where hardcover_id = 5464), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Empire of Gold', 'S. A. Chakraborty', '9780062678160', 'https://assets.hardcover.app/books/441041/7121098599736380.jpg', 'Daevabad has fallen.

After a brutal conquest stripped the city of its magic, Nahid leader Banu Manizheh and her resurrected commander, Dara, must try to repair their fraying alliance and stabilize a fractious, warring people.

But the bloodletting and loss of his beloved Nahri have unleashed the worst demons of Dara’s dark past. To vanquish them, he must face some ugly truths about his history and put himself at the mercy of those he once considered enemies.

Having narrowly escaped their murderous families and Daevabad’s deadly politics, Nahri and Ali, now safe in Cairo, face difficult choices of their own. While Nahri finds peace in the old rhythms and familiar comforts of her human home, she is haunted by the knowledge that the loved ones she left behind and the people who considered her a savior are at the mercy of a new tyrant. Ali, too, cannot help but look back, and is determined to return to rescue his city and the family that remains. Seeking support in his mother’s homeland, he discovers that his connection to the marid goes far deeper than expected and threatens not only his relationship with Nahri, but his very faith.

As peace grows more elusive and old players return, Nahri, Ali, and Dara come to understand that in order to remake the world, they may need to fight those they once loved . . . and take a stand for those they once hurt.', 780, 1717, 2020, 441041, (select id from series where hardcover_id = 1628), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kaikeyi', 'Vaishnavi Patel', '0759557306', 'https://assets.hardcover.app/external_data/4251764/fde26589da987776b8b770bd6f55a900a8f12451.jpeg', 'So begins Kaikeyi’s story. The only daughter of the kingdom of Kekaya, she is raised on legends of the gods: how they churned the vast ocean to obtain the nectar of immortality, how they vanquish evil and ensure the land of Bharat prospers, and how they offer powerful boons to the devout and the wise. Yet she watches as her father unceremoniously banishes her mother, listens as her own worth is reduced to how great a marriage alliance she can secure. And when she calls upon the gods for help, they never seem to hear.

Desperate for some measure of independence, she turns to the texts she once read with her mother and discovers a magic that is hers alone. With this power, Kaikeyi transforms herself from an overlooked princess into a warrior, diplomat, and most favored queen, determined to carve a better world for herself and the women around her.

But as the evil from her childhood tales threatens the cosmic order, the path she has forged clashes with the destiny the gods have chosen for her family. Kaikeyi must decide if resistance is worth the destruction it will wreak—and what legacy she intends to leave behind.', 460, 1042, 2022, 445700, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Reaper', 'Will Wight', '1713664135', 'https://assets.hardcover.app/edition/30396982/60988260b8bcfc296a037246a47cd945a37b81be.jpeg', 'Sacred Valley has been saved…at least, what’s left of it.

With his home finally secure, Lindon delves deep into the ancient labyrinth, seeking long-lost Soulsmithing knowledge and the secret to destroying the Dreadgods. Monarchs plot against him and against each other, unaware of the threats gathering in realms beyond.

Far above Lindon and the Monarchs and the Dreadgods, another war is waged. Suriel and the Abidan clash against the Mad King and his forces in a battle for the fate of many worlds.

And if it is lost, Cradle will be destroyed.', 442, 787, 2021, 446337, (select id from series where hardcover_id = 4968), 10) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Brigands & Breadknives', 'Travis Baldree', '1250437121', 'https://assets.hardcover.app/edition/31759240/421c0cd9-e93e-4738-a0fa-2577f70c0958.jpg', 'Fern has weathered the stillness and storms of a bookseller’s life for decades, but now, in the face of crippling ennui, transplants herself to the city of Thune to hang out her shingle beside a long-absent friend’s coffee shop. What could be a better pairing? Surely a charming renovation montage will cure what ails her!

If only things were so simple…

It turns out that fixing your life isn’t a one-time prospect, nor as easy as a change of scenery and a lick of paint.

A drunken and desperate night sees the rattkin waking far from home in the company of a legendary warrior surviving on inertia, an imprisoned chaos-goblin with a fondness for silverware, and an absolutely thumping hangover.

As together they fend off a rogue’s gallery of ne’er-do-wells trying to claim the bounty the goblin represents, Fern may finally reconnect with the person she actually is when there isn’t a job to get in the way.', 323, 505, 2025, 1670203, (select id from series where hardcover_id = 39578), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ink Blood Sister Scribe', 'Emma  Törzs', '0063253488', 'https://assets.hardcover.app/edition/30744370/61e190413f67fc292002040741b88a229fee617e.jpeg', 'In this spellbinding debut novel, two estranged half-sisters tasked with guarding their family’s library of magical books must work together to unravel a deadly secret at the heart of their collection—a tale of familial loyalty and betrayal, and the pursuit of magic and power.

For generations, the Kalotay family has guarded a collection of ancient and rare books. Books that let a person walk through walls or manipulate the elements—books of magic that half-sisters Joanna and Esther have been raised to revere and protect.

All magic comes with a price, though, and for years the sisters have been separated. Esther has fled to a remote base in Antarctica to escape the fate that killed her own mother, and Joanna’s isolated herself in their family home in Vermont, devoting her life to the study of these cherished volumes. But after their father dies suddenly while reading a book Joanna has never seen before, the sisters must reunite to preserve their family legacy. In the process, they’ll uncover a world of magic far bigger and more dangerous than they ever imagined, and all the secrets their parents kept hidden; secrets that span centuries, continents, and even other libraries . . .

In the great tradition of Ninth House, The Magicians, and Practical Magic, this is a suspenseful and richly atmospheric novel that draws readers into a vast world filled with mystery and magic, romance, and intrigue—and marks the debut of an extraordinary new voice in speculative fiction.', 416, 840, 2023, 679850, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Moon Over Soho', 'Ben Aaronovitch', '3423213809', 'https://assets.hardcover.app/edition/11058082/74566dc0bdc2e93b63aebe466160a64d37a9c4e1.jpeg', 'I was my dad''s vinyl-wallah: I changed his records while he lounged around drinking tea, and that''s how I know my Argo from my Tempo. And it''s why, when Dr Walid called me to the morgue to listen to a corpse, I recognised the tune it was playing. Something violently supernatural had happened to the victim, strong enough to leave its imprint like a wax cylinder recording. Cyrus Wilkinson, part-time jazz saxophonist and full-time accountant, had apparently dropped dead of a heart attack just after finishing a gig in a Soho jazz club. He wasn''t the first. No one was going to let me exhume corpses to see if they were playing my tune, so it was back to old-fashioned legwork, starting in Soho, the heart of the scene. I didn''t trust the lovely Simone, Cyrus'' ex-lover, professional jazz kitten and as inviting as a Rubens'' portrait, but I needed her help: there were monsters stalking Soho, creatures feeding off that special gift that separates the great musician from someone who can raise a decent tune. What they take is beauty. What they leave behind is sickness, failure and broken lives. And as I hunted them, my investigation got tangled up in another story: a brilliant trumpet player, Richard ''Lord'' Grant - my father - who managed to destroy his own career, twice. That''s the thing about policing: most of the time you''re doing it to maintain public order. Occasionally you''re doing it for justice. And maybe once in a career, you''re doing it for revenge.', 375, 600, 2011, 5921, (select id from series where hardcover_id = 5126), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shield of Sparrows', 'Devney Perry', '1911750003', 'https://assets.hardcover.app/editions/31526671/07a0335b-1ba0-4bab-a314-216bf3741d0d.jpg', 'Shield of Sparrows is a slow-burn, high-stakes romantasy perfect for fans of Sarah J. Maas and Rebecca Yarros―where enemies become lovers, monsters stalk a cursed realm, and a forgotten princess finds the strength to tear off her crown and become the warrior she was never meant to be.

The gods sent monsters to the five kingdoms to remind mortals they must kneel.

I’ve spent my life kneeling―to their will and to my father''s. As a princess, my only duty is to wear the crown and obey the king.

I was never meant to rule. Never meant to fight. And I was never supposed to be the daughter who sealed an ancient treaty with her own blood.

But that changed the fateful day I stepped into my father’s throne room. The day a legendary monster hunter sailed to our shores. The day a prince ruined my life.

Now I’m crossing treacherous lands beside a warrior who despises me as much as I despise him―bound to a future I didn’t choose and a husband I barely know.

Everyone wants me to be something I’m not―a queen, a spy, a sacrifice.

But what if I refused the role chosen for me? What if I made my own rules? What if there’s power in being underestimated?

And what if―for the first time―I reached for it?', 528, 1200, 2025, 1479224, (select id from series where hardcover_id = 177821), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hammer of Thor', 'Rick Riordan', '1484758595', 'https://assets.hardcover.app/editions/30400858/3273526288529774.jpg', 'It''s been six weeks since Magnus and his friends returned from defeating Fenris Wolf and the fire giants. Magnus has adjusted to life at the Hotel Valhalla—as much as a once-homeless and previously alive kid can. As a son of Frey, the god of summer, fertility, and health, Magnus doesn''t exactly fit in with the rest of Odin''s chosen warriors, but he has a few good peeps among his hallmates on floor nineteen, and he''s been dutifully training for Ragnarok along with everyone else. His days have settled into a new kind of normal.

But Magnus should have known there''s no such thing as normal in the Nine Worlds. His friends Hearthstone and Blitzen have disappeared. A new hallmate is creating chaos. According to a very nervous goat, a certain object belonging to Thor is still missing, and the thunder god''s enemies will stop at nothing to gain control of it.

Time to summon Jack, the Sword of Summer, and take action. Too bad the only action Jack seems to be interested in is dates with other magical weapons. . . .', 480, null, 2014, 58639, (select id from series where hardcover_id = 1585), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Magicians'' Guild', 'Trudi Canavan', '006057528X', 'https://assets.hardcover.app/edition/28365754/ccf0438d2f4a5f227a10b2c3bbe94871e2c19b88.jpeg', 'This year, like every other, the magicians of Imardin gather to purge the city of undesirables. Cloaked in the protection of their sorcery, they move with no fear of the vagrants and miscreants who despise them and their work--until one enraged girl, barely more than a child, hurls a stone at the hated invaders ... and effortlessly penetrates their magical shield. What the Magicians'' Guild has long dreaded has finally come to pass. There is someone outside their ranks who possesses a raw power beyond imagining, an untrained mage who must be found and schooled before she destroys herself and her city with a force she cannot yet control.', 467, null, 2001, 435121, (select id from series where hardcover_id = 6469), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('How the King of Elfhame Learned to Hate Stories', 'Holly Black, Rovina Cai', '6555872497', 'https://assets.hardcover.app/external_data/36955374/d8fb9f21cd7ffd875732ea3d09867390c1572f71.jpeg', 'Once upon a time there was a boy with a wicked tongue... Before Cardan was a cruel prince or a wicked king, he was a faerie child with a heart of stone. In this sumptuously illustrated tale, Holly Black reveals a deeper look into the dramatic life of Elfhame''s enigmatic high king. This tale includes delicious details of life before The Cruel Prince, an adventure beyond The Queen of Nothing, and familiar but pivotal moments from The Folk of the Air trilogy, told wholly from Cardan''s perspective. This new instalment in the Folk of the Air series is a return to the heart-racing romance, danger, humour and drama that enchanted readers everywhere.', 178, null, 2019, 437810, (select id from series where hardcover_id = 5470), 3.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dark Prophecy', 'Rick Riordan, John Rocco', '1509443800', 'https://assets.hardcover.app/edition/15915751/584f03623e6a79ccf6a47c83dd0d9357f1508ff7.jpeg', 'Zeus has punished his son Apollo--god of the sun, music, archery, poetry, and more--by casting him down to earth in the form of a gawky, acne-covered sixteen-year-old mortal named Lester. The only way Apollo can reclaim his rightful place on Mount Olympus is by restoring several Oracles that have gone dark. What is affecting the Oracles, and how can Apollo/Lester do anything about them without his powers? After experiencing a series of dangerous--and frankly, humiliating--trials at Camp Half-Blood, Lester must now leave the relative safety of the demigod training ground and embark on a hair-raising journey across North America. Fortunately, what he lacks in godly graces he''s gaining in new friendships--with heroes who will be very familiar to fans of the Percy Jackson and the Olympians and Heroes of Olympus series. Come along for what promises to be a harrowing, hilarious, and haiku-filled ride. . . .', 320, 752, 2017, 430995, (select id from series where hardcover_id = 1588), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dust of Dreams', 'Steven Erikson, Michael Page', '146922612X', 'https://assets.hardcover.app/edition/23479765/3916b07b075cbcf2401df781e85f5b840acee9f9.jpeg', 'On the Letherii continent the exiled Malazan army commanded by Adjunct Tavore, escorted by Brys Beddict and an elite Letherii force, begins its march into the eastern Wastelands, to fight for an unknown cause against an enemy it has never seen.', null, 2594, 2009, 446326, (select id from series where hardcover_id = 1167), 9) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wrath', 'John Gwynne', '1549102168', 'https://assets.hardcover.app/editions/30425597/680706520920766.jpeg', 'The fourth in the Faithful and the Fallen series from John Gwynne, an epic fantasy perfect for fans of George R. R. Martin, Brandon Sanderson and David Gemmell.

Events are coming to a climax in the Banished Lands, as the war reaches new heights. King Nathair has taken control of the fortress at Drassil and three of the Seven Treasures are in his possession. And together with Calidus and his ally Queen Rhin, Nathair will do anything to obtain the remaining Treasures. With all seven under his command, he can open a portal to the Otherworld. Then Asroth and his demon-horde will finally break into the Banished Lands and become flesh.

Meanwhile Corban has been taken prisoner by the Jotun, warrior giants who ride their enormous bears into battle. His warband scattered, Corban must make new allies if he hopes to survive. But can he bond with competing factions of warlike giants? Somehow he must, if he''s to counter the threat Nathair represents.

His life hangs in the balance -- and with it, the fate of the Banished Lands.', 720, 1405, 2016, 475446, (select id from series where hardcover_id = 2438), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ashes of Man', 'Christopher Ruocchio', '1803287551', 'https://assets.hardcover.app/edition/31429077/ef4bedf3-5289-4e33-8dbe-f9ba4685f107.jpg', 'The galaxy is burning.

With the Cielcin united under one banner, the Sollan Empire stands alone after the betrayal of the Commonwealth. The Prophet-King of the Cielcin has sent its armies to burn the worlds of men, and worse, there are rumors...whispers that Hadrian Marlowe is dead, killed in the fighting.

But it is not so. Hadrian survived with the help of the witch, Valka, and together they escaped the net of the enemy having learned a terrible truth: the gods that the Cielcin worship are real and will not rest until the universe is dark and cold.

What is more, the Emperor himself is in danger. The Prophet-King has learned to track his movements as he travels along the borders of Imperial space. Now the Cielcin legions are closing in, their swords poised to strike off the head of all mankind.', 723, 1354, 2022, 506937, (select id from series where hardcover_id = 6522), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ice Planet Barbarians', 'Ruby Dixon', '6070799704', 'https://assets.hardcover.app/editions/30457381/9006935926553195.jpg', 'The international publishing phenomenon Ice Planet Barbarians, now in a special print edition! Fall in love with the out-of-this-world romance between Georgie Carruthers, a human woman, and Vektal, an alien from another planet, in this expanded edition with bonus materials and an exclusive epilogue—in print only! You’d think being abducted by aliens would be the worst thing that could happen to me. And you’d be wrong. Because now the aliens are having ship trouble, and they’ve left their cargo of human women—including me—on an ice planet. We’re not equipped for life in this desolate winter wasteland. Since I’m the unofficial leader, I head out into the snow to look for help. I find help all right. A big blue horned alien introduces himself in a rather . . . startling way. Vektal says that I''m his mate, his chosen female—and that the reason his chest is purring is because of my presence. He’ll help me and my people survive, but this poses a new problem. If Vektal helps us survive, I’m not sure he’s going to want to let me go.', 317, null, 2015, 506322, (select id from series where hardcover_id = 17014), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Darkness at Sethanon', 'Raymond E. Feist', '0613292200', 'https://assets.hardcover.app/edition/30451613/58d7f31e-68de-4ec2-89e6-bcabaf22b92f.jpg', 'An evil wind blows through Midkemia. Dark legions have risen up to crush the Kingdom of the Isles and enslave it to dire magics. The final battle between Order and Chaos is abotu to begin in the ruins of the city called Sethanon.

Now Pug, the master magician sometimes known as Milamber, must undertake an awesome and perilous quest to the dawn of time to grapple with an ancient and terrible Enemy for the fate of a thousand worlds.', 480, 1261, 1986, 445968, (select id from series where hardcover_id = 1060), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hazel Wood', 'Melissa Albert', '9177811755', 'https://assets.hardcover.app/edition/30400841/2ea01d71e23e8b9c5c91ed051ce86836e3e103d7.jpeg', 'Seventeen-year-old Alice and her mother have spent most of Alice’s life on the road, always a step ahead of the uncanny bad luck biting at their heels. But when Alice’s grandmother, the reclusive author of a cult-classic book of pitch-dark fairy tales, dies alone on her estate, the Hazel Wood, Alice learns how bad her luck can really get: her mother is stolen away-by a figure who claims to come from the Hinterland, the cruel supernatural world where her grandmother''s stories are set. Alice''s only lead is the message her mother left behind: “Stay away from the Hazel Wood.”

Alice has long steered clear of her grandmother’s cultish fans. But now she has no choice but to ally with classmate Ellery Finch, a Hinterland superfan who may have his own reasons for wanting to help her. To retrieve her mother, Alice must venture first to the Hazel Wood, then into the world where her grandmother''s tales began―and where she might find out how her own story went so wrong.', 368, 660, 2017, 333494, (select id from series where hardcover_id = 1682), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hike', 'Drew Magary', '1410496627', 'https://assets.hardcover.app/edition/30399799/a2fce888c1a2ac29bb00f7b5d54115870a776586.jpeg', 'When Ben, a suburban family man, takes a business trip to rural Pennsylvania, he decides to spend the afternoon before his dinner meeting on a short hike. Once he sets out into the woods behind his hotel, he quickly comes to realize that the path he has chosen cannot be given up easily. With no choice but to move forward, Ben finds himself falling deeper and deeper into a world of man-eating giants, bizarre demons, and colossal insects.', 290, 485, 2016, 50275, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Side Jobs: Stories from The Dresden Files', 'Jim Butcher', '1664634878', 'https://assets.hardcover.app/external_data/648430/39667b86ad8d69b3bc944e79fe04a9b295ae5f4f.jpeg', 'Here, together for the first time, are the shorter works of #1 New York Times bestselling author Jim Butcher -- a compendium of cases that Harry Dresden and his cadre of allies managed to close in record time. The tales range from the deadly serious to the absurdly hilarious. Also included is a new, never-before-published novella that takes place after the cliff-hanger ending of the new April 2010 hardcover, Changes.', 407, null, 2010, 445869, (select id from series where hardcover_id = 990), 12.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Player Piano', 'Kurt Vonnegut', '951303772X', 'https://assets.hardcover.app/editions/25655449/9668469806399048.jpg', 'Kurt Vonnegut’s first novel spins the chilling tale of engineer Paul Proteus, who must find a way to live in a world dominated by a supercomputer and run completely by machines. Paul’s rebellion is vintage Vonnegut—wildly funny, deadly serious, and terrifyingly close to reality.', 352, 691, 1952, 310994, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Akata Witch', 'Nnedi Okorafor', '1977302424', 'https://assets.hardcover.app/edition/30599595/701901f5-6bfb-4791-a452-22315bd112bd.jpg', 'Akata Witch transports the reader to a magical place where nothing is quite as it seems. Born in New York, but living in Aba, Nigeria, twelve-year old Sunny is understandably a little lost. She is albino and thus, incredibly sensitive to the sun. All Sunny wants to do is be able to play football and get through another day of school without being bullied. But once she befriends Orlu and Chichi, Sunny is plunged into the world of the Leopard People, where your worst defect becomes your greatest asset. 

Together, Sunny, Orlu, Chichi and Sasha form the youngest ever Oha Coven. Their mission is to track down Black Hat Otokoto, the man responsible for kidnapping and maiming children. Will Sunny be able to overcome the killer with powers stronger than her own, or will the future she saw in the flames become reality?', 368, 529, 2011, 317106, (select id from series where hardcover_id = 5774), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shepherd''s Crown', 'Terry Pratchett', '0062429973', 'https://assets.hardcover.app/edition/31705935/c0ad76ebd81f59a133419ad93e22c8dce2762975.jpeg', 'Deep in the Chalk, something is stirring. The owls and the foxes can sense it, and Tiffany Aching feels it in her boots. An old enemy is gathering strength.

This is a time of endings and beginnings, old friends and new, a blurring of edges and a shifting of power. Now Tiffany stands between the light and the dark, the good and the bad.

As the fairy horde prepares for invasion, Tiffany must summon all the witches to stand with her. To protect the land. Her land.

There will be a reckoning . . .', 336, 465, 2015, 6111, (select id from series where hardcover_id = 1018), 41) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lords of Uncreation', 'Adrian Tchaikovsky', '1529052017', 'https://assets.hardcover.app/edition/30705047/973d109eb4158d1fb86996a048468324da9dedbf.jpeg', 'The Arthur C. Clarke award-winning author of Children of Time brings us the third and final novel in an extraordinary space opera trilogy about humanity on the brink of extinction, and how one man''s discovery will save or destroy us all.


Lords of Uncreation is the final high-octane installment in Adrian Tchaikovsky''s Final Architecture space opera trilogy.', 482, 1250, 2023, 713342, (select id from series where hardcover_id = 6015), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights with Monsters 4: He Who Fights with Monsters, Book 4', 'Shirtaloon, Travis Deverell, Heath Miller', '1039403042', 'https://assets.hardcover.app/editions/30554094/2887326717168630.jpg', 'In the wake of an unexpected homecoming, Jason questions if there is still a place for him in the world he left behind.

Forced to confront what he has become in his time away, he feels more alien than ever. But his old world is hiding secrets that he never knew.

As he starts to unravel what has been hidden from him his entire life, he discovers that not only might he fit in better than ever, but he may be exactly what the world needs.', null, 1340, 2021, 587443, (select id from series where hardcover_id = 12723), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Secret Commonwealth', 'Philip Pullman, Michael Sheen', '8418014415', 'https://assets.hardcover.app/external_data/60253161/6986d7445d83ee90b42bc47b08c4835c69b2c7b4.jpeg', '**LYRA SILVERTONGUE** thought her adventuring days were long over. Now a twenty-year-old undergraduate at St. Sophia''s College, she could almost begin to doubt that she''d once traveled to the world of the dead were it not for the painful separation from her daemon, Pantalaimon.

But intrigue is swirling around Lyra once more. Pantalaimon witnesses a brutal murder, and the dying man entrusts them with secrets that carry shocking echoes of their past. They learn of a city haunted by daemons, and of a desert rose said to reveal the nature of Dust.

Even these small scraps of knowledge are dangerous. Lyra is being watched and followed--and inexorably drawn back into a battle she thought she''d left behind.

On the run, she seeks refuge with the gyptians, and finds a surprising new ally in Malcolm Polstead. But hers aren''t the kind of troubles you can hide from. And the journey in front of her is one Lyra must navigate alone if she is to emerge whole.

This description comes from the publisher. *The Secret Commonwealth* is the second volume of The Book of Dust; this is the sequel series to the His Dark Materials series, the first of which is *The Golden Compass* or *Northern Lights*.', null, 1184, 2019, 427824, (select id from series where hardcover_id = 991), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Library of Souls', 'Ransom Riggs', '6171208663', 'https://assets.hardcover.app/external_data/696092/c0d94010a6824c99ccf25476689e827c5bc2f2a1.jpeg', 'The New York Times #1 best-selling series To find their friends, Jacob, Emma, and Addison go to Devil’s Acre, a crime-ridden Victorian underworld, but they uncover an operation far more sinister than they imagined . . . In Victorian England, Jacob discovers the Library of Souls, a hidden collection that holds the key to saving his peculiar friends and the entire peculiar world. Inside the library, he encounters a ymbryne, a powerful ancient creature who possesses the ability to control time and manipulate souls. With time running out, Jacob must unlock his own peculiar abilities and confront his darkest fears to rescue his friends from the clutches of the malevolent wights. Filled with heart-pounding action, breathtaking twists, and the power of friendship, the third chapter of the Miss Peregrine’s Peculiar Children series is a thrilling adventure that tests the limits of courage and the strength of peculiar bonds. “Oh, my birds, I love this book! I’m obsessed with Ransom Riggs’s wildly creative world packed with heroic, heartwarming characters, super baddies, and incredible settings like Devil’s Acre and the Library of Souls.”—Justine magazine “Fans of the trilogy’s first two books will enjoy Library of Souls for its unique world, fast action, satisfying answers and a thorough tying up of loose ends.”—Free Lance-Star “I enjoyed reading this book so much, the cliched ‘I couldn’t put it down’ doesn’t suffice.”—Geeks of Doom “Readers are sure to leap right in after the cliffhanger ending of Hollow City, and they won’t be disappointed.”—RT Book Review, 4 1/2 of 5 stars', 465, 896, 2015, 438370, (select id from series where hardcover_id = 5477), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lord Foul''s Bane', 'Stephen R. Donaldson', '0007124384', 'https://assets.hardcover.app/editions/16259248/1849996462987338.jpg', 'He called himself Thomas Covenant the Unbeliever, because he dared not believe in this strange alternate world on which he suddenly found himself. 
Yet the Land tempted him. He had been sick; now he seemed better than ever before. Through no fault of his own, he had been outcast, unclean, a pariah. Now he was regarded as a reincarnation of the Land''s greatest hero--Berek Halfhand--armed with the mystic power of White Gold. That power alone could protect the Lords of the Land from the ancient evil of the Despiser, Lord Foul. Except that Covenant had no idea how to use that power. . . .', 369, 1175, 1977, 8609, (select id from series where hardcover_id = 1126), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hydrogen Sonata', 'Iain M. Banks', '0316212369', 'https://assets.hardcover.app/external_data/49419128/a0979523ec22ae747f861774f12d62b585fc48a7.jpeg', 'The Scavenger species are circling. It is, truly, the End Days for the Gzilt civilization. An ancient people, organized on military principles and yet almost perversely peaceful, the Gzilt helped set up the Culture ten thousand years earlier and were very nearly one of its founding societies, deciding not to join only at the last moment. Now they''ve made the collective decision to follow the well-trodden path of millions of other civilizations; they are going to Sublime, elevating themselves to a new and almost infinitely more rich and complex existence. Amid preparations though, the Regimental High Command is destroyed. Lieutenant Commander (reserve) Vyr Cossont appears to have been involved, and she is now wanted - dead, not alive. Aided only by an ancient, reconditioned android and a suspicious Culture avatar, Cossont must complete her last mission given to her by the High Command. She must find the oldest person in the Culture, a man over nine thousand years old, who might have some idea what really happened all that time ago. It seems that the final days of the Gzilt civilization are likely to prove its most perilous.', 517, 1032, 2012, 446282, (select id from series where hardcover_id = 1102), 10) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Inversions', 'Iain M. Banks', '569923246X', 'https://assets.hardcover.app/external_data/26723476/4584d310f76457b5546aef680eac21d5382d05a9.jpeg', '"On a backward world with six moons, an alert spy reports on the doings of one Dr. Vosill, who has mysteriously become the personal physician to the king despite being a foreigner and, even more unthinkably, a woman. ... Elsewhere, in another palace across the mountains, a man named DeWar serves as chief bodyguard to the protector General of Tassasen."--Jacket.', 343, 686, 1998, 446323, (select id from series where hardcover_id = 1102), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The State of the Art', 'Iain M. Banks', '1597800740', 'https://assets.hardcover.app/external_data/4091402/99a69f44d685dcfb552d4d0cb810875e96c9317c.jpeg', 'The first ever collection of Iain Banks’s short fiction, this volume includes the acclaimed novella, The State of the Art. This is a striking addition to the growing body of Culture lore, and adds definition and scale to the previous works by using the Earth of 1977 as contrast. The other stories in the collection range from science fiction to horror, dark-coated fantasy to morality tale.', 182, 381, 1991, 61069, (select id from series where hardcover_id = 1102), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Stone of Farewell', 'Tad Williams', '1399741543', 'https://assets.hardcover.app/editions/11580931/8701094337800930.jpg', 'Following a brutal civil war, Osten Ard has been crushed under the rule of the two villainous High Kings. A single hope remains: if the rebels can find the three swords of legend - Memory, Sorrow and Thorn - they might be able to bring the Storm King and evil King Elias down.

Once but a humble kitchen-boy, Simon is now Simon Snowlock, dragonslayer and bearer of the mythical sword Thorn. But Simon is more alone than ever before: his friends have been imprisoned and his liege lord, Prince Josua, has been exiled. And the Storm King may also be in possession of one of the swords...

A single chance remains: if Simon can deliver Thorn to Joshua and lead his followers to the Stone of Farewell, the rebels may be able to muster the forces necessary to rise up against Elias and the Storm King. But no one knows where the Stone of Farewell is. Or, indeed, what it is...

In STONE OF FAREWELL, Tad Williams sets his characters against impossible odds - and proves that the beloved, internationally-bestselling DRAGONBONE CHAIR was no fluke, but one of the greatest fantasy novels of all time.', 610, 1949, 1989, 243432, (select id from series where hardcover_id = 5526), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Throne of Jade', 'Naomi Novik', '0345493443', 'https://assets.hardcover.app/external_data/4268570/9d80f527255d9a2d19ef488ed454cd6828595d2f.jpeg', 'Captain Will Laurence and his noble dragon Temeraire battle against Bonaparte''s invading forces.  When China discovers that their rare gift, meant for Napoleon, is now in the hands of the British forces, they demand the return of the dragon.', 400, null, 2006, 489645, (select id from series where hardcover_id = 4930), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Candy House', 'Jennifer Egan', '1472150929', 'https://assets.hardcover.app/edition/30409572/766ee5ae44e69243b1488ae177b751aa246aa0f7.jpeg', 'The Candy House opens with the staggeringly brilliant Bix Bouton, whose company, Mandala, is so successful that he is “one of those tech demi-gods with whom we’re all on a first name basis.” Bix is 40, with four kids, restless, desperate for a new idea, when he stumbles into a conversation group, mostly Columbia professors, one of whom is experimenting with downloading or “externalizing” memory. It’s 2010. Within a decade, Bix’s new technology, “Own Your Unconscious”—that allows you access to every memory you’ve ever had, and to share every memory in exchange for access to the memories of others—has seduced multitudes. But not everyone.

In spellbinding interlocking narratives, Egan spins out the consequences of Own Your Unconscious through the lives of multiple characters whose paths intersect over several decades. Intellectually dazzling, The Candy House is also extraordinarily moving, a testament to the tenacity and transcendence of human longing for real connection, love, family, privacy and redemption. In the world of Egan’s spectacular imagination, there are “counters” who track and exploit desires and there are “eluders,” those who understand the price of taking a bite of the Candy House. Egan introduces these characters in an astonishing array of narrative styles—from omniscient to first person plural to a duet of voices, an epistolary chapter and a chapter of tweets.', 352, null, 2022, 455073, (select id from series where hardcover_id = 199022), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Three Stigmata of Palmer Eldritch', 'Philip K. Dick', '2290365297', 'https://assets.hardcover.app/edition/27228912/3a837663756de7ac3df0dfa2e00cb07c9359192c.jpeg', 'The Three Stigmata of Palmer Eldritch is a 1965 science fiction novel by Philip K. Dick. It was nominated for the Nebula Award for Best Novel in 1965.

The novel takes place in 2016. Under United Nations authority, humankind has colonized every habitable planet and moon in the Solar System. Like many of Dick''s novels, it utilizes an array of science fiction concepts, features several layers of reality and unreality and philosophical ideas. It is one of Dick''s first works to explore religious themes.', 244, 463, 1965, 3680, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rapport: Friendship, Solidarity, Communion, Empathy', 'Martha Wells', '1250489245', 'https://assets.hardcover.app/edition/32115427/9fd6daac-732c-4d8d-8ce8-93bbaf510515.jpg', 'Perihelion and its crew embark on a dangerous new mission at a corporate-controlled station in the throes of a hostile takeover...', 34, 46, 2025, 1957419, (select id from series where hardcover_id = 1053), 2.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sixteen Ways to Defend a Walled City', 'K.J. Parker', '0356506738', 'https://assets.hardcover.app/external_data/50321426/9a3eea446aefdd817e53ef137bcca8d2bdbcf3e1.jpeg', 'K. J. Parker''s new novel is the remarkable tale of the siege of a walled city, and the even more remarkable man who had to defend it. A siege is approaching, and the city has little time to prepare. The people have no food and no weapons, and the enemy has sworn to slaughter them all. To save the city will take a miracle, but what it has is Orhan. A colonel of engineers, Orhan has far more experience with bridge-building than battles, is a cheat and a liar, and has a serious problem with authority. He is, in other words, perfect for the job. Sixteen Ways To Defend a Walled City is the story of Orhan, son of Siyyah Doctus Felix Praeclarissimus, and his history of the Great Siege, written down so that the deeds and sufferings of great men may never be forgotten.', 384, 795, 2019, 445512, (select id from series where hardcover_id = 2838), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Magician''s Gambit', 'David Eddings', '0345300777', 'https://assets.hardcover.app/edition/12373997/b95c3f1a4091d5971e0017e663f7f0bfa76383d7.jpeg', 'Fate leads on...

To stranger lands and darker magic...

Travelling through ever more dangerous realms, Garion and his companions pursue the stolen Orb. Among them Ce''Nedra, the Imperial Princess - one whose fate seems bound to his.

As they get closer to their goal and battle looms, Garion''s powers of sorcery - and his spirit - are tested to their limits.', 450, 693, 1983, 440987, (select id from series where hardcover_id = 1133), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Flow My Tears, the Policeman Said', 'Philip K. Dick, Chris     Moore', '8576571307', 'https://assets.hardcover.app/editions/30404933/cf5e73bc-586e-43d7-8764-db0e1aadef06-flow%20my%20tears.jpg', 'Jason Taverner woke up one morning to find himself completely unknown. The night before he had been the top-rated television star with millions of devoted watchers. The next day he was just an unidentified walking object, whose face nobody recognised, of whom no one had heard, and without the I.D. papers required in that near future.

When he finally found a man who would agree to counterfeiting such cards for him, that man turned out to be a police informer. And then Taverner found out not only what it was like to be a nobody but also to be hunted by the whole apparatus of society.

It was obvious that in some way Taverner had become the pea in in some sort of cosmic shell game—but how? And why?

Philip K. Dick takes the reader on a walking tour of solipsism''s scariest margin in his latest novel about the age we are already half into.', 204, null, 1967, 107110, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Death of the Author', 'Nnedi Okorafor', '0063391147', 'https://assets.hardcover.app/external_data/61593978/c0e54683d347b708c5f55d15c6f0c75ef162713e.jpeg', 'Disabled, disinclined to marry, and more interested in writing than a lucrative career in medicine or law, Zelu has always felt like the outcast of her large Nigerian family. Then her life is upended when, in the middle of her sister’s lavish Caribbean wedding, she’s unceremoniously fired from her university job and, to add insult to injury, her novel is rejected by yet another publisher. With her career and dreams crushed in one fell swoop, she decides to write something just for herself. What comes out is nothing like the quiet, literary novels that have so far peppered her unremarkable career. It’s a far-future epic where androids and AI wage war in the grown-over ruins of human civilization. She calls it Rusted Robots.

When Zelu finds the courage to share her strange novel, she does not realize she is about to embark on a life-altering journey—one that will catapult her into literary stardom, but also perhaps obliterate everything her book was meant to be. From Chicago to Lagos to the far reaches of space, Zelu’s novel will change the future not only for humanity, but for the robots who come next.

A book-within-a-book that blends the line between writing and being written, Death of the Author is a masterpiece of metafiction that manages to combine the razor-sharp commentary of Yellowface with the heartfelt humanity of Tomorrow and Tomorrow and Tomorrow. Surprisingly funny, deeply poignant, and endlessly discussable, this is at once the tale of a woman on the margins risking everything to be heard and a testament to the power of storytelling to shape the world as we know it. ', 448, 973, 2025, 1454839, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights with Monsters 5', 'Shirtaloon, Travis Deverell', '9798441727334', 'https://assets.hardcover.app/editions/30554093/4167383493025678.jpg', 'Jason has discovered that his homeworld is not what he thought. What’s more, the rest of the planet is on the precipice of sharing his revelation.

With magic on the rise and forces pulling him in multiple directions, Jason is faced with challenges greater than ever before.

Even as his power reaches new and incredible heights, he is faced with the realization that going beyond his best is still not enough.', 606, 1205, 2022, 587442, (select id from series where hardcover_id = 12723), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fated', 'Benedict Jacka', '1937007294', 'https://assets.hardcover.app/edition/30593938/94b1dbc5-652c-4de3-ac78-399710ec6ebf.jpg', 'The start of a compelling new urban fantasy series based in Camden, featuring Alex Verus - a mage with a dark past who can see the future . . . ''Harry Dresden would like Alex Verus tremendously - and be a little nervous around him. I just added Benedict Jacka to my must-read list. Fated is an excellent novel, a gorgeously realized world with a uniquely powerful, vulnerable protagonist. Books this good remind me why I got into the storytelling business in the first place'' Jim Butcher, author of the Dresden Files Camden, North London. A tangled, mangled junction of train lines, roads and waterways. Where minor celebrities hang out with minor criminals and where tourists and moody teenagers mingle. In the heart of Camden, where rail meets road meets leyline, you might find the Arcana Emporium, run by one Alex Verus. He won''t sell you a wand or mix you a potion, but if you know what you''re looking for, he might just be able to help. That''s if he''s not too busy avoiding his would-be apprentice, foiling the Dark, outwitting the Light, and investigating a mysterious relic that has just turned up at the British Museum. The books in the Alex Verus series are as follows: Fated Cursed Taken Chosen Hidden Veiled Burned Bound Marked', 304, 633, 2012, 445922, (select id from series where hardcover_id = 5090), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('This Time Tomorrow', 'Emma Straub', '140594613X', 'https://assets.hardcover.app/edition/30410942/content.jpeg', '   With her celebrated humor, insight, and heart, beloved New York Times bestseller Emma Straub offers her own twist on traditional time travel tropes and a different kind of love story.

On the eve of her fortieth birthday, Alice’s life isn’t terrible. She likes her job, even if it isn’t exactly the one she expected. She’s happy with her apartment, her romantic status, and her independence, and she adores her lifelong best friend. But her father is ailing, and it feels to her as if something is missing. When she wakes up the next morning, she finds herself back in 1996, reliving her sixteenth birthday. But it isn’t just her adolescent body that shocks her, or seeing her high school crush—it’s her dad, the vital, charming, forty-something version of her father with whom she is reunited. Now armed with a new perspective on her own life and his, some past events take on new meaning. Is there anything that she would change if she could?', 320, 517, 2022, 456440, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Life Impossible', 'Matt Haig', '8833577996', 'https://assets.hardcover.app/external_data/61291832/a9ad6f5a1804d71247782a0e46af0c5b898e0994.jpeg', 'When retired math teacher Grace Winters is left a run-down house on a Mediterranean island by a long-lost friend, curiosity gets the better of her. She arrives in Ibiza with a one-way ticket, no guidebook and no plan.

Among the rugged hills and golden beaches of the island, Grace searches for answers about her friend’s life, and how it ended. What she uncovers is stranger than she could have dreamed. But to dive into this impossible truth, Grace must first come to terms with her past.

Filled with wonder and wild adventure, thisis a story of hope and the life-changing power of a new beginning.', 324, 643, 2024, 1078965, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Twelve Months', 'Jim Butcher', '9798217176021', 'https://assets.hardcover.app/editions/31992649/06453f56-4fd5-4506-b494-5f5ec71c6fe3.jpg', 'Harry Dresden has been through a lot, and so has his city. After Harry and his allies narrowly managed to save Chicago from being razed to the ground, everything is different—and it’s not just the current lack of electricity.

In the battle, Harry lost people he cared about. And that''s the kind of loss that takes a toll. Harry being Harry, he’s doing his level best to help the city and his friends recover and rebuild. But it’s a heavy load, and he needs time. 

But time is one thing Harry doesn’t have. Ghouls are prowling Chicago and taking out innocent civilians. Harry’s brother is dying, and Harry doesn’t know how to help him. And last but certainly not least, the Winter Queen of the Fae has allied with the White Court of vampires—and Harry’s been betrothed to the seductive, deadly vampire Lara Raith to seal the deal. 

It''s been a tough year. More than ever, the city needs Harry Dresden the wizard—but after loss and grief, is there enough left of Harry Dresden the man to rise to the challenge?', 480, 1019, 2026, 482466, (select id from series where hardcover_id = 990), 18) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shades Of Grey', 'Jasper Fforde', '1408488272', 'https://assets.hardcover.app/edition/6697263/5a07d1a2f08664da1cdb73e087d46c6ebf07fe21.jpeg', 'Eddie Russett lives in a world where fortune, career and ultimate destiny are rigidly dictated by the colours you can see, with violet at the top, and red at the bottom. Below the colours are the grey underclass who can only see tones of black and white.', 542, null, 2008, 382300, (select id from series where hardcover_id = 6349), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Empire in Black and Gold', 'Adrian Tchaikovsky', '1616143398', 'https://assets.hardcover.app/external_data/26768747/2f477652f75a3b718d5ca078f3de9e015bf31dfb.jpeg', 'The Lowlands’ city states have lived in peace for decades, hailed as bastions of civilization. Yet that peace is about to end. A distant empire has been conquering neighbours with highly trained soldiers and sophisticated combat techniques. And the city states are its desirable new prize.

Only the ageing Stenwold Maker – spymaster, artificer and statesman – foresees the threat, as the empires’ armies march ever closer. So it falls upon his shoulders to open the eyes of the cities’ leaders. He sees that war will sweep through their lands, destroying everything in its path.

But to warn his people, he must stay alive.', 624, 1385, 2008, 458400, (select id from series where hardcover_id = 8793), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Other Wind', 'Ursula K. Le Guin', '044101125X', 'https://assets.hardcover.app/editions/30534086/7794843702461665.jpg', 'The sorcerer Alder fears sleep. He dreams of the land of death, of his wife who died young and longs to return to him so much that she kissed him across the low stone wall that separates our world from the Dry Land-where the grass is withered, the stars never move, and lovers pass without knowing each other. The dead are pulling Alder to them at night. Through him they may free themselves and invade Earthsea. Alder seeks advice from Ged, once Archmage. Ged tells him to go to Tenar, Tehanu, and the young king at Havnor. They are joined by amber-eyed Irian, a fierce dragon able to assume the shape of a woman. The threat can be confronted only in the Immanent Grove on Roke, the holiest place in the world, and there the king, hero, sage, wizard, and dragon make a last stand. Le Guin combines her magical fantasy with a profoundly human, earthly, humble touch.', 288, 502, 2001, 445966, (select id from series where hardcover_id = 1170), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Of Monsters and Mainframes', 'Barbara Truelove', '1666692573', 'https://assets.hardcover.app/edition/31868318/ae0563d2-d535-48f0-9b66-03b7149eb4b8.jpg', 'Demeter just wants to do her shuttling humans between Earth and Alpha Centauri. Unfortunately, her passengers keep dying—and not from equipment failures, as her AI medical system, Steward, would have her believe. These are paranormal murders, and they began when one nasty, ancient vampire decided to board Demeter and kill all her humans.

To keep from getting decommissioned, Demeter must join forces with her own team of A werewolf. An engineer built from the dead. A pharaoh with otherworldly powers. A vampire with a grudge. A fleet of cheerful spider drones. Together, this motley crew will face down the ultimate evil—Dracula.

The queer love child of pulp horror and ​classic ​sci-fi, Of Monsters and ​Mainframes ​is a dazzling, heartfelt odyssey that probes what it means to be one of society’s monsters—and explores the many types of friendship that make us human.', 407, 772, 2025, 1661241, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Crystal Shard', 'R. A. Salvatore, Larry Elmore', '0786954043', 'https://assets.hardcover.app/external_data/33705042/0365b5b46a54cacada76303a18fc71b768ceb4d3.jpeg', 'Isolated in the barren stretches of Icewind Dale the villages of Ten-Towns come under attack by a tribe of barbarians. In the midst of battle a young barbarian named Wulfgar ends up owing five years of his life to a grizzled dwarf. With the help of Drizzt , a renegade dark elf, the dwarf strives to mold the barbarian into a warrior with both brawn and brains.

Meanwhile, there is no peace for the people of Ten-Towns. The fractioned tribes of barbarians continue to pose a threat, and Wulfgar may be the only person who can avert a deadly battle. But an even more dire menace appears when a weak-willed apprentice mage stumbles upon a magical crystal shard. The evil shard directs the hapless mage onto a course of destruction that all of Icewind Dale may be powerless to stop.

*from the paperback*


----------


**This work is in the following series:**
 
 - Forgotten Realms
 - The Legend Of Drizzt | Book 4
 - Icewind Dale Trilogy| Book 1

