  [3]: http://openlibrary.org/works/OL15333836W/The_Crystal_Shard', 333, 722, 1988, 28782, (select id from series where hardcover_id = 5806), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Queen of Sorcery', 'David Eddings', '0593026292', 'https://assets.hardcover.app/edition/2084560/65aa5d77c107ea11ffae1147d3c398db64710ab6.jpeg', 'The Trail of Prophecy...

Legends told of how the evil God Torak had coveted the power of the Orb of Aldur, until defeated in a final battle. But prophecy spoke of a time when he would awake and again seek dominance over the world. Now the Orb has been stolen by a priest of Torak, and that time was at hand.

The master Sorcerer Belgarath and his daughter Polgara the arch-Sorceress were on the trail of the Orb, seeking to regain it before the final disaster. And with them went Garion, a simple farm boy only months before, but now the focus of the struggle. He has never believed in sorcery and wanted no part of it. Yet with every league they traveled, the power grew in him, forcing him to acts of wizardry he could not accept.

This continues the magnificent epic of The Belgariad, began in Pawn of Prophecy, set among strange lands against a background of a war of men, Kings, and Gods that had spanned seven thousand years - a novel of strange fate and a prophecy that must come true!', 446, 763, 1982, 3403, (select id from series where hardcover_id = 1133), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Enchanters'' End Game', 'David Eddings', '0552554804', 'https://assets.hardcover.app/edition/32487516/b0900d83c6045fe37b260e92e738337392a22ad1.jpeg', 'On the outcome of one duel rests the fate of the world...

With Garion on the throne, peace has finally come to the West. But as long as the evil God Torak still lives, he knows they will never truly be safe.

As Princess Ce''Nedra leads her armies in a desperate bid to divert the Evil One’s forces, Garion travels to the City of Endless Night to face Torak for the last time.

But one question haunts him: can man ever destroy an immortal God?', 450, 841, 1984, 440985, (select id from series where hardcover_id = 1133), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Redemption Ark', 'Alastair Reynolds', '849800960X', 'https://assets.hardcover.app/edition/7155042/6a23aa24-ead6-4ecf-9b4e-ba3214381c3d.jpg', 'Late in the 26th century, the human race has advanced enough to accidentally trigger the Inhibitors---alien-killing machines designed to detect intelligent life and destroy it. The only hope for humanity lies in the recovery of a secret cache of doomsday weapons---and a renegade named Clavain who is determined to find them. But other factions want the weapons for their own purposes---and the weapons themselves have another agenda altogether.', 647, null, 2002, 446320, (select id from series where hardcover_id = 5563), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('How to Live Safely in a Science Fictional Universe', 'Charles Yu', '3644901619', 'https://assets.hardcover.app/editions/9518321/1451674441833151.jpeg', 'Minor Universe 31 is a vast story-space on the outskirts of fiction, where paradox fluctuates like the stock market, lonely sexbots beckon failed protagonists, and time travel is serious business. Every day, people get into time machines and try to do the one thing they should never do: change the past. That’s where Charles Yu, time travel technician—part counselor, part gadget repair man—steps in. He helps save people from themselves. Literally. When he’s not taking client calls or consoling his boss, Phil, who could really use an upgrade, Yu visits his mother (stuck in a one-hour cycle of time, she makes dinner over and over and over) and searches for his father, who invented time travel and then vanished. Accompanied by TAMMY, an operating system with low self-esteem, and Ed, a nonexistent but ontologically valid dog, Yu sets out, and back, and beyond, in order to find the one day where he and his father can meet in memory. He learns that the key may be found in a book he got from his future self. It’s called How to Live Safely in a Science Fictional Universe, and he’s the author. And somewhere inside it is the information that could help him—in fact it may even save his life.', 257, null, 2010, 432263, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sojourn', 'R. A. Salvatore', '0140143998', 'https://assets.hardcover.app/external_data/4089814/d89b8760584dcc718bf140c3a3466983dd21a175.jpeg', 'Now in paperback, the third installment in the classic tales of the Legend of Drizzt. When a lone drow emerges from the Underdark into the blinding light of day, the Forgotten Realms world will be changed forever.From the Paperback edition.', 309, 614, 1991, 15630, (select id from series where hardcover_id = 5806), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights With Monsters 6', 'Shirtaloon, Travis Deverell', '1039403441', 'https://assets.hardcover.app/editions/31230443/1854233557129981.jpg', 'The world teeters on the brink of destruction.

The people who should be saving the Earth ignore Jason Asano''s warnings and choose to loot the house as it burns down around them. He lacks the strength to save the world himself, but resolves to do it anyway, impossible be damned.

The impossible, in this case, means seizing a power that no mortal should touch. It''s a choice from which there is no turning back, and marks Jason''s first step into a wider cosmos that he is not yet ready to face.

Holding the fate of two worlds in his hands, Jason must decide for himself what home truly means.', 510, 949, 2022, 587441, (select id from series where hardcover_id = 12723), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Disquiet Gods', 'Christopher Ruocchio', '9798892731478', 'https://assets.hardcover.app/edition/31892466/bb96322e-a228-4135-b474-c087f8c7decb.jpg', 'The end is nigh. 

It has been nearly two hundred years since Hadrian Marlowe assaulted the person of the Emperor and walked away from war. From his Empire. His duty. From the will and service of the eldritch being known only as the Quiet. The galaxy lies in the grip of a terrible plague, and worse, the Cielcin have overrun the realms of men. 

A messenger has come to Jadd, bearing a summons from the Sollan Emperor for the one-time hero. A summons, a pardon, and a plea. HAPSIS, the Emperor’s secret first-contact intelligence organization, has located one of the dreadful Watchers, the immense, powerful beings worshipped by the Pale Cielcin. 

Called out of retirement and exile, the old hero—accompanied by his daughter, Cassandra—must race across the galaxy and against time to accomplish one last, impossible task: To kill a god.', 706, 1898, 2024, 896596, (select id from series where hardcover_id = 6522), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wild Seed', 'Octavia E. Butler', '0385151608', 'https://assets.hardcover.app/external_data/30193307/cd284680ea9590aa0363423ed96bc78a7e99404f.jpeg', 'Doro is an immortal, body-stealing spirit who seeks and breeds outcasts with special abilities.  He meets Anyanwu, an immortal, shape-shifting, healer woman who has the abilities he breeds for.  She submits to him but refuses to be controlled by him.', 306, null, 1980, 438811, (select id from series where hardcover_id = 3176), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Boneshaker', 'Cherie Priest', '8490182639', 'https://assets.hardcover.app/external_data/27558182/4081fb3bdbe62ca656ff8cb7e8e4d424c94c8081.jpeg', '<Blockquote>
In the early days of the Civil War, rumors of gold in the frozen Klondike brought hordes of newcomers to the Pacific Northwest. Anxious to compete, Russian prospectors commissioned inventor Leviticus Blue to create a great machine that could mine through Alaska''s ice. 

Thus was Dr. Blue''s Incredible Bone-Shaking Drill Engine born. But on its first test run the Boneshaker went terribly awry, destroying several blocks of downtown Seattle and unearthing a subterranean vein of blight gas that turned anyone who breathed it into the living dead. 

Now it is 16 years later, and a wall has been built to enclose the devastated and toxic city. Just beyond it lives Blue''s widow, Briar Wilkes. Life is hard with a ruined reputation and a teenaged boy to support, but she and Ezekiel are managing. Until Ezekiel undertakes a secret crusade to rewrite history. His quest will take him under the wall and into a city teeming with ravenous undead, air pirates, criminal overlords, and heavily armed refugees. And only Briar can bring him out alive.
<Blockquote>
-<a href="http://www.goodreads.com/book/show/7733239-boneshaker">Goodreads</a>', 416, 822, 2009, 219338, (select id from series where hardcover_id = 5735), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Undertaking of Hart and Mercy', 'Megan Bannen', '9780316394215', 'https://assets.hardcover.app/edition/30505203/eaac0209d5f785f8450ac4235d7c1e9c59bfe1bb.jpeg', '''Megan Bannen has created a world that you''ll never want to leave and characters that will carve a spot into your heart. This series is playfully unique, delightfully steamy, utterly romantic, and overall unmissable!'' Ali Hazelwood The Princess Bride meets You''ve Got Mail in this enchantingly quirky, completely refreshing fantasy with a rom-com-worthy premise. Hart is a marshal, tasked with patrolling the magical wilds of Tanria. It''s an unforgiving job, and he''s got nothing but time to ponder his loneliness. Mercy never has a moment to herself. She''s been single-handedly keeping Birdsall & Son Undertakers afloat in defiance of sullen jerks like Hart-ache Hart, the man with a knack for showing up right when her patience is thinnest. After yet another run-in with Merciless Mercy, Hart finds himself penning a letter addressed simply to "A Friend". Much to his surprise, he receives an anonymous reply, and a tentative friendship is born. Little does Hart know he''s baring his soul to the person who infuriates him most. . . Set in a world equally full of magic and demigods as it is donuts and small-town drama, this utterly unique fantasy is sure to sweep you off your feet. Praise for The Undertaking of Hart and Mercy: ''Romantic, wildly creative, and utterly charming, The Undertaking of Hart and Mercy is a fantasy unlike any I''ve read before'' Lana Harper, author of Payback''s a Witch ''The Undertaking of Hart and Mercy broke my heart, put it back together, then tucked me into bed with a forehead kiss. Packed with earnest characters, wit, action, and reluctant yearning, this is easily my favourite fantasy romance of the year'' Jen DeLuca, author of Well Met ''A uniquely charming mixture of whimsy and the macabre that completely won me over'' Helen Hoang, author of The Kiss Quotient ''Megan Bannen remains the queen of swoons upon swoons upon swoons! The Undertaking of Hart and Mercy is a playful, quirky gem-full of feels and guaranteed to deliver the perfect grumpy/sunshine fix!'' Sierra Simone ''An unabashedly offbeat adventure'' Freya Marske, author of A Marvellous Light ''A lovely, macabre fantasy romance about life, death, and Actually Living. I cried twice and smiled plenty'' Olivia Atwater, author of Half a Soul ''Megan Bannen broke me, made me laugh, then put me back together again. . . The Undertaking of Hart and Mercy is one of those books you''ll be thinking about long after you''ve read the last page'' Manda Collins ''A truly outstanding romantic fantasy'' India Holton, author of The Wisteria Society of Lady Scoundrels ''A little sweet, a little spicy, a little sharp and entirely moreish!'' Davinia Evans, author of Notorious Sorcerer ''I showed up for the fantastic, fun fantasy setting but it was Hart and Mercy that kept me reading'' Ruby Dixon, author of Ice Planet Barbarians ''Megan Bannen has found her voice with this incredibly smart, and hilariously weird debut. A must read'' Nisha Sharma, author of Dating Dr. Dil ''Warm, compassionate and compelling'' Vivian Shaw, author of Strange Practice', 453, null, 2022, 547613, (select id from series where hardcover_id = 41877), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Space Opera', 'Catherynne M. Valente', '8891246670', 'https://assets.hardcover.app/edition/30405535/5dd465473f8e0ce8378e522ac3561703a39d263e.jpeg', '"Mankind will not get to fight for its destiny. They must sing. A century ago, the Sentience Wars tore the galaxy apart and nearly ended the entire concept of intelligent space-faring life. In the aftermath, a curious tradition was invented by the remnants of civilization. Something to cheer up everyone who was left. Something to celebrate having escaped total annihilation by the skin of one''s teeth, if indeed one has skin. Or teeth. Something to bring the shattered worlds together in the spirit of peace, unity, understanding, and the most powerful of all social bonds: excluding others. Once every cycle, the great galactic civilizations gather for Galactivision--part gladiatorial contest, part beauty pageant, part concert extravaganza, and part, a very large, but very subtle part, continuation of the wars of the past. Thus, a fragile peace has held. This year, a bizarre and unsightly species has looked up from its muddy planet-bound cradle and noticed the enormous universe blaring on around it: humanity. Where they expected to one day reach out into space and discover a grand drama of diplomacy, gunships, wormholes, and stoic councils of grave aliens, they have found glitter. And lipstick. And pyrotechnics. And electric guitars. A band of human musicians, dancers, and roadies have been chosen to represent their planet on the greatest stage in the galaxy. And the fate of Earth lies in their ability to rock"--', 304, null, 2017, 77736, (select id from series where hardcover_id = 5662), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('War Storm', 'Victoria Aveyard, Vikas Adam, Amanda Dolan, Charlie Thurston, Erin Spencer, Saskia Maarleveld', '2702447880', 'https://assets.hardcover.app/external_data/60936527/d299e9f01333508c8cb16bbb8a9f6ceb1673418c.jpeg', 'VICTORY COMES AT A PRICE. Mare Barrow learned this all too well when Cal''s betrayal nearly destroyed her. Now determined to protect her heart-and secure freedom for Reds and newbloods like her-Mare resolves to overthrow the kingdom of Norta once and for all . . . starting with the crown on Maven''s head. But no battle is won alone, and before the Reds may rise as one, Mare must side with the boy who broke her heart in order to defeat the boy who almost broke her. Cal''s powerful Silver allies, alongside Mare and the Scarlet Guard, prove a formidable force. But Maven is driven by an obsession so deep, he will stop at nothing to have Mare as his own again, even if it means demolishing everything - and everyone - in his path. War is coming, and all Mare has fought for hangs in the balance. Will victory be enough to topple the Silver kingdoms? Or will the little lightning girl be forever silenced? In the epic conclusion to Victoria Aveyard''s stunning series, Mare must embrace her fate and summon all her power . . . for all will be tested, but not all will survive. The #1 New York Times bestselling Red Queen series by Victoria Aveyard comes to a stunning conclusion in this fourth and final book.', null, null, 2017, 429081, (select id from series where hardcover_id = 1204), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights with Monsters 7', 'Shirtaloon, Travis Deverell', '1039407560', 'https://assets.hardcover.app/editions/30529441/9839541248256036.jpg', 'Jason arrives at a kingdom in peril and he''s surprised to discover that it''s not his job to save it.

With the authorities fulfilling their responsibilities (for once), he looks forward to some quiet time to rest and recuperate.

The locals might not find ceaseless monster onslaughts and an inter-dimensional invasion relaxing, but Jason has had a rough few years. He''s doing his best to let go of his anger.

While his team is caught up in duty, Jason has no shortage of people looking to interfere with his rest. Enemies–old and new–are circling, and even would-be allies are trouble. A princess finds him inconveniently alive, an ancient king arrives at his barbecue, and the local Church of Fertility are uncomfortably enthusiastic about including him in their practices. As his friends strive to reach him from the far side of the world, they are all frustrated by obstacles.

Jason is finally back in the world he longed for, but he is not the same man he was when he left. As the pressure on him mounts, allies and enemies alike will find that out the hard way.', 620, null, 2022, 567927, (select id from series where hardcover_id = 12723), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Legend', 'David Gemmell', '0345379063', 'https://assets.hardcover.app/edition/26611386/d2eb056bf4cb1210ff7e34e2791beea24dc9d142.jpeg', '“David Gemmell tells a tale of very real adventure, the stuff of true epic fantasy.”—R. A. Salvatore Druss, Captain of the Ax, is the stuff of legends. Tales of his battles are told throughout the land, and the stories expand with each telling. But Druss himself grows older, until finally, the warrior turns his back on glory and retreats to his mountain lair. There he awaits his old enemy: death. But far below, the barbarian Nadir hordes are on the march. All that stands between them and the Drenai people is a mighty six-walled fortress, Dros Delnoch—a great citadel that seems destined to fall. If it does, the Nadir will sweep inexorably across the land, killing all who oppose them. Reluctantly Druss agrees to come down from his mountaintop to lead this last, hopeless fight. Lost causes mean nothing to him—he has fought in such battles a thousand times in a thousand lands. And he is a hero to inspire a new generation of warriors. He is Druss the Legend. Thus begins David Gemmell’s most celebrated novel—an unrivaled classic of mythic heroism and magnificent adventure. . . .', 337, null, 1984, 445495, (select id from series where hardcover_id = 3414), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dogs of War', 'Adrian Tchaikovsky', '9934553384', 'https://assets.hardcover.app/edition/30391561/e29af0df-b92a-439c-874b-7ed2501ef96c.jpg', 'My name is Rex. I am a good dog.

Rex is also seven foot tall at the shoulder, bulletproof, bristling with heavy calibre weaponry and his voice resonates with subsonics especially designed to instil fear. With Dragon, Honey and Bees, he''s part of a Multiform Assault Pack operating in the lawless anarchy of Campeche, Mexico. A genetically engineered Bioform, he''s a deadly weapon in a dirty war. All he wants to be is a Good Dog. And to do that he must do exactly what Master says and Master says he''s got to kill a lot of enemies.

But who, exactly, are the enemies? What happens when Master is tried as a war criminal? What rights does the Geneva Convention grant weapons? Do Rex and his fellow Bioforms even have a right to exist?

And what happens when Rex slips his leash?', 305, 598, 2017, 280856, (select id from series where hardcover_id = 3431), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Magyk', 'Angie Sage, Mark Zug', '1408814935', 'https://assets.hardcover.app/external_data/30227317/5a91a9b11b171ba6fe3c82bae1839589ca18a841.jpeg', 'After learning that she is the Princess, Jenna is whisked from her home and carried toward safety by the Extraordinary Wizard, those she always believed were her father and brother, and a young guard known only as Boy 412--pursued by agents of those who killed her mother ten years earlier.', 580, null, 2005, 259702, (select id from series where hardcover_id = 6252), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Foxglove King', 'Hannah F. Whitten', '9896618798', 'https://assets.hardcover.app/editions/30510654/5360ffca-4b8a-417c-b741-40f26c0ead33.jpg', 'When Lore was thirteen, she escaped a cult in the catacombs beneath the city of Dellaire. And in the ten years since, she’s lived by one rule: don’t let them find you. Easier said than done, when her death magic ties her to the city.

Mortem, the magic born from death, is a high-priced and illicit commodity in Dellaire, and Lore’s job running poisons keeps her in food, shelter, and relative security. But when a run goes wrong and Lore’s power is revealed, she’s taken by the Presque Mort, a group of warrior-monks sanctioned to use Mortem working for the Sainted King. Lore fully expects a pyre, but King August has a different plan. Entire villages on the outskirts of the country have been dying overnight, seemingly at random. Lore can either use her magic to find out what’s happening and who in the King’s court is responsible, or die.

Lore is thrust into the Sainted King’s glittering court, where no one can be believed and even fewer can be trusted. Guarded by Gabriel, a duke-turned-monk, and continually running up against Bastian, August’s ne''er-do-well heir, Lore tangles in politics, religion, and forbidden romance as she attempts to navigate a debauched and opulent society.

But the life she left behind in the catacombs is catching up with her. And even as Lore makes her way through the Sainted court above, they might be drawing closer than she thinks.

In this lush, romantic new epic fantasy series from New York Times bestselling author Hannah Whitten, a young woman’s secret power to raise the dead plunges her into the dangerous and glamorous world of the Sainted King’s royal court.', 467, null, 2023, 552137, (select id from series where hardcover_id = 25475), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Half the World', 'Joe Abercrombie', '8580416418', 'https://assets.hardcover.app/external_data/59808549/faca525fe8aaeba02c9b2cf0fc1dcebeda3b8d5d.jpeg', 'Thorn Bathu was born to fight. But when she kills a boy in the training square she finds herself named a murderer.

Fate places her life in the hands of the deep-cunning Father Yarvi as he sets out to cross half the world in search of allies against the ruthless High King. Beside her is Brand, a young warrior who hates to kill. A failure in her eyes and his own, the voyage is his last chance at redemption.

But warriors can be weapons, and weapons are made for one purpose. Will Thorn always be a tool in the hands of the powerful, or can she carve her own path? Is there a place outside of legend for a woman with a blade?', 422, 781, 2015, 458844, (select id from series where hardcover_id = 6740), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Castle of Wizardry', 'David Eddings', '8842902845', 'https://assets.hardcover.app/edition/32026871/9e4540804c31f1f87648e71f9c93bebba48065dd.jpeg', 'It had all begun with the theft of the Orb that had so long protected the West from the evil God Torak. Before that, Garion had been a simple farm boy. Afterward, he discovered that his aunt was really the Sorceress Polgara and his grandfather was Belgarath, the Eternal Man. Then, on the long quest to recover the Orb, Garion found to his dismay that he, too, was a sorcerer.

Now, at last, the Orb was regained and the quest was nearing its end. Of course, the questors still had to escape from this crumbling enemy fortress and flee across a desert filled with Murgo soldiers searching for them, while Grolim Hierarchs strove to destroy them with dark magic. Then, somehow, they must manage to be in Riva with the Orb by Erastide. After that, however, Garion was sure that his part in these great events would be finished.

But the Prophecy still held future surprises for Garion--and for the little princess Ce''Nedra.

This continues the magnificent epic of The Belgariad, begun in Pawn of Prophecy, Queen of Sorcery, and Magician''s Gambit--a fantasy set against a background of the war of men, Kings, and Gods that had spanned seven thousand years--a novel of fate, strange lands, and a prophecy that must be fulfilled!', 450, 854, 1984, 74743, (select id from series where hardcover_id = 1133), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('2312', 'Kim Stanley Robinson', '8445002929', 'https://assets.hardcover.app/external_data/38050072/d8c92d195996b01a2908f439e5406cf9d98c876f.jpeg', 'From the acclaimed author of New York 2140 and Red Mars, this NYT bestselling novel tells the story of a future where humanity has populated miraculous new habitats engineered across the solar system -- and the one death that triggers a precarious chain of events that could destroy it all.

The year is 2312. Scientific and technological advances have opened gateways to an extraordinary future. Earth is no longer humanity''s only home; new habitats have been created throughout the solar system on moons, planets, and in between. But in this year, 2312, a sequence of events will force humanity to confront its past, its present, and its future.

The first event takes place on Mercury, on the city of Terminator, itself a miracle of engineering on an unprecedented scale. It is an unexpected death, but one that might have been foreseen. For Swan Er Hong, it is an event that will change her life. Swan was once a woman who designed worlds. Now she will be led into a plot to destroy them.', 790, null, 2012, 289358, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Locklands', 'Robert Jackson Bennett', '1984820672', 'https://assets.hardcover.app/edition/30382820/ee117700f068c5ef2f3962cc13f6702eec307f62.jpeg', 'NATIONAL BESTSELLER • The jaw-dropping conclusion to the acclaimed Founders Trilogy, from the Hugo–nominated author of Foundryside and Shorefall “Bennett concludes his Founders trilogy . . . with characteristically high-spirited mayhem. Great fun, with nonstop action.”—Kirkus Reviews (starred review) Sancia, Clef, and Berenice have gone up against long odds in the past. But the war they’re fighting now is one even they can’t win. This time, they’re not facing robber-baron elites or even an immortal hierophant, but an entity whose intelligence is spread over half the globe—one that uses the magic of scriving to control not just objects but human minds. To fight it, they’ve used scriving technology to transform themselves and their allies into an army—a society—unlike anything humanity has seen before. With its strength at their backs, they’ve freed a handful of their enemy’s hosts from servitude, and even defeated some of its fearsome, reality-altering dreadnoughts. Yet despite their efforts, their enemy marches on. Implacable. Unstoppable. Now, as their opponent closes in on its true prize—an ancient doorway, long buried, that leads to the chambers at the center of creation itself—Sancia and her friends glimpse a last opportunity to stop this unbeatable foe. To do so, they’ll have to unlock the centuries-old mystery of scriving’s origins, embark on a desperate mission into the heart of their enemy’s power, and pull off the most daring heist they’ve ever attempted. But their adversary might have a spy in their ranks—and a last trick up its sleeve. And to have a chance at victory, Sancia, Clef, and Berenice will have to make a sacrifice beyond anything that’s come before.', 560, 1365, 2022, 465147, (select id from series where hardcover_id = 4975), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Vanished Birds', 'Simon Jimenez', '1789093937', 'https://assets.hardcover.app/external_data/826397/323e167a9accba9d74fc72e7659ae7e77580eba3.jpeg', 'A “highly imaginative and utterly exhilarating” (Thrillist) debut that is “the best of what science fiction can be: a thought-provoking, heartrending story about the choices that define our lives” (Kirkus Reviews, Best Debut Fiction and Best Science Fiction & Fantasy of the Year). FINALIST FOR THE LOCUS AWARD • NAMED ONE OF THE BEST BOOKS OF THE YEAR BY TORDOTCOM AND KIRKUS REVIEWS A mysterious child lands in the care of a solitary woman, changing both of their lives forever. I expected many things from this trip. I did not expect a family. A ship captain, unfettered from time. A mute child, burdened with unimaginable power. A millennia-old woman, haunted by lifetimes of mistakes. In this captivating debut of connection across space and time, these outsiders will find in each other the things they lack: a place of love and belonging. A safe haven. A new beginning. But the past hungers for them, and when it catches up, it threatens to tear this makeshift family apart. Praise for The Vanished Birds “This is the most impressive debut of 2020.”—Locus “This extraordinary science fiction epic, which delves deep into the perils of failing to learn from one’s mistakes, is perfect for fans of big ideas and intimate reflections.”—Publishers Weekly (starred review) “A lyrical and moving narrative of space travel, found families, and lost loves set against an evocative space-opera background.”—Booklist (starred review) “The Vanished Birds finds an intimate heartbeat of longing in a saga of galactic progress and its crushing fallout. . . . A novel of vast scope that yet makes time for compassion, wonder, and poetry.”—Indra Das, author of The Devourers', 432, 797, 2020, 436458, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Agency', 'William Gibson', '9791030704099', 'https://assets.hardcover.app/external_data/60845847/b55a4858fbd70a50b935e7ce432630a5c7f561bc.jpeg', 'Verity Jane, gifted app-whisperer, out of work since her exit from a brief but problematic relationship with a Silicon Valley billionaire, signs the wordy NDA of a dodgy San Francisco start-up, becoming the beta-tester for their latest product: a digital assistant, accessed through a pair of ordinary-looking glasses. Eunice, the disarmingly human AI in the glasses, soon manifests a face, a fragmentary past, and an unnervingly canny grasp of combat strategy. Verity, seeing that her cryptic new employers don''t yet know this, instinctively decides that it''s best they don''t. Meanwhile, a century ahead, in a fundamentally altered London, the result of a timeline in which Hillary Clinton didn''t become president, Wilf Netherton works amid plutocrats and plunderers, survivors of the slow-and-steady apocalypse known as the Jackpot. His employer, the enigmatic Ainsley Lowbeer, can look into alternate pasts and nudge their ultimate directions. Verity and Eunice have become her current project. Wilf can see what Verity and Eunice can''t--their own version of the Jackpot, just around the corner. And something else too: the roles they may play in it.', 423, 612, 2020, 428366, (select id from series where hardcover_id = 5607), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Charlie And The Great Glass Elevator', 'Roald Dahl, Quentin Blake', '8491221301', 'https://assets.hardcover.app/edition/17482775/fcc9e1e52a85f95ea0faf75b1aeb750123c3f25e.jpeg', 'Taking up where Charlie and the Chocolate Factory leaves off, Charlie, his family, and Mr. Wonka find themselves launched into space in the great glass elevator.', 159, null, 1972, 123384, (select id from series where hardcover_id = 5542), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sandman Slim', 'Richard Kadrey, MacLeod Andrews', '5041058083', 'https://assets.hardcover.app/edition/30400324/175417a99177fcd5598741dc8c8f896430097718.jpeg', 'Supernatural fantasy has a new antihero in Sandman Slim, star of this gripping, gritty new series by Richard Kadrey', 390, null, 2009, 90461, (select id from series where hardcover_id = 5672), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Children of Men', 'P. D. James', '849658190X', 'https://assets.hardcover.app/external_data/61006450/2a6aa2585763cb15e5b9ba414d5b48898c6394b9.jpeg', '"The year is 2021, and the human race is - quite literally - coming to an end. Since 1995 no babies have been born, because in that year all males unexpectedly became infertile. Great Britain is ruled by a dictator, and the population is inexorably growing older. Theodore Faron, Oxford historian and, incidentally, cousin of the all-powerful Warden of England, watches in growing despair as society gradually crumbles around him, giving way to strange faiths and cruelties: prison camps, mass organized euthanasia, roving bands of thugs. Then, suddenly, Faron is drawn into the plans of an unlikely group of revolutionaries. His passivity is shattered, and the action begins." "The Children of Men will surprise - and enthrall - P.D. James fans. Written with the same rich blend of keen characterization, narrative drive and suspense as her great detective stories, it engages powerfully with new themes: conflicts of loyalty and duty, the corruption of power, redemption through love. Ingenious, original, irresistibly readable, it confirms once again P.D. James''s standing as a major novelist."--Jacket.', 351, null, 1992, 377197, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Teller of Small Fortunes', 'Julie Leong', '1399729055', 'https://assets.hardcover.app/edition/31441594/06da0d475fd99250302cbc94878c32acc52a3a05.jpeg', 'Tao is an immigrant fortune teller, traveling between villages with just her trusty mule for company. She only tells “small” fortunes: whether it will hail next week; which boy the barmaid will kiss; when the cow will calve. She knows from bitter experience that big fortunes come with big consequences…

Even if it’s a lonely life, it’s better than the one she left behind. But a small fortune unexpectedly becomes something more when a (semi) reformed thief and an ex-mercenary recruit her into their desperate search for a lost child. Soon, they’re joined by a baker with a “knead” for adventure, and—of course—a slightly magical cat.

Tao starts down a new path with companions as big-hearted as her fortunes are small. But as she lowers her walls, the shadows of her past close in—and she’ll have to decide whether to risk everything to preserve the family she never thought she could have.', 320, 597, 2024, 1194212, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The City and the Stars', 'Arthur C. Clarke', '8575325191', 'https://assets.hardcover.app/external_data/47685539/441ee04e6e2056936f1abc657f78439a52b81d41.jpeg', 'Men had built cities before, but never such a city as Diaspar; for millennia its protective dome shutout the creeping decay and danger of the world outside. Once, it held powers that rules the stars. But then, as legend had it, The invaders came, driving humanity into this last refuge. It takes one man, A Unique to break through Diaspar¿s stifling inertia, to smash the legend and discover the true nature of the Invaders.', 254, null, 1956, 427323, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wild Robot', 'Peter  Brown', '8551001930', 'https://assets.hardcover.app/external_data/23225629/e73a1ba1945aec9fcdbadbb744782e350a3af616.jpeg', 'When robot Roz opens her eyes for the first time, she discovers that she is alone on a remote, wild island. She has no idea how she got there or what her purpose is--but she knows she needs to survive. After battling a fierce storm and escaping a vicious bear attack, she realizes that her only hope for survival is to adapt to her surroundings and learn from the island''s unwelcoming animal inhabitants.

As Roz slowly befriends the animals, the island starts to feel like home--until, one day, the robot''s mysterious past comes back to haunt her.', 288, 255, 2016, 150193, (select id from series where hardcover_id = 5706), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dream Hotel', 'Laila Lalami', '0593469801', 'https://assets.hardcover.app/external_data/61792080/69cea9c6bfdc066d8e987e36df4e54685cf4d383.jpeg', '"Using data from her dreams, the RAA’s algorithm has determined that she is at imminent risk of harming the person she loves most: her husband. For his safety, she must be kept under observation for twenty-one days.

The agents transfer Sara to a retention center, where she is held with other dreamers, all of them women trying to prove their innocence from different crimes. With every deviation from the strict and ever-shifting rules of the facility, their stay is extended. Months pass and Sara seems no closer to release. Then one day, a new resident arrives, disrupting the order of the facility and leading Sara on a collision course with the very companies that have deprived her of her freedom."-- Provided by Amazon', null, 702, 2025, 1633712, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Future', 'Naomi Alderman', '8807035723', 'https://assets.hardcover.app/edition/30836330/3c3872f3-4e87-4e43-8d7f-95b7bf0dffc0.jpg', 'The bestselling, award-winning author of The Power delivers a dazzling tour de force where a handful of friends plot a daring heist to save the world from the tech giants whose greed threatens life as we know it.

When Martha Einkorn fled her father’s isolated compound in Oregon, she never expected to find herself working for a powerful social media mogul hell-bent on controlling everything. Now, she’s surrounded by mega-rich companies designing private weather, predictive analytics, and covert weaponry, while spouting technological prophecy. Martha may have left the cult, but if the apocalyptic warnings in her father’s fox and rabbit sermon—once a parable to her—are starting to come true, how much future is actually left?

Across the world, in a mall in Singapore, Lai Zhen, an internet-famous survivalist, flees from an assassin. She’s cornered, desperate and—worst of all—might die without ever knowing what''s going on. Suddenly, a remarkable piece of software appears on her phone telling her exactly how to escape. Who made it? What is it really for? And if those behind it can save her from danger, what do they want from her, and what else do they know about the future?

Martha and Zhen’s worlds are about to collide. An explosive chain of events is set in motion. While a few billionaires assured of their own safety lead the world to destruction, Martha’s relentless drive and Zhen’s insatiable curiosity could lead to something beautiful or the cataclysmic end of civilization.

By turns thrilling, hilarious, tender, and always piercingly brilliant, The Futureunfolds at a breakneck speed, highlighting how power corrupts the few who have it and what it means to stand up to them. The future is coming. The Future is here.', 432, 783, 2023, 824768, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ones Who Walk Away from Omelas', 'Ursula K. Le Guin', '2381631208', 'https://assets.hardcover.app/external_data/650665/04cf836704be8b588af3803ea6bce26f9ff41f95.jpeg', 'Some inhabitants of a peaceful kingdom cannot tolerate the act of cruelty that underlies its happiness.', 32, null, 1973, 1248670, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hexed', 'Kevin Hearne', '3608106618', 'https://assets.hardcover.app/external_data/59815077/38263b852893143d9f476eb1949f7e2a321a1457.jpeg', 'Atticus O’Sullivan has had cause to mistrust witches in his storied past, but he’s willing to live and let live with the Sisters of the Three Auroras, a legendary local coven, even going so far as to sign a non-aggression treaty with them. But that treaty is tested immediately when a deadly new coven sweeps into town seeking to take over, along with some Bacchants from Las Vegas and a fallen angel who’s decided to snack on high school students like they were trail mix.

It’s more than Atticus can handle alone and he must enlist the trickster Coyote, the headhopping abilities of the witch Laksha Kulesekaran, and his neighbor’s illegal arsenal if he wants to keep the city safe from diabolical takeover. He must also exchange favors with his vampire attorney, Leif Helgarson, in a deal that might prove to be the worst of his long life—for Leif doesn’t want to be paid by the hour.

To defeat the mortal hexes of this new coven and keep his apprentice—and his city—safe, Atticus must think fast, make promises, keep his sword handy, and hope he’ll survive to fight another day.', 320, 532, 2011, 429262, (select id from series where hardcover_id = 1290), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pestilence', 'Laura Thalassa', '8027609690', 'https://assets.hardcover.app/edition/30692896/0f6041c96ca736b83aaee5692bacf44f9c4fb486.jpeg', 'When Pestilence comes for Sara Burn’s town, one thing is certain: everyone she knows and loves is marked for death. Unless, of course, the angelic-looking horseman is stopped, which is exactly what Sara has in mind when she shoots the unholy beast off his steed.

Too bad no one told her Pestilence can’t be killed.

Now the horseman, very much alive and very pissed off, has taken her prisoner, and he’s eager to make her suffer. Only, the longer she’s with him, the more uncertain she is about his true feelings towards her… and hers towards him.

And now, well, Sara might still be able to save the world, but in order to do so, she''ll have to sacrifice her heart in the process.

From bestselling indie author Laura Thalassa comes a dark fantasy romance between the Horseman Pestilence and Sara, the girl who shoots Pestilence down only to realize he can''t be killed. He takes her as prisoner, but the longer they''re together, the more uncertain their feelings for each other grow.', 416, 682, 2018, 459951, (select id from series where hardcover_id = 2459), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Thousand Names', 'Django Wexler', '1470366231', 'https://assets.hardcover.app/external_data/1280375/c459a6ece4686c9536381a204e3788ad09b52c53.jpeg', 'Enter an epic fantasy world that echoes with the thunder of muskets and the clang of steel—but where the real battle is against a subtle and sinister magic....

Captain Marcus d’Ivoire, commander of one of the Vordanai empire’s colonial garrisons, was resigned to serving out his days in a sleepy, remote outpost. But that was before a rebellion upended his life. And once the powder smoke settled, he was left in charge of a demoralized force clinging tenuously to a small fortress at the edge of the desert.

To flee from her past, Winter Ihernglass masqueraded as a man and enlisted as a ranker in the Vordanai Colonials, hoping only to avoid notice. But when chance sees her promoted to command, she must win the hearts of her men and lead them into battle against impossible odds.

The fates of both these soldiers and all the men they lead depend on the newly arrived Colonel Janus bet Vhalnich, who has been sent by the ailing king to restore order. His military genius seems to know no bounds, and under his command, Marcus and Winter can feel the tide turning. But their allegiance will be tested as they begin to suspect that the enigmatic Janus’s ambitions extend beyond the battlefield and into the realm of the supernatural—a realm with the power to ignite a meteoric rise, reshape the known world, and change the lives of everyone in its path.', 609, null, 2013, 445516, (select id from series where hardcover_id = 2963), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Untethered Sky', 'Fonda Lee', '6178287623', 'https://assets.hardcover.app/external_data/61253573/e730c2793ad29ea9c3bd4cb987941acef3623a1d.jpeg', 'Ester’s family was torn apart when a manticore killed her mother and baby brother, leaving her with nothing but her father’s painful silence and a single, overwhelming need to kill the monsters that took her family.

Ester’s path leads her to the King’s Royal Mews, where the giant rocs of legend are flown to hunt manticores by their brave and dedicated ruhkers. Paired with a fledgling roc named Zahra, Ester finds purpose and acclaim by devoting herself to a calling that demands absolute sacrifice and a creature that will never return her love. The terrifying partnership between woman and roc leads Ester not only on the empire’s most dangerous manticore hunt, but on a journey of perseverance and acceptance.', 150, 239, 2023, 504589, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Babel-17', 'Samuel R. Delany', '0575094206', 'https://assets.hardcover.app/edition/30405445/36c9923b-4697-4903-9b88-e7b227de38a8.jpg', 'In "Babel-17," Rydra Wong, a poet and code expert, must break an enemy government''s code, but discovers that the code is really a supersophisticated language, while in "Empire Star," a simple-minded teenager is entrusted to carry a vital message to a distant world.', 193, null, 1966, 430657, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The World We Make', 'N. K. Jemisin', '8410466058', 'https://assets.hardcover.app/edition/30556677/50a8c3d7-311d-4f96-ae8e-5e76544283ef.jpg', 'Every great city has a soul. A human avatar that embodies their city’s heart and wields its magic. New York? She’s got six.

But all is not well in the city that never sleeps. Though Brooklyn, Manny, Bronca, Venezia, Padmini, and Neek have temporarily managed to stop the Woman in White from invading–and destroying the entire universe in the process–the mysterious capital “E” Enemy has more subtle powers at her disposal. A new candidate for mayor wielding the populist rhetoric of gentrification, xenophobia, and “law and order” may have what it takes to change the very nature of New York itself and take it down from the inside. In order to defeat him, and the Enemy who holds his purse strings, the avatars will have to join together with the other Great Cities of the world in order to bring her down for good and protect their world from complete destruction.', 369, 778, 2022, 503491, (select id from series where hardcover_id = 1198), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights With Monsters 8', 'Shirtaloon, Travis Deverell', '1039410006', 'https://assets.hardcover.app/editions/30616096/203d8e58-ce98-4a19-a0c8-269c7e157082.jpg', 'After a much longed-for reunion, Jason Asano works on moving past old traumas as he looks to a brighter future.

Despite warnings of dangers awaiting him in the future, Jason gets back in the saddle as an adventurer, ready to tackle new challenges. Those challenges are not hard to find as enemies that have lurked in the background start moving into the light.

Jason and his friends don’t wait passively and use schemes of their own to take the fight to the enemy. Jason’s companions find themselves plunged into dangerous missions and confronted with enemies both personal and unexpected. Jason will push new boundaries, and while it comes at a cost, it will move him deeper into the realms of cosmic power.', 765, 1092, 2022, 638211, (select id from series where hardcover_id = 12723), 8) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Spell or High Water', 'Scott Meyer', '1491519606', 'https://assets.hardcover.app/editions/17454660/713177648480365.jpg', 'The adventures of an American hacker in Medieval England continue as Martin Banks takes his next step on the journey toward mastering his reality-altering powers and fulfilling his destiny.

A month has passed since Martin helped to defeat the evil programmer Jimmy, and things couldn’t be going better. Except for his love life, that is. Feeling distant and lost, Gwen has journeyed to Atlantis, a tolerant and benevolent kingdom governed by the Sorceresses, and a place known to be a safe haven to all female time-travelers.

Thankfully, Martin and Philip are invited to a summit in Atlantis for all of the leaders of the time-traveler colonies, and now Martin thinks this will be a chance to try again with Gwen. Of course, this is Martin Banks we’re talking about, so murder, mystery, and high intrigue all get in the way of a guy who just wants one more shot to get the girl.

The follow-up to the hilarious Off to Be the Wizard, Scott Meyer’s Spell or High Water proves that no matter what powers you have over time and space, you can’t control rotten luck.', 431, 699, 2014, 427559, (select id from series where hardcover_id = 1028), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('SpecOps', 'Craig Alanson', '8366375501', 'https://assets.hardcover.app/books/435290/1454299551414571.jpg', 'Colonel Joe Bishop made a promise and he''s going to keep it; taking the captured alien starship Flying Dutchman back out.

He doesn''t agree when the UN decides to send almost 70 elite Special Operations troops, hotshot pilots, and scientists with him; the mission is a fool''s errand he doesn''t expect to ever return from. At least, this time, the Earth is safe, right?

Not so much.', 277, 950, 2016, 435290, (select id from series where hardcover_id = 1086), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Light Brigade', 'Kameron Hurley', '8491816402', 'https://assets.hardcover.app/edition/18884538/b414170bd4a1e558ca6777fd11aef199eed021ab.jpeg', 'From the Hugo Award­­–winning author of The Stars Are Legion comes a brand-new science fiction thriller about a futuristic war during which soldiers are broken down into light in order to get them to the front lines on Mars.

They said the war would turn us into light.
I wanted to be counted among the heroes who gave us this better world.

The Light Brigade: it’s what soldiers fighting the war against Mars call the ones who come back…different. Grunts in the corporate corps get busted down into light to travel to and from interplanetary battlefronts. Everyone is changed by what the corps must do in order to break them down into light. Those who survive learn to stick to the mission brief—no matter what actually happens during combat.

Dietz, a fresh recruit in the infantry, begins to experience combat drops that don’t sync up with the platoon’s. And Dietz’s bad drops tell a story of the war that’s not at all what the corporate brass want the soldiers to think is going on.

Is Dietz really experiencing the war differently, or is it combat madness? Trying to untangle memory from mission brief and survive with sanity intact, Dietz is ready to become a hero—or maybe a villain; in war it’s hard to tell the difference.

A worthy successor to classic stories like Downbelow Station, Starship Troopers, and The Forever War, The Light Brigade is award-winning author Kameron Hurley’s gritty time-bending take on the future of war.', 396, 622, 2019, 440168, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Valis', 'Philip K. Dick', '9532862102', 'https://assets.hardcover.app/external_data/919071/b721bd27bf9aa79b0de1a5f3aba3d1b677925f25.jpeg', 'It began with a blinding light, a divine revelation from a mysterious intelligence that called itself VALIS (Vast Active Living Intelligence System). And with that, the fabric of reality was torn apart and laid bare so that anything seemed possible, but nothing seemed quite right. It was madness, pure and simple. But what if it were true?', 195, null, 1981, 457364, (select id from series where hardcover_id = 7748), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The City in the Middle of the Night', 'Charlie Jane Anders', '1664447512', 'https://assets.hardcover.app/book_mappings/7333405/6972bb62661f1aa193830ccb7a67f0f5d83b83da.jpeg', 'Would you give up everything to change the world?

Humanity clings to life on January – a colonized planet divided between permanently frozen darkness on one side, and blazing endless sunshine on the other.

Two cities, built long ago in the meager temperate zone, serve as the last bastions of civilization – but life inside them is just as dangerous as the uninhabitable wastelands outside.

Sophie, a young student from the wrong side of Xiosphant city, is exiled into the dark after being part of a failed revolution. But she survives--with the help of a mysterious savior from beneath the ice.

Burdened with a dangerous, painful secret, Sophie and her ragtag group of exiles face the ultimate challenge – and they are running out of time.

Welcome to the City in the Middle of the Night', 366, 836, 2018, 237533, (select id from series where hardcover_id = 5544), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('We Hunt the Flame', 'Hafsah Faizal', '1529045177', 'https://assets.hardcover.app/external_data/24939944/9dad4261b0f44dce5779cc5452a7ad96061a78c0.jpeg', 'Zafira is the Hunter, disguising herself as a man when she braves the cursed forest of the Arz to feed her people. Nasir is the Prince of Death, assassinating those foolish enough to defy his autocratic father, the sultan. If Zafira was exposed as a girl, all of her achievements would be rejected; if Nasir displayed his compassion, his father would punish him in the most brutal of ways. Both Zafira and Nasir are legends in the kingdom of Arawiya--but neither wants to be.

War is brewing, and the Arz sweeps closer with each passing day, engulfing the land in shadow. When Zafira embarks on a quest to uncover a lost artifact that can restore magic to her suffering world and stop the Arz, Nasir is sent by the sultan on a similar mission: retrieve the artifact and kill the Hunter. But an ancient evil stirs as their journey unfolds--and the prize they seek may pose a threat greater than either can imagine.', 480, 885, 2019, 379371, (select id from series where hardcover_id = 5577), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Witch''s Heart', 'Genevieve Gornichec', '0593346629', 'https://assets.hardcover.app/external_data/60820932/cd2ac16fa3464d298e7436aef67536b6960f2f4b.jpeg', 'When a banished witch falls in love with the legendary trickster Loki, she risks the wrath of the gods in this moving, subversive debut novel that reimagines Norse mythology.
 
Angrboda’s story begins where most witches’ tales end: with a burning. A punishment from Odin for refusing to provide him with knowledge of the future, the fire leaves Angrboda injured and powerless, and she flees into the farthest reaches of a remote forest. There she is found by a man who reveals himself to be Loki, and her initial distrust of him transforms into a deep and abiding love.
 
Their union produces three unusual children, each with a secret destiny, who Angrboda is keen to raise at the edge of the world, safely hidden from Odin’s all-seeing eye. But as Angrboda slowly recovers her prophetic powers, she learns that her blissful life—and possibly all of existence—is in danger.
 
With help from the fierce huntress Skadi, with whom she shares a growing bond, Angrboda must choose whether she’ll accept the fate that she’s foreseen for her beloved family…or rise to remake their future. From the most ancient of tales this novel forges a story of love, loss, and hope for the modern age.', 369, null, 2021, 465190, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wishing Game', 'Meg Shaffer', '1529436265', 'https://assets.hardcover.app/edition/32018566/ced6e019-a6e6-4c9a-9355-b79d4cb5d3af.jpg', 'Make a wish. . . .

Lucy Hart knows better than anyone what it’s like to grow up without parents who loved her. In a childhood marked by neglect and loneliness, Lucy found her solace in books, namely the Clock Island series by Jack Masterson. Now a twenty-six-year-old teacher’s aide, she is able to share her love of reading with bright, young students, especially seven-year-old Christopher Lamb, who was left orphaned after the tragic death of his parents. Lucy would give anything to adopt Christopher, but even the idea of becoming a family seems like an impossible dream without proper funds and stability.

But be careful what you wish for. . . .

Just when Lucy is about to give up, Jack Masterson announces he’s finally written a new book. Even better, he’s holding a contest at his home on the real Clock Island, and Lucy is one of the four lucky contestants chosen to compete to win the one and only copy.

For Lucy, the chance of winning the most sought-after book in the world means everything to her and Christopher. But first she must contend with ruthless book collectors, wily opponents, and the distractingly handsome (and grumpy) Hugo Reese, the illustrator of the Clock Island books. Meanwhile, Jack “the Mastermind” Masterson is plotting the ultimate twist ending that could change all their lives forever.

. . . You might just get it.', 305, 793, 2023, 659718, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hush, Hush', 'Becca Fitzpatrick', '6075294538', 'https://assets.hardcover.app/edition/30705320/7a83b0633b1dbb5caee10dd7946c464e474979f1.jpeg', 'It''s a great story about a Nephilum and a fallen angel that have a hard time balancing responsibility, school, and life all together. They love each other but to other''s it''s wrong and shouldn''t be. but to them.......just read the book and see.', 432, 536, 2009, 157111, (select id from series where hardcover_id = 10929), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Winter''s Promise', 'Christelle Dabos, Hildegarde Serle', '1609456076', 'https://assets.hardcover.app/edition/30938112/85bd3e68-1e5c-43d6-a1e5-1a199c264923.jpeg', '“A stunningly atmospheric fantasy that doubles as an exceptional character study . . . we can’t wait to see where Dabos takes it next.” —Entertainment Weekly (“The 10 Best YA Books of 2018”) One of Publishers Weekly’s Best YA Books of the Year A National Indie Bestseller Lose yourself in the fantastic world of the arks and in the company of unforgettable characters in this French runaway hit, Christelle Dabos’ The Mirror Visitor quartet. Plain-spoken, headstrong Ophelia cares little about appearances. Her ability to read the past of objects is unmatched in all of Anima and, what’s more, she possesses the ability to travel through mirrors, a skill passed down to her from previous generations. Her idyllic life is disrupted, however, when she is promised in marriage to Thorn, a taciturn and influential member of a distant clan. Ophelia must leave all she knows behind and follow her fiancé to Citaceleste, the capital of a cold, icy ark known as the Pole, where danger lurks around every corner and nobody can be trusted. There, in the presence of her inscrutable future husband, Ophelia slowly realizes that she is a pawn in a political game that will have far-reaching ramifications not only for her but for her entire world. The World of the Arks Long ago, following a cataclysm called the Rupture, the world was shattered into many floating celestial islands, now known as arks. Over each, the spirit of an omnipotent and immortal ancestor abides. The inhabitants of these arks each possess a unique power. Ophelia, with her ability to read the pasts of objects, must navigate this fantastic, disjointed, perilous world using her trademark tenacity and quiet strength.', 448, 884, 2013, 914465, (select id from series where hardcover_id = 5588), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wind in the Willows', 'Kenneth Grahame', '0194230228', 'https://assets.hardcover.app/edition/22940335/4330bff5bc70b2ac7104064c1ca8bead163f7303.jpeg', 'The adventures of four amiable animals, Rat, Toad, Mole and Badger, along a river in the English countryside.', 324, null, 1908, 115289, (select id from series where hardcover_id = 53357), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Curse So Dark and Lonely', 'Brigid Kemmerer', '880474488X', 'https://assets.hardcover.app/edition/17818948/743cd3e05c879e545182dc4c1dbf01d57827b0e4.jpeg', '"It once seemed so easy to Prince Rhen, the heir to Emberfall. Cursed by a powerful enchantress to repeat the autumn of his eighteenth year over and over, he knew he could be saved if a girl fell for him. But that was before he learned that at the end of each autumn, he would turn into a vicious beast hell-bent on destruction. That was before he destroyed his castle, his family, and every last shred of hope.

Nothing has ever been easy for Harper. With her father long gone, her mother dying, and her brother barely holding their family together while constantly underestimating her because of her cerebral palsy, she learned to be tough enough to survive. But when she tries to save someone else on the streets of Washington, DC, she’s instead somehow sucked into Rhen’s cursed world.

Break the curse, save the kingdom.

A prince? A monster? A curse? Harper doesn’t know where she is or what to believe. But as she spends time with Rhen in this enchanted land, she begins to understand what’s at stake. And as Rhen realizes Harper is not just another girl to charm, his hope comes flooding back. But powerful forces are standing against Emberfall . . . and it will take more than a broken curse to save Harper, Rhen, and his people from utter ruin."-- Provided by Amazon', 517, null, 2019, 1421897, (select id from series where hardcover_id = 5863), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shadows Between Us', 'Tricia Levenseller', '8328720906', 'https://assets.hardcover.app/editions/2319416/2522349704868141.jpg', 'Alessandra is tired of being overlooked, but she has a plan to gain power:

1) Woo the Shadow King.

2) Marry him.

3) Kill him and take his kingdom for herself

No one knows the extent of the freshly crowned Shadow King’s power. Some say he can command the shadows that swirl around him to do his bidding. Others say they speak to him, whispering the thoughts of his enemies. Regardless, Alessandra knows what she deserves, and she’s going to do everything within her power to get it.

But Alessandra’s not the only one trying to kill the king. As attempts on his life are made, she finds herself trying to keep him alive long enough for him to make her his queen—all while struggling not to lose her heart. After all, who better for a Shadow King than a cunning, villainous queen?

They should know better, not to underestimate her...', 336, 593, 2020, 451636, (select id from series where hardcover_id = 6697), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Eternity Code', 'Eoin Colfer', '9050006337', 'https://assets.hardcover.app/edition/30751500/a216b5a9-4d9f-4a53-afcd-63edc693c7bd.jpg', 'Thirteen-year-old criminal mastermind Artemis Fowl has constructed a supercomputer from stolen fairy technology. In the wrong hands it could be fatal for humans and fairies alike. But no need to worry, Artemis has a brilliant plan. He''s not going to use the computer; he''s just going to show it to a ruthless American businessman with Mafia connections. His bodyguard, Butler, will be with him. What could possibly go wrong...?', 309, null, 2003, 72561, (select id from series where hardcover_id = 1374), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lore', 'Alexandra Bracken', '9781368002318', 'https://assets.hardcover.app/edition/26228631/10830320-L.jpg', 'Every seven years, the Agon begins. As punishment for a past rebellion, nine Greek gods are forced to walk the earth as mortals. They are hunted by the descendants of ancient bloodlines, all eager to kill a god and seize their divine power and immortality.

Long ago, Lore Perseous fled that brutal world, turning her back on the hunt’s promises of eternal glory after her family was murdered by a rival line. For years she''s pushed away any thought of revenge against the man—now a god—responsible for their deaths.

Yet as the next hunt dawns over New York City, two participants seek her out: Castor, a childhood friend Lore believed to be dead, and Athena, one of the last of the original gods, now gravely wounded.

The goddess offers an alliance against their mutual enemy and a way to leave the Agon behind forever. But Lore''s decision to rejoin the hunt, binding her fate to Athena''s, will come at a deadly cost—and it may not be enough to stop the rise of a new god with the power to bring humanity to its knees.', 552, 897, 2021, 428650, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Witch''s Guide to Magical Innkeeping', 'Sangu Mandanna', '8466680861', 'https://assets.hardcover.app/edition/31503368/2a3bb4eb8df6a4f32aa5a715089e2f44e395ab1d.jpeg', 'Sera Swan was once one of the most powerful witches in Britain. Then she resurrected her great-aunt Jasmine from the (very recently) dead, lost most of her magic, befriended a semi-villainous talking fox, and was exiled from her magical Guild. 

Now she (slightly reluctantly and a bit grumpily) helps Aunt Jasmine run an inn in Lancashire, where she deals with her quirky guest’s shenanigans, tries to keep the talking fox in check, and longs for the magical future she lost. 

When she learns about an old spell book that could hold the secret to restoring her power, she finds herself turning to Luke Larsen, a gorgeous and icy historian who might be the only person who can help her unlock the book’s mysteries. 

The fact that he also happens to be her one-night stand from years ago is totally irrelevant. 

Running an inn, reclaiming lost magic, and trying not to fall in love is a lot for anyone, but Sera is about to discover that she doesn’t have to do it alone...and that the weird, wonderful family she’s made might be the best magic of all.', 352, 600, 2025, 792128, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ella Enchanted', 'Gail Carson Levine', '0062253484', 'https://assets.hardcover.app/external_data/3904779/083e87d19b115f3ebc43938b5603bbc261005dc6.jpeg', 'In this novel based on the story of Cinderella, Ella struggles against the childhood curse that forces her to obey any order given to her.', 292, null, 1997, 196248, (select id from series where hardcover_id = 3237), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Winter King', 'Bernard Cornwell', '8830461458', 'https://assets.hardcover.app/edition/3073019/3448764bef9ec602da8b86c832378a995f4f6d7f.jpeg', 'With The Winter King, the first volume of his magnificent Warlord Chronicles, Bernard Cornwell turns to the story he was born to write: the mythic saga of King Arthur. Now a major television show.

The tale begins in Dark Age Britain, a land where Arthur has been banished and Merlin has disappeared, where a child-king sits unprotected on the throne, where religion vies with magic for the souls of the people. It is to this desperate land that Arthur returns, a man at once utterly human and truly heroic: a man of honor, loyalty, and amazing valor; a man who loves Guinevere more passionately than he should; a man whose life is at once tragic and triumphant.

As Arthur fights to keep a flicker of civilization alive in a barbaric world, Bernard Cornwell makes a familiar tale into a legend all over again.', 448, null, 1994, 185390, (select id from series where hardcover_id = 6966), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Thorn of Emberlain', 'Scott Lynch', '0575088834', 'https://assets.hardcover.app/external_data/61259105/f604e1ed4d507e5e1e84c5c73a697cb2a9af2820.jpeg', 'With 50,000 copies sold of The Republic of Thieves and with praise from the likes of Joe Abercrombie and George RR Martin the saga of the Gentleman Bastard has become a favourite and key part of the fantasy landscape. And now Locke Lamora, thief, con-man, pirate, political deceiver must become a soldier. A new chapter for Locke and Jean and finally the war that has been brewing in the Kingdom of the Marrows flares up and threatens to capture all in its flames. And all the while Locke must try to deal with the disturbing rumours about his past revealed in The Republic of Thieves. Fighting a war when you don''t know the truth of right and wrong is one thing. Fighting a war when you don''t know the truth of yourself is quite another. Particularly when you''ve never been that good with a sword anyway...', 512, null, null, 433217, (select id from series where hardcover_id = 1128), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Beautiful Creatures', 'Kami Garcia, Margaret Stohl', '0316042676', 'https://assets.hardcover.app/external_data/36345217/02a7ea992552030931b37e05bd0fc2586d47eda2.jpeg', 'In a small South Carolina town, where it seems little has changed since the Civil War, sixteen-year-old Ethan is powerfully drawn to Lena, a new classmate with whom he shares a psychic connection and whose family hides a dark secret that may be revealed on her sixteenth birthday.', 592, 1056, 2009, 24651, (select id from series where hardcover_id = 5625), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ruins of Gorlan', 'John Flanagan', '3570270726', 'https://assets.hardcover.app/edition/26128648/3e191fbec96a8ff3d993c21cee2c785cfe0f76ee.jpeg', 'They have always scared him in the past--the Rangers, with their dark cloaksand shadowy ways. The villagers believe the Rangers practice magic that makes them invisible to ordinary people. And now 15-year-old Will, always small for his age, has been chosen as a Ranger''s apprentice. What he doesn''t yet realize is that the Rangers are the protectors of the kingdom. Highly trained in the skills of battle and surveillance, they fight the battles before the battles reach the people. And as Will is about to learn, there is a large battle brewing. The exiled Morgarath, Lord of the Mountains of Rain and Night, is gathering his forces for an attack on the kingdom. This time, he will not be denied...', 274, null, 2004, 66923, (select id from series where hardcover_id = 2965), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dream Thieves', 'Maggie Stiefvater, Will Patton', '0545721121', 'https://assets.hardcover.app/edition/19822911/3cec8bf9647bf0a7789c944e059a0c1ff2b323ad.jpeg', 'Ronan Lynch has secrets. Some he keeps from others. Some he keeps from himself.

One secret: Ronan can bring things out of his dreams.

And sometimes he''s not the only one who wants those things.

Ronan is one of the raven boys - a group of friends, practically brothers, searching for a dead king named Glendower, who they think is hidden somewhere in the hills by their elite private school, Aglionby Academy. The path to Glendower has long lived as an undercurrent beneath town. But now, like Ronan''s secrets, it is beginning to rise to the surface - changing everything in its wake.', null, 760, 2013, 109533, (select id from series where hardcover_id = 3226), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wrath & the Dawn', 'Renée Ahdieh', '1473657938', 'https://assets.hardcover.app/editions/30399520/3223154836598275.jpg', 'Every dawn brings horror to a different family in a land ruled by a killer. Khalid, the eighteen-year-old Caliph of Khorasan, takes a new bride each night only to have her executed at sunrise. So it is a suspicious surprise when sixteen-year-old Shahrzad volunteers to marry Khalid. But she does so with a clever plan to stay alive and exact revenge on the Caliph for the murder of her best friend and countless other girls. Shazi’s wit and will, indeed, get her through to the dawn that no others have seen, but with a catch . . . she’s falling in love with the very boy who killed her dearest friend.

She discovers that the murderous boy-king is not all that he seems and neither are the deaths of so many girls. Shazi is determined to uncover the reason for the murders and to break the cycle once and for all.', 418, null, 2015, 324503, (select id from series where hardcover_id = 1154), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('What the River Knows', 'Isabel Ibañez', '125033604X', 'https://assets.hardcover.app/edition/31694647/c0fe24ecdd7fea2b533b24f8eaa6e65d20f29a20.jpeg', 'Bolivian-Argentinian Inez Olivera belongs to the glittering upper society of nineteenth century Buenos Aires, and like the rest of the world, the town is steeped in old world magic that’s been largely left behind or forgotten. Inez has everything a girl might want, except for the one thing she yearns the most: her globetrotting parents—who frequently leave her behind.

When she receives word of their tragic deaths, Inez inherits their massive fortune and a mysterious guardian, an archeologist in partnership with his Egyptian brother-in-law. Yearning for answers, Inez sails to Cairo, bringing her sketch pads and a golden ring her father sent to her for safekeeping before he died. But upon her arrival, the old world magic tethered to the ring pulls her down a path where she soon discovers there’s more to her parent’s disappearance than what her guardian led her to believe.

With her guardian’s infuriatingly handsome assistant thwarting her at every turn, Inez must rely on ancient magic to uncover the truth about her parent’s disappearance—or risk becoming a pawn in a larger game that will kill her.', 416, 1020, 2023, 735454, (select id from series where hardcover_id = 72506), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('In Five Years', 'Rebecca Serle', '802494412X', 'https://assets.hardcover.app/edition/9177289/3871f7de4206ab2db882ac2ef527f5e485e421a2.jpeg', 'Dannie Kohan lives her life by the numbers.

She is nothing like her lifelong best friend—the wild, whimsical, believes-in-fate Bella. Her meticulous planning seems to have paid off after she nails the most important job interview of her career and accepts her boyfriend’s marriage proposal in one fell swoop, falling asleep completely content.

But when she awakens, she’s suddenly in a different apartment, with a different ring on her finger, and beside a very different man. Dannie spends one hour exactly five years in the future before she wakes again in her own home on the brink of midnight—but it is one hour she cannot shake. In Five Years is an unforgettable love story, but it is not the one you’re expecting.', 255, null, 2020, 428440, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Stolen Heir', 'Holly Black', '1471411389', 'https://assets.hardcover.app/edition/32461263/35d9deb2670e0b1e5ebbad2d2e7621d08f1518b8.jpeg', 'Eight years have passed since the Battle of the Serpent. But in the icy north, Lady Nore of the Court of Teeth has reclaimed the Ice Needle Citadel. There, she is using an ancient relic to create monsters of stick and snow who will do her bidding and exact her revenge.

Suren, child queen of the Court of Teeth, and the one person with power over her mother, fled to the human world. There, she lives feral in the woods. Lonely, and still haunted by the merciless torments she endured in the Court of Teeth, she bides her time by releasing mortals from foolish bargains. She believes herself forgotten until the storm hag, Bogdana chases her through the night streets. Suren is saved by none other than Prince Oak, heir to Elfhame, to whom she was once promised in marriage and who she has resented for years.

Now seventeen, Oak is charming, beautiful, and manipulative. He’s on a mission that will lead him into the north, and he wants Suren’s help. But if she agrees, it will mean guarding her heart against the boy she once knew and a prince she cannot trust, as well as confronting all the horrors she thought she left behind.', 352, 609, 2023, 526027, (select id from series where hardcover_id = 24827), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Salt and Sorrows', 'Erin A. Craig', '198483195X', 'https://assets.hardcover.app/external_data/61558981/f932f1a107ef8bcb188e7c18bef3ce21e64fb221.jpeg', 'Annaleigh lives a sheltered life at Highmoor, a manor by the sea, with her sisters, their father, and stepmother. Once they were twelve, but loneliness fills the grand halls now that four of the girls'' lives have been cut short. Each death was more tragic than the last—the plague, a plummeting fall, a drowning, a slippery plunge—and there are whispers throughout the surrounding villages that the family is cursed by the gods.

Disturbed by a series of ghostly visions, Annaleigh becomes increasingly suspicious that the deaths were no accidents. Her sisters have been sneaking out every night to attend glittering balls, dancing until dawn in silk gowns and shimmering slippers, and Annaleigh isn''t sure whether to try to stop them or to join their forbidden trysts. Because who—or what—are they really dancing with?

When Annaleigh''s involvement with a mysterious stranger who has secrets of his own intensifies, it''s a race to unravel the darkness that has fallen over her family—before it claims her next.', 403, null, 2019, 428697, (select id from series where hardcover_id = 57295), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dandelion Wine', 'Ray Bradbury', '8804715308', 'https://assets.hardcover.app/edition/20810446/df82abf27d34d34fae314e854dc59ae8d5d6ea17.jpeg', 'The summer of ''28 was a vintage season for a growing boy. A summer of green apple trees, mowed lawns, and new sneakers. Of half-burnt firecrackers, of gathering dandelions, of Grandma''s belly-busting dinner. It was a summer of sorrows and marvels and gold-fuzzed bees. A magical, timeless summer in the life of a twelve-year-old boy named Douglas Spaulding—remembered forever by the incomparable Ray Bradbury.

Dandelion Wine is unique amongst the works of the popular author Ray Bradbury, in that it provides us with perhaps the clearest insight into the thoughts and feelings of the author. The book was published in 1957, perhaps over twenty years after the era which it is about, thus providing an inevitable theme of nostalgia throughout the book. The principal character, Douglas Spalding, and his brother Tom, encounter a series of adventures which are described in a crafted and distinguished manner to provide a philosophical tone throughout the book. The narrative is enriched by the experiences of individuals such as Leo Auffman, who attempts (unsuccessfully) to construct a ''Happiness machine''. Overall, the book provides a nostalgic sense of childhood and an understanding of the beauty of the world and all its features; in this way, it appears to be Bradbury himself reminiscing on his past. Douglas has similar traits to those Bradbury has later in life identified in himself, strengthening this interpretation.', 239, null, 1946, 385967, (select id from series where hardcover_id = 1129), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Clockwork Boys', 'T. Kingfisher', '161450475X', 'https://assets.hardcover.app/edition/15680234/1abca764a5b8c006455cda632fcdeb97dec94494.jpeg', 'A paladin, an assassin, a forger, and a scholar ride out of town. It’s not the start of a joke, but rather an espionage mission with deadly serious stakes. T. Kingfisher’s new novel begins the tale of a murderous band of criminals (and a scholar), thrown together in an attempt to unravel the secret of the Clockwork Boys, mechanical soldiers from a neighboring kingdom that promise ruin to the Dowager’s city.

If they succeed, rewards and pardons await, but that requires a long journey through enemy territory, directly into the capital. It also requires them to refrain from killing each other along the way! At turns darkly comic and touching, The Clocktaur War duology puts together a broken group of people trying to make the most of the rest of their lives as they drive forward on their suicide mission.', 228, 460, 2017, 449946, (select id from series where hardcover_id = 6682), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Welcome to Night Vale', 'Joseph Fink, Jeffrey Cranor', '3608961372', 'https://assets.hardcover.app/external_data/1303125/ffebff2ea82e2291c1d979d47131bf81a1364549.jpeg', 'A Waterstones Paperback of the Year and New York Times Bestseller Based on the no. 1 Podcast WELCOME TO NIGHT VALE . . . a friendly desert community where the sun is hot, the moon is beautiful, and mysterious lights pass overhead while its citizens pretend to sleep. It''s a town like your town, with a city hall, a bowling alley, a diner, and a radio station reporting all the news that''s allowed to be heard. It might be more like your town than you''d like to admit. In this ordinary town where ghosts, aliens and government conspiracies are parts of everyday life, the lives of two women, with two mysteries, are about to converge. From the creators of the wildly popular Welcome to Night Vale podcast comes an original mystery of appearances and disappearances about the ways we all struggle to find ourselves, no matter where we live.', 372, null, 2015, 467060, (select id from series where hardcover_id = 1508), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Immortal Longings', 'Chloe Gong', '9896618615', 'https://assets.hardcover.app/edition/30823153/8e85e4b6a8287cea0cd020bb8235e9a56d6717ab.jpeg', '"For those confident enough in their ability to jump between bodies, competitors across San-Er fight to the death to win unimaginable riches.

Princess Calla Tuoleimi lurks in hiding. Five years ago, a massacre killed her parents and left the palace of Er empty…and she was the one who did it. Before King Kasa’s forces in San can catch her, she plans to finish the job and bring down the monarchy. Her reclusive uncle always greets the victor of the games, so if she wins, she finally gets her opportunity to kill him.

Enter Anton Makusa, an exiled aristocrat. His childhood love has lain in a coma since they were both ousted from the palace, and he’s deep in debt trying to keep her alive. Thankfully, he’s one of the best jumpers in the kingdom, flitting from body to body at will. His last chance at saving her is entering the games and winning.

Calla finds both an unexpected alliance with Anton and help from King Kasa’s adopted son, August, who wants to mend Talin’s ills. But the three of them have very different goals, even as Calla and Anton’s partnership spirals into something all-consuming. Before the games close, Calla must decide what she’s playing for—her lover or her kingdom."-- Provided by Amazon', 384, 720, 2023, 453592, (select id from series where hardcover_id = 29132), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('An Unkindness of Ghosts', 'Rivers Solomon', '1538475030', 'https://assets.hardcover.app/external_data/4029515/f5e90ce8eb4ad572a0a89d8308788939c67b3991.jpeg', '"Aster has little to offer folks in the way of rebuttal when they call her ogre and freak. She''s used to the names; she only wishes there was more truth to them. If she were truly a monster, she''d be powerful enough to tear down the walls around her until nothing remains of her world. Aster lives in the lowdeck slums of the HSS Matilda, a space vessel organized much like the antebellum South. For generations, Matilda has ferried the last of humanity to a mythical Promised Land. On its way, the ship''s leaders have imposed harsh moral restrictions and deep indignities on dark-skinned sharecroppers like Aster. Embroiled in a grudge with a brutal overseer, Aster learns there may be a way to improve her lot--if she''s willing to sow the seeds of civil war"--Page 4 of cover.', 360, 714, 2017, 430969, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tuck Everlasting', 'Natalie Babbitt', '8499989691', 'https://assets.hardcover.app/edition/30778988/88781ccef4359a049dc7c4b7e7b97a0111eaf3eb.jpeg', '"In this timeless story young Winnie Foster learns of a hidden spring in a nearby wood and meets the Tuck family, whose members reveal their astonishing discovery of the spring’s life-changing power. 

Now Winnie must decide what to do with her newfound knowledge―and the Tucks must decide what to do with her. 

But it’s not just the curious girl who is interested in their remarkable tale. A suspicious stranger is also searching for the Tucks, and he will stop at nothing until he finds them and uncovers their secret."-- Provided by Amazon', 192, null, 1975, 15424, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The School for Good Mothers', 'Jessamine Chan', '9798200912933', 'https://assets.hardcover.app/external_data/1118658/256cc3649513278f9121a23f10168d537bd1b4f5.jpeg', '"Set in near-future America, The School for Good Mothers introduces readers to a government-run reform program where bad mothers are retrained using robot doll children with artificial intelligence. Protagonist Frida Liu, a 39-year-old Chinese-American single mother in Philadelphia, loses custody of her 18-month-old daughter, Harriet, after she leaves Harriet home alone for two hours on one very bad day. To regain custody, Frida must spend a year at a newly-created institution, where she practices parenting with bad mothers from all over the county. There, she learns to love an uncannily life-like toddler girl doll in order to demonstrate her maternal instincts and prove to her family court judge that she deserves a second chance. Frida is an outsider in every way: better educated, more affluent, and the only Asian. The mothers, whose transgressions range from benign to horrific, are under constant surveillance. If they don''t pass all the school''s tests, their parental rights will be terminated. Inspired by dystopian classics such as 1984, Never Let Me Go, and The Handmaid''s Tale, the novel eviscerates the dominant American parenting culture, while highlighting the tragedy of state-sponsored family separation. Is there one right way to mother? Can a bad mother ever be redeemed? With warmth, heart, and dark humor, the novel tells a timeless story of a mother fighting to win back her child, and her struggle to hold onto her integrity while being indoctrinated"--', 324, null, 2022, 433760, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Orconomics', 'J. Zachary Pike', '0990859622', 'https://assets.hardcover.app/edition/30408038/a3f194c81e6e1683fc8c1c10efde8e8995e1faf8.jpeg', 'PROFESSIONAL HEROES KILL AND LOOT deadly monsters every day, but Gorm Ingerson''s latest quest will be anything but business as usual. The adventuring industry drives the economy of Arth, a world much like our own but with more magic and fewer vowels. Monsters'' hoards are claimed, bought by corporate interests, and sold off to plunder funds long before the Heroes'' Guild actually kills the beasts. Of course, that''s a terrible arrangement for the Shadowkin; orcs, goblins, kobolds, and their ilk must apply for to become Noncombatant Paper Carriers (or NPCs) to avoid being killed and looted by heroes. When Gorm Ingerson, a Dwarven ex-hero with a checkered past, stands up for an undocumented goblin, he inadvertently singles himself out for recruitment by a prophet of the mad goddess to undertake a suicidal quest. But there''s more to Gorm''s new job than an insane prophecy: powerful corporations and governments have shown an unusual interest in the quest. If his party of eccentric misfits can stop fighting each other long enough to recover the Elven Marbles, Gorm might be able to turn a bad deal into a golden opportunity.', 340, 706, 2014, 445669, (select id from series where hardcover_id = 6611), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fragile Things: Short Fictions & Wonders', 'Neil Gaiman', '1439558345', 'https://assets.hardcover.app/edition/3026278/8d9c1cd0-44a7-4787-a681-9446e53af96f.jpg', 'Fragile Things showcases the distinctive storytelling genius that has made Neil Gaiman one of the most admired literary artists of our time. The thirty-two gems of prose and verse in this astonishing collection stretch the imagination and engage the intellect even as they illuminate the vagaries of human experience. Whether he’s conjuring a mysterious traveling circus, exploring the rarefied tastes of an exclusive epicurean club, or visiting a strangely altered Victorian England, Gaiman reveals how the ordinary and the fantastical are transmutable and intertwined.

With breathtaking clarity, Fragile Things illumines Gaiman’s brilliance as well as his terrifyingly entertaining dark sense of humor. By turns delightful, disturbing, and diverting, this volume is a gift of enchantments that will startle the senses and stir the soul.', 448, 647, 2006, 438928, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Every Day', 'David Levithan', '2361931737', 'https://assets.hardcover.app/edition/3494362/a6702f2594b7a4823e04ca9dc48cb2b736960469.jpeg', 'Every day a different body. Every day a different life. Every day in love with the same girl.
There’s never any warning about where it will be or who it will be. A has made peace with that, even established guidelines by which to live: Never get too attached. Avoid being noticed. Do not interfere.

It’s all fine until the morning that A wakes up in the body of Justin and meets Justin’s girlfriend, Rhiannon. From that moment, the rules by which A has been living no longer apply. Because finally A has found someone A wants to be with—day in, day out, day after day.', 296, null, 2012, 70139, (select id from series where hardcover_id = 6082), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cursor''s Fury', 'Jim Butcher', '0441015476', 'https://assets.hardcover.app/external_data/60982699/976bb79acf49115bc3497c0a9ed765ff3f286c08.jpeg', 'When the power-hungry High Lord of Kalare launches a merciless rebellion against the First Lord, young Tavi of Calderon joins a newly formed legion under an assumed name. And when the ruthless Kalare allies himself with a savage enemy of the realm, Tavi finds himself leading an inexperienced, poorly equipped legion—the only force standing between Alera and certain doom...', 614, null, 2006, 437923, (select id from series where hardcover_id = 975), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Angel Experiment', 'James Patterson', '1408432226', 'https://assets.hardcover.app/edition/12853262/fde483193287376050fc8570bc7cc0cddedc84b7.jpeg', 'Fourteen-year-old Maximum Ride, better known as Max, knows what it’s like to soar above the world. She and all the members of the “flock”—Fang, Iggy, Nudge, Gasman, and Angel—are just like ordinary kids—only they have wings and can fly. It may seem like a dream come true to some, but their lives can morph into a living nightmare at any time... like when Angel, the youngest member of the flock, is kidnapped and taken back to the “School” where she and the others were experimented on by a crew of wack jobs.

Her friends brave a journey to blazing hot Death Valley, CA, to save Angel, but soon enough, they find themselves in yet another nightmare—this one involving fighting off the half-human, half-wolf “Erasers” in New York City. Whether in the treetops of Central Park or in the bowels of the Manhattan subway system, Max and her adopted family take the ride of their lives. Along the way Max discovers from her old friend and father-figure Jeb—now her betrayed and greatest enemy—that her purpose is save the world—but can she?', 321, null, 2005, 68716, (select id from series where hardcover_id = 6078), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Compound', 'Aisling Rawle', '0008710090', 'https://assets.hardcover.app/external_data/61791844/801d67988d053635c647677fae6b7f6991a10a74.jpeg', 'Lily—a bored, beautiful twenty-something—wakes up on a remote desert compound, alongside nineteen other contestants competing on a massively popular reality show. To win, she must outlast her housemates to stay in the Compound the longest, while competing in challenges for luxury rewards like champagne and lipstick, plus communal necessities to outfit their new home, like food, appliances, and a front door.

Cameras are catching all her angles, good and bad, but Lily has no desire to leave: why would she, when the world outside is falling apart? As the competition intensifies, intimacy between the players deepens, and it becomes increasingly difficult to distinguish between desire and desperation. When the unseen producers raise the stakes, forcing contestants into upsetting, even dangerous situations, the line between playing the game and surviving it begins to blur. If Lily makes it to the end, she’ll receive prizes beyond her wildest dreams—but what will she have to do to win?

Addictive and prescient, The Compound is an explosive debut from a major new voice in fiction and will linger in your mind long after the game ends.', 304, 605, 2025, 1633611, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bury Your Gays', 'Chuck Tingle', '1250351278', 'https://assets.hardcover.app/editions/31467004/2586016368117763.jpg', 'Misha knows that chasing success in Hollywood can be hell.

But finally, after years of trying to make it, his big moment is here: an Oscar nomination. And the executives at the studio for his long-running streaming series know just the thing to kick his career to the next level: kill off the gay characters, "for the algorithm," in the upcoming season finale.

Misha refuses, but he soon realizes that he’s just put a target on his back. And what’s worse, monsters from his horror movie days are stalking him and his friends through the hills above Los Angeles.

Haunted by his past, Misha must risk his entire future—before the horrors from the silver screen find a way to bury him for good.', 304, 631, 2024, 1070590, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dragon''s Path', 'Daniel Abraham', '5389249631', 'https://assets.hardcover.app/edition/30409723/d110a93e015f5f52aa29451fb0898b1d3f458035.jpeg', 'The dragons are gone, the powerful magics that broke the world diluted to little more than parlour tricks, but the kingdoms of men remain and the great game of thrones goes on. Lords deploy armies and merchant caravans as their weapons, manoeuvring for wealth and influence. But a darker power is rising - an unlikely leader with an ancient ally threatens to unleash again the madness that destroyed the world once already. Only one man knows the truth and, from the shadows, must champion humanity. The world''s fate stands on the edge of a Dagger, its future on the toss of a Coin . . .', 576, null, 2011, 441048, (select id from series where hardcover_id = 2537), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sorrowland', 'Rivers Solomon', '1529119138', 'https://assets.hardcover.app/editions/3270589/6354108922870589.jpg', '"A wonderland of fantastical and frightening, magical and real." Marlon James "A fantastical, fierce reckoning... Sorrowland is gorgeous." Roxanne Gay "Dark, magical and incredibly satisfying." Independent "An exhilarating journey to the outer limits of science fiction." Guardian. --- Vern, a hunted woman alone in the woods, gives birth to twins and raises them away from the influence of the outside world. But something is wrong - not with them, but with her own body. It''s changing, it''s itching, it''s stronger, it''s... not normal. To understand her body''s metamorphosis, Vern must investigate not just the secluded religious compound she fled but the violent history of dehumanization, medical experimentation, and genocide that produced it. In the course of reclaiming her own darkness, Vern learns that monsters aren''t just individuals, but entire histories, systems, and nations. Sorrowland is a memorable work of Gothic fiction that wrestles with the tangled history of racism in America and the marginalisation of society''s undesirables. It is a searing, seminal book that marks the arrival of a bold, unignorable voice in American fiction.', 368, 722, 2021, 435914, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hench', 'Natalie Zina Walschots', '0062978578', 'https://assets.hardcover.app/external_data/4018523/953fc4e975b4380ad84277fbd4597cf97c67752c.jpeg', 'The Boys meets My Year of Rest and Relaxation in this smart, imaginative, and evocative novel of love, betrayal, revenge, and redemption, told with razor-sharp wit and affection, in which a young woman discovers the greatest superpower—for good or ill—is a properly executed spreadsheet.

Includes a bonus story for the paperback.

Anna does boring things for terrible people because even criminals need office help and she needs a job. Working for a monster lurking beneath the surface of the world isn’t glamorous. But is it really worse than working for an oil conglomerate or an insurance company? In this economy?

As a temp, she’s just a cog in the machine. But when she finally gets a promising assignment, everything goes very wrong, and an encounter with the so-called “hero” leaves her badly injured. And, to her horror, compared to the other bodies strewn about, she’s the lucky one.

So, of course, then she gets laid off.

With no money and no mobility, with only her anger and internet research acumen, she discovers her suffering at the hands of a hero is far from unique. When people start listening to the story that her data tells, she realizes she might not be as powerless as she thinks.

Because the key to everything is data: knowing how to collate it, how to manipulate it, and how to weaponize it. By tallying up the human cost these caped forces of nature wreak upon the world, she discovers that the line between good and evil is mostly marketing. And with social media and viral videos, she can control that appearance.

It’s not too long before she’s employed once more, this time by one of the worst villains on earth. As she becomes an increasingly valuable lieutenant, she might just save the world.

A sharp, witty, modern debut, Hench explores the individual cost of justice through a fascinating mix of Millennial office politics, heroism measured through data science, body horror, and a profound misunderstanding of quantum mechanics. ', 403, 855, 2020, 433504, (select id from series where hardcover_id = 58119), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Moon of the Crusted Snow', 'Waubgeshig Rice', '1770414002', 'https://assets.hardcover.app/edition/5510705/11f13a835e19aac05554867b264b9a0a699d6bf4.jpeg', 'A daring post-apocalyptic novel from a powerful rising literary voice

With winter looming, a small northern Anishinaabe community goes dark. Cut off, people become passive and confused. Panic builds as the food supply dwindles. While the band council and a pocket of community members struggle to maintain order, an unexpected visitor arrives, escaping the crumbling society to the south. Soon after, others follow.

The community leadership loses its grip on power as the visitors manipulate the tired and hungry to take control of the reserve. Tensions rise and, as the months pass, so does the death toll due to sickness and despair. Frustrated by the building chaos, a group of young friends and their families turn to the land and Anishinaabe tradition in hopes of helping their community thrive again. Guided through the chaos by an unlikely leader named Evan Whitesky, they endeavor to restore order while grappling with a grave decision.

Blending action and allegory, Moon of the Crusted Snow upends our expectations. Out of catastrophe comes resilience. And as one society collapses, another is reborn.', 226, 406, 2018, 442917, (select id from series where hardcover_id = 7394), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('And Another Thing...', 'Eoin Colfer', '1401310303', 'https://assets.hardcover.app/edition/25135984/33658302-88ff-4c8d-8579-3e7f8837b539.jpg', 'And Another Thing... is the sixth novel in the increasingly inaccurately named Hitchhiker''s Guide to the Galaxy trilogy. Eight years after the death of its creator, Douglas Adams, widow Jane Belson sanctioned the project to be written by the international number-one bestselling children''s writer Eoin Colfer, author of the Artemis Fowl novels. Belson said of Eoin Colfer, "I love his books and could not think of a better person to transport Arthur, Zaphod, and Marvin to pastures new." Colfer, a fan of Hitchhiker since his school days, said, "Being given the chance to write this book is like suddenly being offered the superpower of your choice. For years I have been finishing this incredible story in my head and now I have the opportunity to do it in the real world." Prepare to be amazed...', 290, null, 2009, 168993, (select id from series where hardcover_id = 3400), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Livesuit', 'James S. A. Corey', '0316575348', 'https://assets.hardcover.app/external_data/61555450/bc67451b4e0b98e2f93927d22d7a9235dd237f8a.jpeg', 'The first novella set in the universe of James S. A. Corey''s epic Captive''s War series. Humanity''s war is eternal, spread across the galaxy and the ages. Humanity''s best hope to end the endless slaughter is the Livesuit forces. Soldiers meld their bodies to the bleeding edge technology, becoming something more than human for the duration of a war that might never end. For more from James S. A. Corey, check out: The Captive''s War: The Mercy of Gods The Expanse: Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath Leviathan Falls Memory''s Legion The Expanse Short Fiction: Drive The Butcher of Anderson Station Gods of Risk The Churn The Vital Abyss Strange Dogs Auberon The Sins of Our Fathers', 75, 163, 2024, 1423630, (select id from series where hardcover_id = 52808), 1.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Princeps'' Fury', 'Jim Butcher', '1440656797', 'https://assets.hardcover.app/edition/6770015/3acbd69424b7f4229bc319b97150571d88a63971.jpeg', 'From the New York Times bestselling author of Captain''s Fury and the Dresden Files novels.Tavi of Calderon, now recognized as Princeps Gaius Octavian and heir to the crown, has achieved a fragile alliance with Alera''s oldest foes, the savage Canim. But when Tavi and his legions guide the Canim safely to their lands, his worst fears are realized.The dreaded Vord—the enemy of Aleran and Cane alike—have spent the last three years laying waste to the Canim homeland. And when the Alerans are cut off from their ships, they find themselves with no choice but to fight shoulder to shoulder if they are to survive.For a thousand years, Alera and her furies have withstood every enemy, and survived every foe.The thousand years are over…', 404, 1061, 2007, 40860, (select id from series where hardcover_id = 975), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Just One Damned Thing After Another', 'Jodi Taylor', '1597808687', 'https://assets.hardcover.app/external_data/4229238/504320aa2c688ad1f78b5a06d4ccd6297f542ef6.jpeg', '"History is just one damned thing after another."

Behind the seemingly innocuous façade of St Mary''s, a different kind of historical research is taking place. They don''t do ''time-travel'' - they ''investigate major historical events in contemporary time''. Maintaining the appearance of harmless eccentrics is not always within their power - especially given their propensity for causing loud explosions when things get too quiet.

Meet the disaster-magnets of St Mary''s Institute of Historical Research as they ricochet around History. Their aim is to observe and document - to try and find the answers to many of History''s unanswered questions...and not to die in the process. But one wrong move and History will fight back - to the death. And, as they soon discover - it''s not just History they''re fighting.

Follow the catastrophe curve from 11th-century London to World War I, and from the Cretaceous Period to the destruction of the Great Library at Alexandria. For wherever Historians go, chaos is sure to follow in their wake....', 394, 431, 2013, 428569, (select id from series where hardcover_id = 1823), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Autonomous', 'Annalee Newitz', '0356511227', 'https://assets.hardcover.app/external_data/964999/229c375d3dfd50782add9bcf87f27c4e234386e7.jpeg', 'When anything can be owned, how can we be free

Earth, 2144. Jack is an anti-patent scientist turned drug pirate, traversing the world in a submarine as a pharmaceutical Robin Hood, fabricating cheap scrips for poor people who can’t otherwise afford them. But her latest drug hack has left a trail of lethal overdoses as people become addicted to their work, doing repetitive tasks until they become unsafe or insane.

Hot on her trail, an unlikely pair: Eliasz, a brooding military agent, and his robotic partner, Paladin. As they race to stop information about the sinister origins of Jack’s drug from getting out, they begin to form an uncommonly close bond that neither of them fully understand.

And underlying it all is one fundamental question: Is freedom possible in a culture where everything, even people, can be owned?', 319, 627, 2017, 431267, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Living Dead in Dallas', 'Charlaine Harris', '8711411120', 'https://assets.hardcover.app/edition/22590091/3a99f8f10951da8dc6f6d69bee3bba1c25c9d83c.jpeg', 'Even though Sookie has her own vampire to look out for her—her red-hot, cold-blooded boyfriend, Bill Compton—she has to admit that the bloodsuckers did save her life. So when one of the local Undead asks the cocktail waitress for a favor, she feels like she owes them.

Soon, Sookie’s in Dallas using her telepathic skills to search for a missing vampire. She’s supposed to interview certain humans involved. There’s just one condition: The vampires must promise to behave—and let the humans go unharmed. Easier said than done. All it takes is one delicious blonde and one small mistake for things to turn deadly...', 288, null, 2002, 437931, (select id from series where hardcover_id = 5512), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dreaming Void', 'Peter F. Hamilton', '0345496531', 'https://assets.hardcover.app/edition/29849093/28390f7f6d517d2f914007d3c0404ad558b94224.jpeg', 'The year is 3589, fifteen hundred years after Commonwealth forces barely staved off human extinction in a war against the alien Prime. Now an even greater danger has surfaced: a threat to the existence of the universe itself.
At the very heart of the galaxy is the Void, a self-contained microuniverse that cannot be breached, cannot be destroyed, and cannot be stopped as it steadily expands in all directions, consuming everything in its path: planets, stars, civilizations. The Void has existed for untold millions of years. Even the oldest and most technologically advanced of the galaxy’s sentient races, the Raiel, do not know its origin, its makers, or its purpose.

But then Inigo, an astrophysicist studying the Void, begins dreaming of human beings who live within it. Inigo’s dreams reveal a world in which thoughts become actions and dreams become reality. Inside the Void, Inigo sees paradise. Thanks to the gaiafield, a neural entanglement wired into most humans, Inigo’s dreams are shared by hundreds of millions–and a religion, the Living Dream, is born, with Inigo as its prophet. But then he vanishes.

Suddenly there is a new wave of dreams. Dreams broadcast by an unknown Second Dreamer serve as the inspiration for a massive Pilgrimage into the Void. But there is a chance that by attempting to enter the Void, the pilgrims will trigger a catastrophic expansion, an accelerated devourment phase that will swallow up thousands of worlds.

And thus begins a desperate race to find Inigo and the mysterious Second Dreamer. Some seek to prevent the Pilgrimage; others to speed its progress–while within the Void, a supreme entity has turned its gaze, for the first time, outward. . . .', 607, 1312, 2007, 378960, (select id from series where hardcover_id = 3433), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sins of Our Fathers', 'James S. A. Corey', '0316669075', 'https://assets.hardcover.app/external_data/61060171/bca8750d3ab80754377c6eff31ff82f0b60c0110.jpeg', 'Through one of the gates, a colony stands alone. Their supplies are low. Their defenses, weak. The leadership is uncertain, and the community fragile. Huge alien beasts threaten the little they have left.

But the worst monsters are human, and the greatest dangers are the past they brought.', 64, null, 2022, 499024, (select id from series where hardcover_id = 1026), 9.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Captain''s Fury', 'Jim Butcher', '1429587415', 'https://assets.hardcover.app/edition/1948989/9cf87166247fe9b43b1a5f291391262798383fc4.jpeg', 'In his acclaimed Codex Alera novels, #1 New York Times bestselling author Jim Butcher has created a fascinating world of elemental magic. Now, as enemies become allies, and friends become bitter foes, a danger beyond reckoning looms for all... After two years of bitter conflict with the hordes of invading Canim warriors, Tavi of Calderon, now Captain of the First Aleran Legion, realizes that a peril far greater than the Canim exists—the mysterious threat that drove the savage Canim to flee their homeland. Tavi proposes attempting an alliance with the Canim against their common foe, but his warnings go unheeded. For the Senate’s newly-appointed military commander has long desired to wipe out the Canim “scourge,” and their slave allies. Now, Tavi must find a way to overcome centuries-old animosities if an alliance is to be forged, and he must lead his legion in defiance of the law, against friend and foe—or none will have a chance of survival...', 658, 1174, 2007, 258514, (select id from series where hardcover_id = 975), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fuzzy Nation', 'John Scalzi, Wil Wheaton', '1250174643', 'https://assets.hardcover.app/external_data/41630191/0e5f1c0f51ff6ffd52b7d86b3e8dacbb08b47cc3.jpeg', 'Discovering a gem node on a distant planet, contractor Jack Holloway believes he has become a wealthy man before encountering an indigenous race of small, furry, sentient beings who his corporate partners are determined to eliminate in order to secure their stake in the treasure.', null, 439, 1996, 355188, (select id from series where hardcover_id = 5798), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Spindle Splintered', 'Alix E. Harrow', '2253909157', 'https://assets.hardcover.app/external_data/61253336/73dd7ca8e2e85dca5c505e2124ef2a523c8dfbc2.jpeg', 'It''s Zinnia Gray''s twenty-first birthday, which is extra-special because it''s the last birthday she''ll ever have. When she was young, an industrial accident left Zinnia with a rare condition. Not much is known about her illness, just that no-one has lived past twenty-one.

Her best friend Charm is intent on making Zinnia''s last birthday special with a full sleeping beauty experience, complete with a tower and a spinning wheel. But when Zinnia pricks her finger, something strange and unexpected happens, and she finds herself falling through worlds, with another sleeping beauty, just as desperate to escape her fate.', 128, 199, 2021, 428543, (select id from series where hardcover_id = 1191), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Zombie Survival Guide: Complete Protection from the Living Dead', 'Max Brooks', '8806238671', 'https://assets.hardcover.app/external_data/61661302/26e10c99eadbca2106913ddae6c060dddb8420c6.jpeg', '"Those who don''t learn from history are condemned to repeat it. From the Stone Age to the information age, the undead have threatened to engulf the human race. They''re coming. They''re hungry. Don''t wait for them to come to you! This is the graphic novel the fans demanded: major zombie attacks from the dawn of humanity. On the African savannas, against the legions of ancient Rome, on the high seas with Francis Drake-- every civilization has faced them. Here are the grisly and heroic stories--complete with eye-popping artwork that pulsates with the hideous faces of the undead. Organize before they rise! Scripted by the world''s leading zombie authority, Max Brooks, Recorded Attacks reveals how other eras and cultures have dealt with--and survived--the ancient viral plague. By immersing ourselves in past horror we may yet prevail over the coming outbreak in our time."', 254, null, 2003, 261070, (select id from series where hardcover_id = 6290), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Cloud Roads', 'Martha Wells', '1597803030', 'https://assets.hardcover.app/edition/22658252/a22e2e449f81d1f0e96d2d16e063f774113c8c92.jpeg', 'Now available in mass market paperback, The Cloud Roads is the first in the Hugo Award-nominated Books of the Raksura series, from New York Times bestselling author Martha Wells (The Murderbot Diaries). Moon has spent his life hiding what he is: a shape-shifter able to transform himself into a winged creature of flight. An orphan with only vague memories of his own kind, Moon tries to fit in among the tribes of his river valley, with mixed success. Just as he is once again cast out by his adopted tribe, he discovers a shape-shifter like himself—someone who seems to know exactly what he is, who promises that Moon will be welcomed into the shape-shifter community. What this stranger doesn''t tell Moon is that his presence will tip the balance of power, that his extraordinary lineage is crucial to the colony''s survival, and that his people face extinction at the hands of the dreaded Fell! Now Moon must overcome a lifetime of conditioning in order to save himself . . . and his newfound kin.', 278, null, 2011, 433355, (select id from series where hardcover_id = 2887), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Trade of Blood', 'Robert Jackson Bennett', '1399725505', 'https://assets.hardcover.app/edition/31280227/8eb5d925-dcec-49f8-bdc1-600d8e59068e.jpg', 'The heir to one of the Empire’s most powerful families sits in jail, accused of murder. His hands are covered in the victim’s blood, and he can neither deny his guilt nor explain his actions.

But if the great detective Ana Dolabra cannot save him from the noose, the farming canton of Sapirdad will explode into war, threatening to plunge the whole Empire into starvation and chaos.

As Ana investigates—her assistant Dinios Kol, as ever, acting as her eyes and ears—she fears her task is even more daunting than it seemed. For this murder is just the latest in a deeper, subtler web of death, woven by a mastermind with an ancient weapon at his disposal.

With their customary skill, Ana and Din pursue their adversary through the canton’s wild ranges, sprawling ranches, and reeking slaughterhouses. Yet even they are not prepared to learn the horrifying secret behind their opponent’s powers.', 400, 847, 2026, 1255177, (select id from series where hardcover_id = 46710), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Slade House', 'David Mitchell', '3498042769', 'https://assets.hardcover.app/external_data/26368479/54c722cf51303cb678c58829a304c66bccdeb310.jpeg', 'The New York Times bestseller by the author of The Bone Clocks and Cloud Atlas | Named One of the Best Books of the Year by San Francisco Chronicle, NPR, Los Angeles Times, The Guardian, The Telegraph, National Post, BookPage, and Kirkus Reviews Keep your eyes peeled for a small black iron door. Down the road from a working-class British pub, along the brick wall of a narrow alley, if the conditions are exactly right, you’ll find the entrance to Slade House. A stranger will greet you by name and invite you inside. At first, you won’t want to leave. Later, you’ll find that you can’t. Every nine years, the house’s residents—an odd brother and sister—extend a unique invitation to someone who’s different or lonely: a precocious teenager, a recently divorced policeman, a shy college student. But what really goes on inside Slade House? For those who find out, it’s already too late. . . . Spanning five decades, from the last days of the 1970s to the present, leaping genres, and barreling toward an astonishing conclusion, this intricately woven novel will pull you into a reality-warping new vision of the haunted house story—as only David Mitchell could imagine it. Praise for Slade House “A fiendish delight . . . Mitchell is something of a magician.”—The Washington Post “Entertainingly eerie . . . We turn to [Mitchell] for brain-tickling puzzle palaces, for character studies and for language.”—Chicago Tribune “A ripping yarn . . . Like Shirley Jackson’s Hill House or the Overlook Hotel from Stephen King’s The Shining, [Slade House] is a thin sliver of hell designed to entrap the unwary. . . . As the Mitchellverse grows ever more expansive and connected, this short but powerful novel hints at still more marvels to come.”—San Francisco Chronicle “Like Stephen King in a fever . . . manically ingenious.”—The Guardian (U.K.) “A haunted house story that savors of Dickens, Stephen King, J. K. Rowling and H. P. Lovecraft, but possesses more psychic voltage than any of them.”—Pittsburgh Post-Gazette “Tightly crafted and suspenseful yet warmly human . . . the ultimate spooky nursery tale for adults.”—The Huffington Post', 272, 414, 2015, 429216, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Light of the Jedi', 'Charles Soule', '9504973159', 'https://assets.hardcover.app/external_data/61341797/8f579c08afdc5edaad07d09d74700d4b7e8c2287.jpeg', 'Long before the First Order, before the Empire, before even The Phantom Menace . . . Jedi lit the way for the galaxy in The High Republic

It is a golden age. Intrepid hyperspace scouts expand the reach of the Republic to the furthest stars, worlds flourish under the benevolent leadership of the Senate, and peace reigns, enforced by the wisdom and strength of the renowned order of Force users known as the Jedi. With the Jedi at the height of their power, the free citizens of the galaxy are confident in their ability to weather any storm But the even brightest light can cast a shadow, and some storms defy any preparation.

When a shocking catastrophe in hyperspace tears a ship to pieces, the flurry of shrapnel emerging from the disaster threatens an entire system. No sooner does the call for help go out than the Jedi race to the scene. The scope of the emergence, however, is enough to push even Jedi to their limit. As the sky breaks open and destruction rains down upon the peaceful alliance they helped to build, the Jedi must trust in the Force to see them through a day in which a single mistake could cost billions of lives.

Even as the Jedi battle valiantly against calamity, something truly deadly grows beyond the boundary of the Republic. The hyperspace disaster is far more sinister than the Jedi could ever suspect. A threat hides in the darkness, far from the light of the age, and harbors a secret that could strike fear into even a Jedi''s heart.', 368, null, 2020, 445730, (select id from series where hardcover_id = 7234), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('First Lord''s Fury', 'Jim Butcher', '110115022X', 'https://assets.hardcover.app/edition/30407552/668a9b8d5b6be864ed782235619e30d286f92e90.jpeg', 'The aging First Lord of Alera has fallen in battle. Yet his people must continue to resist an invading inhuman army. Desperate Alerans even pledge fealty to the Vord Queen to survive, turning the incredible power of Aleran furies back on their own people. And despite all efforts, the Alerans are being ground into dust and pushed to the farthest reaches of their own realm. However, Tavi has returned with vital insights from the Canim Blood Lands. He knows how to counter the Vord and, more importantly, believes human ingenuity can equal fury-born powers. Now events are rushing towards a last stand, where Tavi and the last Aleran legions must formulate a dangerous new strategy, together. For a civilisation is on the brink of extinction.', 704, 1437, 2009, 10095, (select id from series where hardcover_id = 975), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Contract of Isako', 'Fonda Lee', '0356526720', 'https://assets.hardcover.app/edition/32441073/205eddc0-a726-44e2-a883-0fd1e3072075.jpg', 'Isako is a legendary swordswoman, but every legend must come to an end. When her long-time client unexpectedly retires, she plans to follow—to walk out into the frozen wasteland of their planet with her head held high and her family enriched by her death. But when she''s offered a final mission, she can''t refuse, especially when she realizes who lies at the center of it all: Martim, her last—and worst—apprentice, who''s somehow made his way to the top. As she''s thrust into a world of corporate espionage and shadowy secrets, what she uncovers could forever change humanity''s existence among the stars.  

The Last Contract of Isako is epic science fiction like only Fonda Lee can write it—set in a world where money trumps loyalty, the elite have the power to extend life or end it, and one woman in the twilight of her calling must decide what''s ultimately worth living—or dying—for.', 528, 1034, 2025, 874677, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Summer Frost', 'Blake Crouch', '1978650833', 'https://assets.hardcover.app/editions/31712397/8987401731135107.jpg', 'Maxine was made to do one thing: die. Except the minor non-player character in the world Riley is building makes her own impossible decision—veering wildly off course and exploring the boundaries of the map. When the curious Riley extracts her code for closer examination, an emotional relationship develops between them. Soon Riley has all new plans for her spontaneous AI, including bringing Max into the real world. But what if Max has real-world plans of her own?

Blake Crouch’s Summer Frost is part of Forward, a collection of six stories of the near and far future from out-of-this-world authors. Each piece can be read or listened to in a single thought-provoking sitting.', 85, 139, 2019, 427934, (select id from series where hardcover_id = 5493), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Champion', 'Marie Lu', '8467574070', 'https://assets.hardcover.app/edition/30615130/a6cbe161aff8135adabc05db2c128671a5edb6cd.jpeg', 'June and Day have sacrificed so much for the people of the Republic—and each other—and now their country is on the brink of a new existence. June is back in the good graces of the Republic, working within the government’s elite circles as Princeps-Elect, while Day has been assigned a high-level military position.

But neither could have predicted the circumstances that will reunite them: just when a peace treaty is imminent, a plague outbreak causes panic in the Colonies, and war threatens the Republic’s border cities. This new strain of plague is deadlier than ever, and June is the only one who knows the key to her country’s defense. But saving the lives of thousands will mean asking the one she loves to give up everything.

With heart-pounding action and suspense, Marie Lu’s bestselling trilogy draws to a stunning conclusion.', 353, null, 2013, 70390, (select id from series where hardcover_id = 5717), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Darkfever', 'Karen Marie Moning', '0440240980', 'https://assets.hardcover.app/edition/23713604/8f9dbc06494e32d9d43761552c027e297156ff30.jpeg', 'MacKayla Lane’s life is good. She has great friends, a decent job, and a car that breaks down only every other week or so. In other words, she’s your perfectly ordinary twenty-first-century woman. Or so she thinks…until something extraordinary happens.

When her sister is murdered, leaving a single clue to her death–a cryptic message on Mac’s cell phone–Mac journeys to Ireland in search of answers. The quest to find her sister’s killer draws her into a shadowy realm where nothing is as it seems, where good and evil wear the same treacherously seductive mask. She is soon faced with an even greater challenge: staying alive long enough to learn how to handle a power she had no idea she possessed–a gift that allows her to see beyond the world of man, into the dangerous realm of the Fae….

As Mac delves deeper into the mystery of her sister’s death, her every move is shadowed by the dark, mysterious Jericho, a man with no past and only mockery for a future. As she begins to close in on the truth, the ruthless Vlane–an alpha Fae who makes sex an addiction for human women–closes in on her. And as the boundary between worlds begins to crumble, Mac’s true mission becomes clear: find the elusive Sinsar Dubh before someone else claims the all-powerful Dark Book–because whoever gets to it first holds nothing less than complete control of the very fabric of both worlds in their hands….', 262, null, 2006, 322433, (select id from series where hardcover_id = 1578), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sourdough', 'Robin Sloan, Thérèse Plummer', '1925603156', 'https://assets.hardcover.app/external_data/60239865/7f9d1add3670df915ff7b73dc894e77ac376c216.jpeg', 'Named a best book of the year by NPR, the San Francisco Chronicle, and Southern Living Includes the new short story "The Suitcase Clone" From Robin Sloan, the New York Times bestselling author of Mr. Penumbra''s 24-Hour Bookstore, comes Sourdough, "a perfect parable for our times" (San Francisco Magazine): a delicious and funny novel about an overworked and undersocialized software engineer discovering a calling and a community as a baker. Lois Clary is a software engineer who codes all day and collapses at night, her human contact limited to the two brothers who run the neighborhood hole-in-the-wall from which she orders dinner every evening. Then, disaster! Visa issues. The brothers quickly close up shop, but they have one last delivery for Lois: their culture, the sourdough starter used to bake their bread. Lois must keep it alive, they tell her--feed it daily, play it music, and learn to bake with it. Soon, not only is she eating her own homemade bread, she''s providing loaves daily to her employer''s cafeteria. When the company chef urges her to take her product to the farmer''s market, a whole new world opens up.', null, null, 2017, 102315, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ruin of Kings', 'Jenn Lyons', '3608191755', 'https://assets.hardcover.app/external_data/49418329/8971621b758d90ad171a4a7cc5d2c2130184f9d5.jpeg', '"Everything epic fantasy should be: rich, cruel, gorgeous, brilliant, enthralling and deeply, deeply satisfying. I loved it."—Lev Grossman, author of The Magicians When destiny calls, there''s no fighting back. Kihrin grew up in the slums of Quur, a thief and a minstrel''s son raised on tales of long-lost princes and magnificent quests. When he is claimed against his will as the missing son of a treasonous prince, Kihrin finds himself at the mercy of his new family''s ruthless power plays and political ambitions. Practically a prisoner, Kihrin discovers that being a long-lost prince is nothing like what the storybooks promised. The storybooks have lied about a lot of other things, too: dragons, demons, gods, prophecies, and how the hero always wins. Then again, maybe he isn''t the hero after all. For Kihrin is not destined to save the world. He''s destined to destroy it. Jenn Lyons begins the Chorus of Dragons series with The Ruin of Kings, an epic fantasy novel about a man who discovers his fate is tied to the future of an empire.', 560, null, 2019, 428656, (select id from series where hardcover_id = 1704), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Semiosis', 'Sue Burke', '0008300798', 'https://assets.hardcover.app/external_data/41550864/791601b8dda2d1d91b7d7b23ca362b01d811122d.jpeg', '"Colonists from Earth wanted the perfect home, but they''ll have to survive on the one they found. They don''t realize another life form watches...and waits...Only mutual communication can forge an alliance with the planet''s sentient species and prove that humans are more than tools."--', 336, 886, 2018, 440082, (select id from series where hardcover_id = 66511), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Dead Djinn in Cairo', 'P. Djèlí Clark, Suehyla El-Attar', '0765389444', 'https://assets.hardcover.app/external_data/1222324/7d8e8a1892af74df3aaf15c747ed5181a70ebf20.jpeg', 'Alex Award-winning author P. Djèlí Clark, A Dead Djinn in Cairo is a Tor.com original historcal fantasy set in an alternate early twentieth century infused with the otherworldly. Egypt, 1912. In Cairo, the Ministry of Alchemy, Enchantments and Supernatural Entities investigate disturbances between the mortal and the (possibly) divine. What starts off as an odd suicide case for Special Investigator Fatma el-Sha’arawi leads her through the city’s underbelly as she encounters rampaging ghouls, saucy assassins, clockwork angels, and a plot that could unravel time itself. At the Publisher''s request, this title is being sold without Digital Rights Management Software (DRM) applied.', 50, 101, 2016, 439076, (select id from series where hardcover_id = 2347), 0.1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wall', 'Marlen Haushofer, Shaun Whiteside', '1573440949', 'https://assets.hardcover.app/edition/30698873/51d5070e9572398ddb18485a434bcfa7d035165a.jpeg', 'First published to acclaim in Germany, The Wall chronicles the life of the last surviving human on earth, an ordinary middle-aged woman who awakens one morning to find that everyone else has vanished. Assuming her isolation to be the result of a military experiment gone awry, she begins the terrifying work of survival and self-renewal. This novel is at once a simple and moving tale and a disturbing meditation on humanity.', 248, 520, 1963, 479004, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Keeper of Enchanted Rooms', 'Charlie N. Holmberg', '1713663627', 'https://assets.hardcover.app/edition/30514956/2426f647116ccd645c3e7d345b61d46cb249a97c.jpeg', 'Rhode Island, 1846. Estranged from his family, writer Merritt Fernsby is surprised when he inherits a remote estate in the Narragansett Bay. Though the property has been uninhabited for more than a century, Merritt is ready to call it home—until he realizes he has no choice. With its doors slamming shut and locking behind him, Whimbrel House is not about to let Merritt leave. Ever.

Hulda Larkin of the Boston Institute for the Keeping of Enchanted Rooms has been trained in taming such structures in order to preserve their historical and magical significance. She understands the dangers of bespelled homes given to tantrums. She advises that it’s in Merritt’s best interest to make Whimbrel House their ally. To do that, she’ll need to move in, too.

Prepared as she is with augury, a set of magic tools, and a new staff trained in the uncanny, Hulda’s work still proves unexpectedly difficult. She and Merritt grow closer as the investigation progresses, but the house’s secrets run deeper than they anticipated. And the sentient walls aren’t their only concern—something outside is coming for the enchantments of Whimbrel House, and it could be more dangerous than what rattles within.', 348, 635, 2022, 555789, (select id from series where hardcover_id = 25473), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Silverblood Promise', 'James Logan', '1529432812', 'https://assets.hardcover.app/editions/31404414/8671187064902544.jpg', 'Set in a city of traders and thieves, monsters and murderers, this fast-paced epic fantasy debut is a must-read for fans of Joe Abercrombie, Nicholas Eames, and Scott Lynch. Lukan Gardova is a cardsharp, academy dropout, and—thanks to a duel that ended badly—the disgraced heir to an ancient noble house. His days consist of cheap wine, rigged card games, and wondering how he might win back the life he threw away. When Lukan discovers that his estranged father has been murdered in strange circumstances, he finds fresh purpose. Deprived of his chance to make amends for his mistakes, he vows to unravel the mystery behind his father''s death. His search for answers leads him to Saphrona, fabled city of merchant princes, where anything can be bought if one has the coin. Lukan only seeks the truth, but instead he finds danger and secrets in every shadow. For in Saphrona, everything has a price—and the price of truth is the deadliest of all.', 522, 1022, 2024, 1001453, (select id from series where hardcover_id = 63947), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Obsidian', 'Jennifer L. Armentrout', '1452681651', 'https://assets.hardcover.app/editions/30461813/dcfbf336-2fa7-4f5b-bb1b-877bc003070b-obsidian-entangled-teen.jpg', 'Starting over sucks.

When we moved to West Virginia right before my senior year, I''d pretty much resigned myself to thick accents, dodgy internet access, and a whole lot of boring...until I spotted my hot neighbor, with his looming height and eerie green eyes. Things were looking up.

And then he opened his mouth.

Daemon is infuriating. Arrogant. Stab-worthy. We do not get along. At all. But when a stranger attacks me and Daemon literally freezes time with a wave of his hand, well, something...unexpected happens.

The hot alien living next door marks me.

You heard me. Alien. Turns out Daemon and his sister have a galaxy of enemies wanting to steal their abilities, and Daemon''s touch has me lit up like the Vegas Strip. The only way I''m getting out of this alive is by sticking close to Daemon until my alien mojo fades.

If I don''t kill him first, that is.', 400, null, 2011, 429391, (select id from series where hardcover_id = 6404), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Princess of Mars', 'Edgar Rice Burroughs', '1421980010', 'https://assets.hardcover.app/edition/6021101/1bbe9d0284d82c61ad04ec952f71191abbea037f.jpeg', 'I am a very old man; how old I do not know. Possibly I am a hundred, possibly more; but I cannot tell because I have never aged as other men, nor do I remember any childhood. So far as I can recollect I have always been a man, a man of about thirty. I appear today as I did forty years and more ago, and yet I feel that I cannot go on living forever; that some day I shall die the real death from which there is no resurrection.
[Adventures of John Carter in Mars -- from the author of the Tarzan series.]', 228, null, 1912, 356502, (select id from series where hardcover_id = 5800), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Five Broken Blades', 'Mai Corland', '2073063535', 'https://assets.hardcover.app/editions/31199575/1c142c51-179c-4042-94fc-fba7afe5b3e0.jpg', 'The five most dangerous liars in the land have been mysteriously summoned to work together for a single objective: to kill the God King Joon.

He has it coming. Under his merciless immortal hand, the nobles flourish, while the poor and innocent are imprisoned, ruined…or sold.

And now each of the five blades will come for him. Each has tasted bitterness―from the hired hitman seeking atonement, a lovely assassin who seeks freedom, or even the prince banished for his cruel crimes. None can resist the sweet, icy lure of vengeance.

They can agree on murder.

They can agree on treachery.

But for these five killers―each versed in deception, lies, and betrayal―it’s not enough to forge an alliance. To survive, they’ll have to find a way to trust each other…but only one can take the crown.

Let the best liar win.', 443, 923, 2024, 1175092, (select id from series where hardcover_id = 87818), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kraken', 'China Miéville', '1596063378', 'https://assets.hardcover.app/edition/5150876/f7621bb4-e826-4f3e-a1d7-a908a56674d7.jpg', 'Kraken is a fantasy novel by British author China Miéville. It is published in the UK by Macmillan, and in the US by Del Rey Books. The book bears the subtitle "An Anatomy" on the title page. It was the winner for the 2011 Locus Award for Best Fantasy Novel. 
Miéville has described the book as "a dark comedy about a squid-worshipping cult and the end of the world. It takes the idea of the squid cult very seriously. Part of the appeal of the fantastic is taking ridiculous ideas very seriously and pretending they’re not absurd."', 481, 971, 2010, 295020, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('1Q84: Book 1', 'Haruki Murakami', '8779559204', 'https://assets.hardcover.app/editions/28310660/7690577800292837.jpeg', 'The year is 1984. Aomame sits in a taxi on the expressway in Tokyo. Her work is not the kind which can be discussed in public but she is in a hurry to carry out an assignment and, with the traffic at a stand-still, the driver proposes a solution. She agrees, but as a result of her actions starts to feel increasingly detached from the real world.

Meanwhile, Tengo is leading a nondescript life but wishes to become a writer. He inadvertently becomes involved in a strange affair surrounding a literary prize to which a mysterious seventeen-year-old girl has submitted her remarkable first novel. Can her story really be true?', 560, null, 2009, 444788, (select id from series where hardcover_id = 1116), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Specials', 'Scott Westerfeld', '0439025664', 'https://assets.hardcover.app/editions/30403684/967262916349874.jpg', 'Tally has become one of them: a super-amped fighting machine, engineered to keep the Uglies down and the Pretties stupid. But one tiny corner of Tally''s heart remembers something different.', 384, null, 2006, 248133, (select id from series where hardcover_id = 5729), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Plot Against America', 'Philip Roth', '150469368X', 'https://assets.hardcover.app/external_data/60618448/0881698eed9087a4a3b035448baf41af0b8f05cb.jpeg', 'The Plot Against America is a novel by Philip Roth published in 2004. It is an alternative history in which Franklin D. Roosevelt is defeated in the presidential election of 1940 by Charles Lindbergh. The novel follows the fortunes of the Roth family during the Lindbergh presidency, as antisemitism becomes more accepted in American life and Jewish-American families like the Roths are persecuted on various levels. The narrator and central character in the novel is the young Philip, and the care with which his confusion and terror are rendered makes the novel as much about the mysteries of growing up as about American politics. Roth based his novel on the isolationist ideas espoused by Lindbergh in real life as a spokesman for the America First Committee, and on his own experiences growing up in Newark, New Jersey. The novel received praise for the realism of its world and its treatment of topics such as antisemitism, trauma, and the perception of history. The novel depicts the Weequahic section of Newark which includes Weequahic High School from which Roth graduated.

In 2005, the novel won the James Fenimore Cooper Prize for Best Historical Fiction given by the Society of American Historians. It won the Sidewise Award for Alternate History, was a finalist for the John W. Campbell Memorial Award, and came in 11th for the 2005 Locus Awards.', 418, null, 2004, 159874, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Young Elites', 'Marie Lu', '0141370696', 'https://assets.hardcover.app/edition/30399904/69a4838d06c7983032f41d4c6c58709e6364f238.jpeg', 'I am tired of being used, hurt, and cast aside.

Adelina Amouteru is a survivor of the blood fever. A decade ago, the deadly illness swept through her nation. Most of the infected perished, while many of the children who survived were left with strange markings. Adelina’s black hair turned silver, her lashes went pale, and now she has only a jagged scar where her left eye once was. Her cruel father believes she is a malfetto, an abomination, ruining their family’s good name and standing in the way of their fortune. But some of the fever’s survivors are rumored to possess more than just scars—they are believed to have mysterious and powerful gifts, and though their identities remain secret, they have come to be called the Young Elites.

Teren Santoro works for the king. As Leader of the Inquisition Axis, it is his job to seek out the Young Elites, to destroy them before they destroy the nation. He believes the Young Elites to be dangerous and vengeful, but it’s Teren who may possess the darkest secret of all. 

Enzo Valenciano is a member of the Dagger Society. This secret sect of Young Elites seeks out others like them before the Inquisition Axis can. But when the Daggers find Adelina, they discover someone with powers like they’ve never seen. 

Adelina wants to believe Enzo is on her side, and that Teren is the true enemy. But the lives of these three will collide in unexpected ways, as each fights a very different and personal battle. But of one thing they are all certain: Adelina has abilities that shouldn’t belong in this world. A vengeful blackness in her heart. And a desire to destroy all who dare to cross her.

It is my turn to use. My turn to hurt.', 370, null, 2014, 135712, (select id from series where hardcover_id = 4679), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Who Fears Death', 'Nnedi Okorafor', '075640617X', 'https://assets.hardcover.app/edition/30400847/f657b7a7fd5c5f3751691b9c5536d1ca0f560aaa.jpeg', 'In a far future, post-nuclear-holocaust Africa, genocide plagues one region. The aggressors, the Nuru, have decided to follow the Great Book and exterminate the Okeke. But when the only surviving member of a slain Okeke village is brutally raped, she manages to escape, wandering farther into the desert. She gives birth to a baby girl with hair and skin the color of sand and instinctively knows that her daughter is different. She names her daughter Onyesonwu, which means "Who Fears Death?" in an ancient African tongue.

Reared under the tutelage of a mysterious and traditional shaman, Onyesonwu discovers her magical destiny – to end the genocide of her people. The journey to fulfill her destiny will force her to grapple with nature, tradition, history, true love, the spiritual mysteries of her culture – and eventually death itself.', 386, null, 2010, 197936, (select id from series where hardcover_id = 5537), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Test', 'Sylvain Neuvel', '1250312825', 'https://assets.hardcover.app/external_data/59522820/54b22b947610c3be4481282bff9340e632094e42.jpeg', 'Award-winning author Sylvain Neuvel explores an immigration dystopia in The Test Britain, the not-too-distant future. Idir is sitting the British Citizenship Test. He wants his family to belong. Twenty-five questions to determine their fate. Twenty-five chances to impress. When the test takes an unexpected and tragic turn, Idir is handed the power of life and death. How do you value a life when all you have is multiple choice?', 112, null, 2019, 427916, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Aurora Rising', 'Alastair Reynolds', '8834722469', 'https://assets.hardcover.app/edition/30546145/7a123a2ba856fb787503a231efee22c4f88b0a5b.jpeg', 'Tom Dreyfus is a Prefect, a law enforcement officer with the Panoply.
His beat is the multifaceted utopian society of the Glitter Band, that vast swirl of space habitats orbiting the planet Yellowstone, the teeming hub of a human interstellar empire spanning many worlds.
His current case: investigating a murderous attack against one of the habitats that left 900 people dead, a crime that appalls even a hardened cop like Dreyfus. But then his investigation uncovers something far more serious than mass slaughter---a covert plot by an enigmatic entity who seeks nothing less than total control of the Glitter Band.
Before long, the Panoply detectives are fighting against something worse than tyranny, in a struggle that will lead to more devastation and more death. And Dreyfus will discover that to save what is precious, you may have to destroy it.', 528, null, 2007, 581444, (select id from series where hardcover_id = 8102), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Changeling', 'Victor LaValle', '1524722553', 'https://assets.hardcover.app/edition/25737346/d2a96da84216ef86f5f0ef7da4de2e0fdc0e3b20.jpeg', '"The wildly imaginative story of one man''s thrilling odyssey through an enchanted world to find his wife, who has disappeared after having seemingly committed an unforgivable act of violence, from the award-winning author of The Devil in Silver and Big Machine"--

"Apollo Kagwa has had strange dreams that have haunted him since childhood. An antiquarian book dealer with a business called Improbabilia, he is just beginning to settle into his new life as a committed and involved father, unlike his own father who abandoned him, when his wife Emma begins acting strange. Disconnected and uninterested in their new baby boy, Emma at first seems to be exhibiting all the signs of post-partum depression, but it quickly becomes clear that her troubles go far beyond that. Before Apollo can do anything to help, Emma commits a horrific act--beyond any parent''s comprehension--and vanishes, seemingly into thin air. Thus begins Apollo''s odyssey through a world he only thought he understood to find a wife and child who are nothing like he''d imagined. His quest begins when he meets a mysterious stranger who claims to have information about Emma''s whereabouts. Apollo then begins a journey that takes him to a forgotten island in the East River of New York City, a graveyard full of secrets, a forest in Queens where immigrant legends still live, and finally back to a place he thought he had lost forever. This dizzying tale is ultimately a story about family and the unfathomable secrets of the people we love"--', 449, null, 2017, 428223, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blood of the Fold', 'Terry Goodkind', '1608475514', 'https://assets.hardcover.app/edition/26967787/8785ecdebc6c21e1254eae1a8174c216d28467fb.jpeg', 'After escaping from the Palace of Prophets, Richard comes to terms with his true identity as a War Wizard. But when he brings down the barrier between the Old and New Worlds, the Imperial Order suddenly poses a threat to the the freedom of all humankind. As the Imperial Order sends delegations and armies into the New World, Richard’s only chance to stop the invasion is to claim his heritage as the new Lord Rahl and ruler of D’Hara. 
 
But convincing the D’Harans of his legitimacy won’t be easy. Meanwhile, a powerful enemy is on the trail of Richard’s love, Kahlan Amnell. And when the spell Richard cast to protect her is broken, he must martial his newfound authority—and the armies that come with it—to save her life.', 645, null, 1996, 362928, (select id from series where hardcover_id = 1078), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Club Dead', 'Charlaine Harris', '8711411090', 'https://assets.hardcover.app/edition/3543780/38ca10f2c789250d6ebcb39cd4e2b41c6a3cf2a4.jpeg', 'There’s only one vampire Sookie Stackhouse is involved with (at least voluntarily) and it’s Bill Compton. But recently he’s been a little distant—in another state, distant. Then his sinister and sexy boss Eric Northman tells Sookie where she might find him. Next thing she knows, she’s off to Jackson, Mississippi, to mingle with the under-underworld at Club Dead, a dangerous little haunt where the elite of vampire society can go to chill out and suck down some Type-O. But when Sookie finally finds Bill—caught in an act of serious betrayal—she’s not sure whether to save him...or sharpen some stakes.', 288, null, 2003, 437948, (select id from series where hardcover_id = 5512), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wisteria Society of Lady Scoundrels', 'India Holton', '0593200179', 'https://assets.hardcover.app/external_data/2479120/d6d82e3b40d9116fc7f5dc87b817a9d755e4eb3b.jpeg', 'Cecilia Bassingwaite is the ideal Victorian lady. She’s also a thief. Like the other members of the Wisteria Society crime sorority, she flies around England drinking tea, blackmailing friends, and acquiring treasure by interesting means. Sure, she has a dark and traumatic past and an overbearing aunt, but all things considered, it’s a pleasant existence. Until the men show up.

Ned Lightbourne is a sometimes assassin who is smitten with Cecilia from the moment they meet. Unfortunately, that happens to be while he’s under direct orders to kill her. His employer, Captain Morvath, who possesses a gothic abbey bristling with cannons and an unbridled hate for the world, intends to rid England of all its presumptuous women, starting with the Wisteria Society. Ned has plans of his own. But both men have made one grave mistake. Never underestimate a woman.

When Morvath imperils the Wisteria Society, Cecilia is forced to team up with her handsome would-be assassin to save the women who raised her–hopefully proving, once and for all, that she’s as much of a scoundrel as the rest of them.', 336, 603, 2021, 428571, (select id from series where hardcover_id = 1194), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sins of Empire', 'Brian McClellan', '0316407224', 'https://assets.hardcover.app/external_data/25936428/58c9d0fa3b2cd372df29025fdf15a27e4f266520.jpeg', 'A new epic fantasy series from highly acclaimed fantasy author, Brian McClellan, set in the same world as The Powder Mage trilogy. A world on the cusp of a new age... The young nation of Fatrasta is a turbulent place -- a frontier destination for criminals, fortune-hunters, brave settlers, and sorcerers seeking relics of the past. Only the iron will of the lady chancellor and her secret police holds the capital city of Landfall together against the unrest of an oppressed population and the machinations of powerful empires. Sedition is a dangerous word... The insurrection that threatens Landfall must be purged with guile and force, a task which falls on the shoulders of a spy named Michel Bravis, convicted war hero Mad Ben Styke, and Lady Vlora Flint, a mercenary general with a past as turbulent as Landfall''s present. The past haunts us all... As loyalties are tested, revealed, and destroyed, a grim specter as old as time has been unearthed in this wild land, and the people of Landfall will soon discover that rebellion is the least of their worries. For more from Brian McClellan, check out: The Powder Mage Trilogy Promise of Blood The Crimson Campaign The Autumn Republic', 624, 1226, 2017, 467520, (select id from series where hardcover_id = 2348), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Heir', 'Kiera Cass', '222118775X', 'https://assets.hardcover.app/editions/30399826/f5a31db0-f58b-44cd-8447-fb431f8a6444.jpg', 'Princess Eadlyn has grown up hearing endless stories about how her mother and father met. Twenty years ago, America Singer entered the Selection and won the heart of Prince Maxon - and they lived happily ever after. Eadlyn has always found their fairy-tale story romantic, but she has no interest in trying to repeat it. If it were up to her, she''d put off marriage for as long as possible.

But a princess''s life is never entirely her own, and Eadlyn can''t escape her very own Selection—no matter how fervently she protests.

Eadlyn doesn''t expect her story to end in romance. But as the competition begins, one entry may just capture Eadlyn''s heart, showing her all the possibilities that lie in front of her . . . and proving that finding her own happily ever after isn''t as impossible as she''s always thought.', 342, null, 2015, 58916, (select id from series where hardcover_id = 1545), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Futuristic Violence and Fancy Suits', 'David Wong, Jason Pargin', '1518210430', 'https://assets.hardcover.app/editions/28676647/5eea125f-0f49-449a-a29b-df896533ca2f.jpg', 'New York Times bestselling author Jason Pargin takes readers to a whole new level with his darkly comic sci-fi thriller.

A Winner of the 2016 Alex Awards

Get ready for a world in which anyone can have the powers of a god or the fame of a pop star, in which human achievement soars to new heights while its depravity plunges to the blackest depths. A world in which at least one cat smells like a seafood shop''s dumpster on a hot summer day.

This is the world in which Zoey Ashe finds herself, navigating a futuristic city in which one can find elements of the fantastic, nightmarish and ridiculous on any street corner. Her only trusted advisor is the aforementioned cat, but even in the future, cats cannot give advice. At least not any that you''d want to follow.

Will Zoey figure it all out in time? Or maybe the better question is, will you? After all, the future is coming sooner than you think.', 384, 939, 2015, 31210, (select id from series where hardcover_id = 6822), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('On the Calculation of Volume (Book I)', 'Solvej Balle, Barbara J. Haveland', '0571383394', 'https://assets.hardcover.app/edition/31587092/87ad151b8936a6b0c71ebeb25dd1e3a9c1aca925.jpeg', 'She no longer expects to wake up to the 19th of November, and she no longer remembers the 17th of November as if it were yesterday. She comes to know the shape of the day like the back of her hand – the grey morning light in her Paris hotel; the moment a blackbird breaks into song; her husband’s surprise at seeing her return home unannounced.  

But for everyone around her, this day is lived for the first and only time. They do not remember the other 18ths of November, and they do not believe her when she tries to explain. 

As Tara approaches her 365th 18th of November, she can’t shake the feeling that somewhere underneath the surface of this day, there’s a way to escape. 

<i>On the Calculation of Volume I</i> was shortlisted for the International Booker Prize 2025, announced on April 8 2025.', 160, 280, 2020, 1801896, (select id from series where hardcover_id = 56475), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Book of the New Sun', 'Gene Wolfe', '1568658079', 'https://assets.hardcover.app/editions/22707427/5850141771547750.jpg', 'Contains 4 books in one volume: The Shadow of the Torturer (winner of the 1981 World Fantasy Award), The Claw of the Conciliator (winner of the 1982 Nebula Award), The Sword of the Lictor and The Citadel of the Autarch. Blending the lyric extravagance of fantasy and the keen edge of science fiction, The Book of the New Sun weaves a powerful tapestry of awesome terror and dreamlike beauty. It begins in a future so distant our civilization is no longer even a memory, and the remnants of our science seem like magical forces. It is a time when the Sun is dying, and legend speaks of the return of the Conciliator, who will bring about the birth of the New Sun. It is an odyssey fraught with monsters and mysteries and woven about with strange portents.', 950, null, 1980, 445503, (select id from series where hardcover_id = 1172), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Landline', 'Rainbow Rowell', '1250049377', 'https://assets.hardcover.app/edition/8465953/67983f3eb449460b103dbb0b0e7146864211ff26.jpeg', '"Two days before they''re supposed to visit his family in Omaha for Christmas, TV writer Georgie McCool tells her husband, Neal, that she has to stay in Los Angeles. She knows Neal will be upset -- but she doesn''t expect him to pack up the kids and go without her. That night, Georgie discovers a way to communicate with Neal in the past. Is this an opportunity to fix her marriage before it starts...or should it never have happened?"--', 319, null, 2014, 28114, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Children of Strife', 'Adrian Tchaikovsky', '1035057816', 'https://assets.hardcover.app/book/1974594/2b376943-f9c3-492d-b7ec-f863e241b58b.jpg', 'After Earth fell, ark ships hunted for a new home. They sought lost worlds terraformed in Earth’s forgotten past. A ship crewed by maverick humans, spiders and a spectacularly punchy mantis shrimp captain is about to rediscover one such world, and an ark.

Then human crewmate Alis wakes to discover that she, her captain and the ship’s intelligence are the only ones left on their ship.

But what happened to those who left to explore the ark ... and the world below?', 704, 1210, 2026, 1974594, (select id from series where hardcover_id = 1017), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Beautifully Foolish Endeavor', 'Hank Green', '8380743849', 'https://assets.hardcover.app/external_data/540386/827ab96d63e2f91136ffb70839e47e1e7a47fa8e.jpeg', 'April May and the Carls are back in the much-anticipated sequel to Hank Green''s #1 New York Times bestselling debut novel, An Absolutely Remarkable Thing.

The Carls disappeared the same way they appeared, in an instant. While they were on Earth, they caused confusion and destruction without ever lifting a finger. Well, that’s not exactly true. Part of their maelstrom was the sudden viral fame and untimely death of April May: a young woman who stumbled into Carl’s path, giving them their name, becoming their advocate, and putting herself in the middle of an avalanche of conspiracy theories.

Months later, the world is as confused as ever. Andy has picked up April’s mantle of fame, speaking at conferences and online about the world post-Carl; Maya, ravaged by grief, begins to follow a string of mysteries that she is convinced will lead her to April; and Miranda infiltrates a new scientific operation . . . one that might have repercussions beyond anyone’s comprehension.

As they each get further down their own paths, a series of clues arrive—mysterious books that seem to predict the future and control the actions of their readers; unexplained internet outages; and more—which seem to suggest April may be very much alive. In the midst of the gang''s possible reunion is a growing force, something that wants to capture our consciousness and even control our reality.

A Beautifully Foolish Endeavor is the bold and brilliant follow-up to An Absolutely Remarkable Thing. It’s a fast-paced adventure that is also a biting social commentary, asking hard, urgent questions. How will we live online? What powers over our lives are we giving away for free? Who has the right to change the world forever? And how do we find comfort in an increasingly isolated world?', 466, 946, 2020, 468134, (select id from series where hardcover_id = 1186), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Leech', 'Hiron Ennes', '1250811201', 'https://assets.hardcover.app/external_data/4066705/cec9c6f6df83b44a79682852bc7f4d2cc2ea6fdf.jpeg', 'In an isolated chateau, as far north as north goes, the baron’s doctor has died. The doctor’s replacement has a mystery to solve: discovering how the Institute lost track of one of its many bodies.

For hundreds of years the Interprovincial Medical Institute has grown by taking root in young minds and shaping them into doctors, replacing every human practitioner of medicine. The Institute is here to help humanity, to cure and to cut, to cradle and protect the species from the apocalyptic horrors their ancestors unleashed.

In the frozen north, the Institute''s body will discover a competitor for its rung at the top of the evolutionary ladder. A parasite is spreading through the baron''s castle, already a dark pit of secrets, lies, violence, and fear. The two will make war on the battlefield of the body. Whichever wins, humanity will lose again.', 317, 787, 2022, 511650, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Twelve', 'Justin Cronin', '0345504984', 'https://assets.hardcover.app/edition/15676077/7261041-L.jpg', 'In the present day, as the man-made apocalypse unfolds, three strangers navigate the chaos. Lila, a doctor and an expectant mother, is so shattered by the spread of violence and infection that she continues to plan for her child’s arrival even as society dissolves around her. Kittridge, known to the world as “Last Stand in Denver,” has been forced to flee his stronghold and is now on the road, dodging the infected, armed but alone and well aware that a tank of gas will get him only so far. April is a teenager fighting to guide her little brother safely through a landscape of death and ruin. These three will learn that they have not been fully abandoned—and that in connection lies hope, even on the darkest of nights.
 
One hundred years in the future, Amy and the others fight on for humankind’s salvation . . . unaware that the rules have changed. The enemy has evolved, and a dark new order has arisen with a vision of the future infinitely more horrifying than man’s extinction. If the Twelve are to fall, one of those united to vanquish them will have to pay the ultimate price.
 
A heart-stopping thriller rendered with masterful literary skill, The Twelve is a grand and gripping tale of sacrifice and survival.', 592, 1584, 2012, 440995, (select id from series where hardcover_id = 5550), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Smoke and Mirrors: Short Fiction and Illusions', 'Neil Gaiman', '061349458X', 'https://assets.hardcover.app/edition/16792518/a15695ea840989cfb2d29313815ca7b8e648e0cb.jpeg', '"En las manos maestras de Neil Gaiman, la magia es mucho más que un mero juego de engaños. La destreza y el poder de invención de este gran fabulador transforman el entorno cotidiano en un mundo hechizado por sucesos sombríos y extraños, en el que una anciana puede comprar el Santo Grial en una tienda de segunda mano, unos asesinos se anuncian en los clasificados de un periódico bajo la rúbrica ±CONTROL DE PLAGAS¬, o un muchacho asustado debe negociar con un trol malcarado y mezquino que vive bajo un puente ferroviario. Esta recopilación de treinta relatos, poemas narrativos y piezas breves e inclasificables ofrece múltiples y variadas posibilidades para que el lector explore una realidad transformada, astutamente velada por el humo y las sombras, a la vez que tangible y afilada. Todo parece posible en el universo de Gaiman, el gran maestro prestidigitador que despierta los sentidos, cautiva los sueños y mantiene en vilo nuestra mente."--', 356, 636, 1998, 50931, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Broken Kingdoms', 'N. K. Jemisin', '0316075981', 'https://assets.hardcover.app/edition/20878878/67798a080ade19cd051a1e117c6d4bf43888d4ae.jpeg', 'A man with no memory of his past and a struggling, blind street artist will face off against the will of the gods as the secrets of this stranger''s past are revealed in the sequel to The Hundred Thousand Kingdoms, the debut novel of NYT bestselling author N. K. Jemisin. In the city of Shadow, beneath the World Tree, alleyways shimmer with magic and godlings live hidden among mortalkind. Oree Shoth, a blind artist, takes in a strange homeless man on an impulse. This act of kindness engulfs Oree in a nightmarish conspiracy. Someone, somehow, is murdering godlings, leaving their desecrated bodies all over the city. And Oree''s guest is at the heart of it. . .', 384, null, 2010, 430979, (select id from series where hardcover_id = 1375), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Short Second Life of Bree Tanner', 'Stephenie Meyer', '754481422X', 'https://assets.hardcover.app/edition/30403616/91cbd33b-2388-418b-8c7c-00487b3bb58e.jpg', 'Fans of The Twilight Saga will be enthralled by this riveting story of Bree Tanner, a character first introduced in Eclipse, and the darker side of the newborn vampire world she inhabits. In another irresistible combination of danger, mystery, and romance, Stephenie Meyer tells the devastating story of Bree and the newborn army as they prepare to close in on Bella Swan and the Cullens, following their encounter to its unforgettable conclusion.', 178, null, 2005, 203705, (select id from series where hardcover_id = 5451), 3.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Deep', 'Nick Cutter', '1529452635', 'https://assets.hardcover.app/external_data/22783780/385b2d2983b8898fe498ce6fe4ec6117f0454f47.jpeg', '"A strange plague called the ''Gets is decimating humanity on a global scale. It causes people to forget--small things at first, like where they left their keys...then the not-so-small things like how to drive, or the letters of the alphabet. Then their bodies forget how to function involuntarily...and there is no cure. But now, far below the surface of the Pacific Ocean, deep in the Marianas Trench, an heretofore unknown substance hailed as "ambrosia" has been discovered--a universal healer, from initial reports. It may just be the key to a universal cure. In order to study this phenomenon, a special research lab, the Trieste, has been built eight miles under the sea''s surface. But now the station is incommunicado, and it''s up to a brave few to descend through the lightless fathoms in hopes of unraveling the mysteries lurking at those crushing depths..."--', 416, 267, 2015, 201254, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('More Than This', 'Patrick Ness', '1406350478', 'https://assets.hardcover.app/external_data/39831611/1e88641c3fa28038063bcde6becc9b4030338d15.jpeg', 'A boy called Seth drowns, desperate and alone in his final moments, losing his life as the pounding sea claims him. But then he wakes. How is that possible? And where is this place? It looks like the suburban English town where he lived as a child, before an unthinkable tragedy happened and his family moved to America. But the neighbourhood around his old house is overgrown, covered in dust and completely abandoned. What''s going on?', 480, 663, 2013, 428676, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fledgling', 'Octavia E. Butler', '0792748115', 'https://assets.hardcover.app/external_data/60027030/12257d86bd9c59c713b850f319fa6eab2330615a.jpeg', 'Fledgling, Octavia Butler’s last novel, is the story of an apparently young, amnesiac girl whose alarmingly un-human needs and abilities lead her to a startling conclusion: she is in fact a genetically modified, 53-year-old vampire. Forced to discover what she can about her stolen former life, she must at the same time learn who wanted—and still wants—to destroy her and those she cares for, and how she can save herself. Fledgling is a captivating novel that tests the limits of “otherness” and questions what it means to be truly human.', 320, 742, 2005, 293060, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Seraphina', 'Rachel Hartman', '0375966560', 'https://assets.hardcover.app/external_data/179130/0094bc348aed5431dcbffbbcb1149e35285849e6.jpeg', 'Lyrical, imaginative, and wholly original, this New York Times bestseller with 8 starred reviews is not to be missed. Rachel Hartman’s award-winning debut will have you looking at dragons as you’ve never imagined them before… Seraphina is a half-dragon, descended from a dragon mother who took human form and a father who has no particular fondness for Seraphina’s kind. Not that anyone else does either. Hers is a world where dragons and humans live and work side by side—but below the surface, tensions and hostilities are on the rise. Seraphina guards her true self with all of her being, but when a member of the royal family is brutally murdered, she’s suddenly thrust into the spotlight, drawn into the investigation alongside the dangerously perceptive Prince Lucian. As the two uncover a sinister plot to destroy the wavering peace of the kingdom, Seraphina’s struggle to protect her secret becomes increasingly difficult . . . and its discovery could mean her very life. "Will appeal to both fans of Christopher Paolini’s Eragon series and Robin McKinley’s The Hero and the Crown."—Entertainment Weekly “[A] lush, intricately plotted fantasy.”—The Washington Post "Beautifully written. Some of the most interesting dragons I''ve read."—Christopher Paolini, New York Times bestselling author of Eragon Meet Seraphina’s sister, Tess, in Rachel Hartman’s brand new fantasy adventure, Tess of the Road.', 528, null, 2012, 456758, (select id from series where hardcover_id = 6009), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Beneath the Sugar Sky', 'Seanan McGuire', '1643585274', 'https://assets.hardcover.app/edition/30400864/83ff6598053be63f3563fabb72b4a9ac4805f8e5.jpeg', 'A glorious fantasy tale from Seanan McGuire''s Alex-award winning Wayward Children series, which began in the Alex, Hugo, Nebula, and Locus Award-winning, World Fantasy Award finalist, Tiptree Honor List Every Heart a Doorway

Beneath the Sugar Sky, the third book in McGuire''s Wayward Children series, returns to Eleanor West''s Home for Wayward Children in a standalone contemporary fantasy for fans of all ages. At this magical boarding school, children who have experienced fantasy adventures are reintroduced to the "real" world.

When Rini lands with a literal splash in the pond behind Eleanor West''s Home for Wayward Children, the last thing she expects to find is that her mother, Sumi, died years before Rini was even conceived. But Rini can’t let Reality get in the way of her quest – not when she has an entire world to save! (Much more common than one would suppose.)

If she can''t find a way to restore her mother, Rini will have more than a world to save: she will never have been born in the first place. And in a world without magic, she doesn’t have long before Reality notices her existence and washes her away. Good thing the student body is well-acquainted with quests...', 176, null, 2018, 87848, (select id from series where hardcover_id = 1638), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sand', 'Hugh Howey', '132876754X', 'https://assets.hardcover.app/edition/30399483/9f3af7f4ebe4fdbe3291c33a9511c0372c8e53ee.jpeg', 'The old world is buried. A new one has been forged atop the shifting dunes. Here in this land of howling wind and infernal sand, four siblings find themselves scattered and lost. Their father was a sand diver, one of the elite few who could travel deep beneath the desert floor and bring up the relics and scraps that keep their people alive. But their father is gone. And the world he left behind might be next.

Welcome to the world of Sand, a novel by New York Times best-selling author Hugh Howey. Sand is an exploration of lawlessness, the tale of a land ignored. Here is a people left to fend for themselves. Adjust your ker and take a last, deep breath before you enter.', 384, 522, 2014, 125810, (select id from series where hardcover_id = 28289), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Husbands', 'Holly Gramazio', '1784745359', 'https://assets.hardcover.app/external_data/1349888/afe1aa280e5ba25ca9946887c5187ea60086ef90.jpeg', 'When Lauren returns home to her flat in London late one night, she is greeted at the door by her husband, Michael. There’s only one problem—she’s not married. She’s never seen this man before in her life. But according to her friends, her much-improved decor, and the photos on her phone, they’ve been together for years.

As Lauren tries to puzzle out how she could be married to someone she can’t remember meeting, Michael goes to the attic to change a lightbulb and abruptly disappears. In his place, a new man emerges, and a new, slightly altered life re-forms around her. Realizing that her attic is creating an infinite supply of husbands, Lauren confronts the question: If swapping lives is as easy as changing a lightbulb, how do you know you’ve taken the right path? When do you stop trying to do better and start actually living?', 352, 630, 2024, 1083931, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Boy''s Life', 'Robert McCammon', '1560543264', 'https://assets.hardcover.app/edition/12323554/76352476045348ffd4b7f86d9d5ac8eb65e33acb.jpeg', 'Gift from Kansas City Library.', 840, null, 1991, 429957, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dead to the World', 'Charlaine Harris', '3423244747', 'https://assets.hardcover.app/edition/25302241/342bb74377aae77c8b1f1d42a0a0b894eb6d6fc2.jpeg', 'It''s not every day that you come across a naked man on the side of the road. That''s why cocktail waitress Sookie Stackhouse doesn''t just drive on by. Turns out the poor thing hasn''t a clue who he is, but Sookie does. It''s Eric the vampire - but now he''s a kinder, gentler Eric. And a scared Eric, because whoever took his memory now wants his life. Sookie''s investigation into who and why leads straight into a dangerous battle among witches, vampires, and werewolves. But a greater danger could be to Sookie''s heart - because this version of Eric is very difficult to resist.', 291, null, 2005, 53975, (select id from series where hardcover_id = 5512), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Four: A Divergent Collection', 'Veronica Roth', '9720047259', 'https://assets.hardcover.app/edition/31005941/a15dd628df6c75cf894510fab3d7af7b3a1c6ce5.jpeg', 'Two years before Beatrice Prior made her choice, the sixteen-year-old son of abnegation''s faction leader did the same. Tobias''s transfer to Dauntless is a chance to begin again. Here, he will not be called the name his parents gave him. Here, he will not let fear turn him into a cowering child.

Newly christened "Four," he discovers during initiation that he will succeed in Dauntless. Initiation is only the beginning, though; Four must claim his place in the Dauntless hierarchy. His decisions will affect future initiates as well as uncover secrets that could threaten his own future--and the future of the entire faction system.

Two years later, Four is poised to take action, but the course is still unclear. The first new initiate who jumps into the net might change all that. With her, the way to righting their world might become clear. With her, it might become possible to be Tobias once again.', 256, null, 2014, 981093, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Robopocalypse', 'Daniel H. Wilson', '902145484X', 'https://assets.hardcover.app/edition/31670719/fa8b8ca18e960d1b163ae2a0182d07c7e58cf90f.jpeg', 'A tale set in the near future finds the world thrown into chaos by rebelling artificial intelligences under the leadership of a murderous technology called Archos that kills its creator and takes over the global network, triggering an unprecedented united front among all human cultures', 347, null, 2011, 440327, (select id from series where hardcover_id = 5961), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ember Blade', 'Chris Wooding', '5907338091', 'https://assets.hardcover.app/edition/30385999/dafe632297597610e4dfd125ae4d56e37eef8742.jpeg', 'Empires rise, civilisations fall and one culture comes to subsume another. It''s the way of the world . . . sometimes ways of life are improved, sometimes they are not. But the progression of change is huge and - usually - unstoppable. In this story, the Ossian way of life is fading and the Dachen way is taking its place and Aren is comfortable with that. Even when his parents are accused of treason he supports the establishment and maintains there''s been some mistake . . . which is all it takes to get himself and his best friend arrested . . . Thrown into a prison mine they plan their escape - only to be overtaken by events when they''re rescued, and promptly find themselves in the middle of an ambush. By the time they''ve escaped, they''re unavoidably linked to Garric - their unwelcome saviour - and his quest to overturn to Dachen way of life. If they leave Garric now, they''ll be arrested or killed by their pursuers. If they turn him in, Garric will kill them. If they stay with him, they''ll be abetting a murderous quest they don''t believe in. There are no good options - but Aren will still have to choose a path . . . Designed to return to classic fantasy adventures and values, from a modern perspective, this is a fast-moving coming-of-age trilogy featuring a strong cast of diverse characters, brilliant set-pieces and a strong character and plot driven story.', 832, null, 2018, 468164, (select id from series where hardcover_id = 2860), 1) on conflict (hardcover_id) do nothing;
